window.__BOOK__ = {"meta":{"title_ar":"الأمير الصغير","title_zh":"小王子","author_ar":"أنطوان دو سانت إكزوبيري","author_zh":"安托万·德·圣埃克苏佩里","voice":"ar-AE-FatimaNeural (edge-tts)","ipa_note":"阿拉伯语读音为拉丁转写，供参考。","n_chapters":28,"n_paras":762,"n_sents":1635,"audio_paras":762},"chapters":[{"id":"ch00","title_ar":"إلى ليون وورث","title_en":"To Leon Werth","title_zh":"献词","paras":[{"id":"ch00p00","audio":"ch00p00.mp3","sents":[{"ar":"أطلب التسامح من الأطفال الذين قد يقرؤون هذا الكتاب لتحديد الكتاب لراشد.","zh":"请孩子们原谅我把这本书献给一位大人。","t":[103,6842]},{"ar":"لدي سبب جاد: هو أفضل صديق لي في العالم.","zh":"他是我世间最好的朋友。","t":[6842,11697]},{"ar":"لدي سبب آخر: هذا الكبير يفهم كل شيء، حتى كتب الأطفال.","zh":"这位大人洞察一切，即便是对孩子的书也能心领神会。","t":[11697,18382]},{"ar":"الأمير الصغير يعيش في فرنسا يعاني الجوع والبرد","zh":"他住在法国，忍饥受寒。","t":[18382,22342]},{"ar":"يحتاج إلى التشجيع.","zh":"他亟需慰藉。","t":[22342,24868]},{"ar":"إذا لم تكن هذه الأسباب كافية، سأهدي الكتاب للطفل الصغير الذي نشأ منه هذا البالغ. إن كل البالغين كانوا أطفالًا في يوم من الأيام، ولو أن قلة منهم يتذكرون ذلك. وهكذا أعدل الإهداء: إلى ليون وورث عندما كان صغيرًا. أنطوان دو سانت إكزوبيري 1944.","zh":"若这些理由仍不足够，我便将此书献予那位成人曾是的孩童。","t":[24868,47987]},{"ar":"كل الكبار كانوا أطفالًا يومًا ما، ولكن قلة منهم يتذكرون ذلك.","zh":"所有大人曾经都是孩子——尽管他们中的许多人已不记得。","t":[47987,58237]},{"ar":"إذًا، أُصحح الهديه: إلى ليون وورث عندما كان ولدًا صغيرًا. أنطوان دو سانت إكزوبيري ١٩٤٤.","zh":"因此，我将献词更正：献予列翁·维尔特，他曾是孩童时。","t":[58237,69368]}]}]},{"id":"ch01","title_ar":"الفصل الأول","title_en":"Chapter I","title_zh":"第 1 章","paras":[{"id":"ch01p00","audio":"ch01p00.mp3","sents":[{"ar":"ذات مرة، عندما كنت في السادسة من عمري، رأيت صورة جميلة في كتاب عن غابة بدائية، اسمه «قصص حقيقية من الطبيعة»، قد أظهرت ثعبانًا عظيمًا يبتلع حيوانًا.","zh":"六岁那年，我在一本名为《自然奇观》的书里，瞥见了一幅描绘原始森林的壮丽图画。","t":[103,15684]},{"ar":"صورة ثعبان يبتلع حيوانًا","zh":"这是一幅蟒蛇正在吞食动物的图画。","t":[15684,18105]},{"ar":"هذه نسخة من الرسم.","zh":"这是这幅画的复印件。","t":[18105,19986]}]},{"id":"ch01p01","audio":"ch01p01.mp3","sents":[{"ar":"الثعبان يلتهم الفريسة بأكملها دون مضغها.","zh":"书中记载：“蟒蛇将猎物整个吞下，不嚼就吞。”","t":[103,4855]},{"ar":"بعد ذلك لا يستطيعون الحركة ويغفون طوال ستة أشهر التي تحتاجونها للهضم.","zh":"它们便无法动弹，需在消化过程中沉睡六个月。","t":[4855,11553]}]},{"id":"ch01p02","audio":"ch01p02.mp3","sents":[{"ar":"تأملت بعمق، ثم، في مغامرات الغابة.","zh":"我沉思良久，对丛林奇遇心生遐想。","t":[103,4816]},{"ar":"وبعد بعض العمل بكرباس ملون، نجحت في رسم رسوماتي الأولى.","zh":"经过一番用彩色铅笔的练习，我终于完成了我的第一幅画。","t":[4816,11118]},{"ar":"رسمي الأول.","zh":"我的第一幅画。","t":[11118,13250]},{"ar":"هذا هو الشكل:","zh":"它看起来是这样的：","t":[13250,14474]}]},{"id":"ch01p03","audio":"ch01p03.mp3","sents":[{"ar":"عرضت عملي الفني على الكبار وسألتهم إن كان رسمي يثير الخوف فيهم.","zh":"我把我的杰作展示给大人看，问他们这幅画是否吓到了他们。","t":[103,5629]}]},{"id":"ch01p04","audio":"ch01p04.mp3","sents":[{"ar":"لكنهم أجابوا: \"مخيف؟\"","zh":"吓什么？","t":[103,2616]},{"ar":"لماذا يخاف أي شخص من قبعة؟","zh":"帽子有什么好怕的？","t":[2616,5247]}]},{"id":"ch01p05","audio":"ch01p05.mp3","sents":[{"ar":"رسمي لم يكن صورة قبعة.","zh":"我的画作并非帽子图。","t":[103,3500]},{"ar":"صورة ثعبان يُمتص فسحة الفيل","zh":"这是一幅蟒蛇消化大象的图画。","t":[3500,6184]},{"ar":"لكن لأن الكبار لم يتمكنوا من فهمها، رسمت رسمًا آخر: رسمت داخل الثعبان الضخم، حتى يتمكن الكبار من رؤيته بوضوح.","zh":"但既然大人们无法理解，我便又画了一张：我画了蟒蛇的内部，好让大人们能看得一清二楚。","t":[6184,17592]},{"ar":"إنهم دائمًا يحتاجون إلى تفسير الأشياء.","zh":"他们总需要有人给他们解释。","t":[17592,21618]},{"ar":"رسمي الثاني كان يبدو هكذا:","zh":"我的第二号画看起来是这样的：","t":[21618,24026]}]},{"id":"ch01p06","audio":"ch01p06.mp3","sents":[{"ar":"ثم نصحني الراشدون بالتخلي عن رسم الثعبان العظيم، سواء من الداخل أو من الخارج، وأن أكرس نفسي عوضًا عن ذلك للجغرافيا والتاريخ والحساب وعلم الصرف والنحو.","zh":"大人们这次则劝我放下对蟒蛇的描绘，无论是从内部还是外部，转而投身于地理、历史、算术和语法的学习。","t":[103,14526]},{"ar":"لذلك، في السادسة من عمري، تخليت عن ما كان قد يكون مهنة رائعة كرسام.","zh":"六岁那年，我便放弃了可能成为辉煌画家的生涯。","t":[14526,22408]},{"ar":"لقد شعرت باليأس من فشل رسمي الأول ورسمي الثاني.","zh":"我的第一幅画和第二幅画均以失败告终，令我心灰意冷。","t":[22408,27671]},{"ar":"البالغون لا يفهمون أي شيء بأنفسهم، ويصبح مرهقًا للأطفال أن يفسروا للأشياء لهم دائمًا.","zh":"大人自己永远不懂，孩子们总是不断地向他们解释，这实在令人厌烦。","t":[27671,35724]}]},{"id":"ch01p07","audio":"ch01p07.mp3","sents":[{"ar":"ثم اخترت مهنة أخرى وتعلمت قيادة الطائرات.","zh":"于是，我选择了另一门职业，学会了驾驶飞机。","t":[103,5184]},{"ar":"لقد صعدت الطائرة فوق كل أنحاء العالم، وحقاً الجغرافيا قد كانت مفيدة جدًا لي.","zh":"我驾驶飞机飞越了世界的各个角落；确实，地理学对我帮助极大。","t":[5184,13145]},{"ar":"بإعجاز العين يمكنني تمييز الصين من أريزونا","zh":"一目了然，便能分辨出中国与亚利桑那。","t":[13145,16553]},{"ar":"إذا غابت في الليل، هذه المعرفة قيمة.","zh":"若夜航迷失，此等知识便显宝贵。","t":[16553,19829]}]},{"id":"ch01p08","audio":"ch01p08.mp3","sents":[{"ar":"في مسار حياتي، مررت بعدد كبير من المواجهات مع أناس مهتمين بأمور هامة.","zh":"在这漫长的人生旅程中，我与众多关注重大事务的人们有过无数次的相遇。","t":[103,8118]},{"ar":"لقد عشت الكثير من الوقت بين البالغين.","zh":"我在成人世界中度过许多时光。","t":[8118,12197]},{"ar":"لقد رأيتُهم عن قرب، على مرأى مني.","zh":"我近距离地与他们亲密接触。","t":[12197,16276]},{"ar":"لم يتحسن رأيي فيهم كثيرًا.","zh":"我对他们的看法并未有多大改观。","t":[16276,18750]}]},{"id":"ch01p09","audio":"ch01p09.mp3","sents":[{"ar":"عندما ألتقي بأحد هؤلاء الذين يبدون لي على ما يرام بدينهم الحاد، أحاول تجربة عرض رسمي الأول الذي أحتفظ به دائمًا.","zh":"每当我遇到一个在我看来还算有洞察力的大人，我便尝试向他展示我始终保留的那幅《第一号画》。","t":[103,11211]},{"ar":"سأحاول معرفة، إذاً، إن كان هذا شخصاً يعي الحقيقة.","zh":"我试图探查，看这究竟是否是一个真正懂得理解的人。","t":[11211,17263]},{"ar":"لكن، من كان هو، أو هي، سيقول دائمًا: \"هذا هو القبعة.\"","zh":"但无论他是谁，他或她总是会说：“那是一顶帽子。”","t":[17263,23237]}]},{"id":"ch01p10","audio":"ch01p10.mp3","sents":[{"ar":"لن أتحدث مع ذلك الشخص عن الثعابين المضيقة أو الغابات الأصلية أو النجوم.","zh":"于是，我便不再与那个人谈论蟒蛇、原始森林或星星。","t":[103,6987]},{"ar":"أخفض من مستوى نفسي لتناسب مستواه.","zh":"我降低自己的身份以适应他。","t":[6987,10974]},{"ar":"أتحدث معه عن البريدج والجولف والسياسة وربطات العنق.","zh":"我与他说起桥牌、高尔夫、政治和领带。","t":[10974,16579]},{"ar":"كان الراشد سعيدًا جدًا بلقاء رجل مفكر بهذا الشكل.","zh":"这位大人对结识如此明理的人感到非常满意。","t":[16579,21092]}]}]},{"id":"ch02","title_ar":"الفصل الثاني","title_en":"Chapter II","title_zh":"第 2 章","paras":[{"id":"ch02p00","audio":"ch02p00.mp3","sents":[{"ar":"وهكذا عشت وحيدًا، من دون أي إنسان أستطيع التحدث إليه حقًا، إلى أن تعرضت لحادث في الصحراء الكبرى منذ ست سنوات.","zh":"于是，我独自一人生活，无人可倾诉衷肠，直至六年前，我的飞机在撒哈拉沙漠遭遇事故。","t":[103,11118]},{"ar":"شيء ما انكسر في محركي.","zh":"发动机里出了故障。","t":[11118,14224]},{"ar":"وبما أنني لم أكن أملك ميكانيكيًا ولا راكبًا، قررت أن أقوم بمحاولة إصلاح الماكينة بمفردي.","zh":"于是，身边既无机械师，又无乘客相伴，我便孤身一人尝试着艰难地修理。","t":[14224,23276]},{"ar":"كانت مسألة حياة أو موت بالنسبة لي: لم يكن لدي الماء الشروب الكافي لأكثر من أسبوع.","zh":"生死攸关，我仅有的饮用水只够维持一周。","t":[23276,31618]},{"ar":"في الليلة الأولى، نمت على الرمال، على بعد ألف ميل من أي مسكن بشري.","zh":"那第一夜，我便在千里之外、人迹罕至的沙地上安睡。","t":[31618,38776]},{"ar":"كنت معزولًا أكثر من بحار على طوافة في وسط المحيط، وقد تحطمت سفينته","zh":"我比孤舟在茫茫大海中的遇险者还要孤独。","t":[38776,45211]},{"ar":"وبالتالي يمكنك تخيل دهشتي عند شروق الشمس عندما استيقظت على صوت صغير غريب.","zh":"晨曦初露，那奇异的细小声音将我惊醒，我惊愕不已。","t":[45211,52684]},{"ar":"قال: - أرجوك... ارسم لي خروفًا. - ماذا؟ - ارسم لي خروفًا. قفزت وأنا مصعوق تمامًا فركت عيني، فتحتهما وأغلقتهما ونظرت بانتباه حولي. اكتشفت وجود صبي صغير غير عادي يراقبني بجدية. هنا أفضل رسم استطعت أن أرسمه له مؤخرًا. لكن رسمي بالطبع ليس بنصف روعة شخصه. إن هذا ليس خطئي؛ لقد أحبطني الكبار في مهنتي كرسام عندما كنت في السادسة من عمري، فلم أتعلم رسم شيء عدا حيات عاصرة من الخارج وحيات عاصرة من الداخل. ولذلك حدقت بدهشة تامة إلى هذا الشبح المفاجئ. لا تنس أنني كنت على بعد ألف ميل من أي منطقة سكنية. لكن الفتى الصغير لم يظهر أنه تائه أو منهك أو ميت من العطش والجوع، أو الخوف. لم يبد أنه طفل تائه في وسط الصحراء، على بعد ألف ميل من أي منطقة مأهولة. عندما تمكنت من الكلام أخيرًا، سألته: - لكن... ما الذي تفعله هنا؟ فأجاب برقة وجدية: - أرجوك ارسم لي خروفًا. عندما يكون اللغز طاغيًا بشدة، لا يجرؤ أحد على عدم الطاعة، ومع أن ذلك بدا لي سخيفًا وأنا أبعد ألف ميل عن أي مسكن بشري، تناولت ورقة وقلمي الحبر من جيبي، لكنني تذكرت فجأة أن دراساتي تركزت على الجغرافيا والتاريخ والحساب والنحو، فأخبرت الفتى الصغير (بغضب قليل) أنني لا أعرف كيف أرسم. أجاب: - لا بأس. ارسم لي خروفًا. وبما أنني لم أرسم خروفًا قط، رسمت له إحدى الصورتين اللتين رسمتهما من قبل: صورة الحيَّة العاصرة من الخارج. إليكم أفضل رسمة استطعت رسمها له بعد ذلك.. وقد دُهشت عندما سمعت المخلوق الصغير يقول: - لا! لا! لا أريد فيلًا في باطن حية، إن الحية العاصرة مخلوق خطير جدًّا، والفيل ثقيل جدًّا. إن كل شيء صغير جدًّا حيث أعيش. إنني بحاجة إلى خروف، ارسم لي خروفًا. وهكذا رسمت. نظر إليه بانتباه وقال: - لا. إن هذا الخروف سقيم جدًّا. ارسم لي خروفًا آخر. فرسمت. قال صديقي الصغير بلطف وتسامح: - ألا ترى أنه ليس خروفًا، إنه كبش. إن لديه قرونًا... ومرة أخرى رسمت رسمًا لكنه رفضه أيضًا كالرسمين السابقين. - إن هذا عجوز جدًّا. أريد خروفًا يعيش وقتًا طويلًا. عندئذ نفد صبري لأنني كنت في عجلة من أمري لأفكك محركي في أسرع وقت ممكن، وهكذا خربشت هذا الرسم. وأوضحت: - إن هذا ليس سوى الصندوق. إن الخروف الذي طلبته يوجد داخله. لكنني دهشت جدًّا لأرى وجه القاضي الصغير مشرقًا: - هذا تمامًا ما أردت. هل تظن أن هذا الخروف سيحتاج إلى الكثير من العشب؟ - لماذا؟ - لأنه حيث أعيش كل شيء صغير جدًّا... - لا بد أن هناك عشبًا كافيًا له؛ لقد أعطيتك خروفًا صغيرًا جدًّا. أحنى رأسه فوق الرسم وقال: - ليس صغيرًّا جدًّا كما... انظر! لقد خلد إلى النوم. وعلى هذا النحو التقيت الأميرالصغير.","zh":"它说：","t":[52684,300514]}]},{"id":"ch02p01","audio":"ch02p01.mp3","sents":[{"ar":"يرجى رسم لي خروفًا.","zh":"请给我画一只绵羊吧！","t":[103,1932]}]},{"id":"ch02p02","audio":"ch02p02.mp3","sents":[{"ar":"ماذا!","zh":"什么！","t":[103,735]}]},{"id":"ch02p03","audio":"ch02p03.mp3","sents":[{"ar":"يرسم لي خروفًا.","zh":"画只绵羊吧！","t":[103,1734]}]},{"id":"ch02p04","audio":"ch02p04.mp3","sents":[{"ar":"جئت إلى قدمي، مصعوق تمامًا كأنني تعرضت للصاعقة.","zh":"我惊得跳了起来，如遭雷击。","t":[103,5868]},{"ar":"أغرق عيني بصعوبة كبيرة.","zh":"我紧闭双眼，用力眨动。","t":[5868,9211]},{"ar":"نظرت حولي بعناية","zh":"我环顾四周，仔细打量。","t":[9211,10934]},{"ar":"ورأيت شخصًا صغيرًا غريبًا جدًا، يقف هناك يراني بجدية عظيمة.","zh":"我瞥见一个极为奇特的小人儿，他正一本正经地打量着我。","t":[10934,17776]},{"ar":"هنا يمكنكم رؤية أفضل رسم قمت بإنجازه له لاحقًا.","zh":"这里可见我后来为他画的最成功的肖像。","t":[17776,23408]},{"ar":"لكن رسمي بالطبع ليس بنصف روعة شخصه. إن هذا ليس خطئي؛ لقد أحبطني الكبار في مهنتي كرسام عندما كنت في السادسة من عمري، فلم أتعلم رسم شيء عدا حيات عاصرة من الخارج وحيات عاصرة من الداخل. ولذلك حدقت بدهشة تامة إلى هذا الشبح المفاجئ. لا تنس أنني كنت على بعد ألف ميل من أي منطقة سكنية. لكن الفتى الصغير لم يظهر أنه تائه أو منهك أو ميت من العطش والجوع، أو الخوف. لم يبد أنه طفل تائه في وسط الصحراء، على بعد ألف ميل من أي منطقة مأهولة.","zh":"但我的画作显然远不及它的原型迷人。","t":[23408,68106]}]},{"id":"ch02p05","audio":"ch02p05.mp3","sents":[{"ar":"هذا ليس خطئي","zh":"这并非我的过错。","t":[103,1366]},{"ar":"كان الكبار يمنعونني من مهنة الرسم عندما كنت في السادسة من عمري، ولم أتعلم رسم أي شيء، إلا من الخارج والintérieur الثعبان.","zh":"六岁那年，大人们便扼杀了我的画家梦想，我从未学会画任何东西，除了从外面看的蟒蛇和从里面看的蟒蛇。","t":[1366,11656]}]},{"id":"ch02p06","audio":"ch02p06.mp3","sents":[{"ar":"لقد نظرت إلى هذا الظهور المفاجئ بعينين قد بدأت تخرجان من رأسي من دهشة شديدة.","zh":"我惊愕地瞪大了眼睛，几乎要目不转睛地凝视着这个突如其来的身影。","t":[103,7882]},{"ar":"تذكر، لقد تحطمت في الصحراء على بعد ألف ميل من أي منطقة مأهولة.","zh":"记得，我在人烟稀少的沙漠中，千里之外遭遇了坠机。","t":[7882,14671]},{"ar":"وإلا بدا أن رجلي الصغير لم يكن يضل في الصحراء بلا اتجاه، ولا ينهار من الإرهاق أو الجوع أو العطش أو الخوف.","zh":"他似乎既不是在沙中迷失方向，也不是因疲惫、饥饿、口渴或恐惧而昏倒。","t":[14671,24461]},{"ar":"لم يكن في نفسه أي دليل على أن الطفل قد ضل في وسط الصحراء، بعيدًا عن أي مكان مأهول بألف ميل.","zh":"他身上丝毫没有在沙漠中迷失方向、远离人烟千里的孩子的痕迹。","t":[24461,33368]},{"ar":"عندما تمكنت أخيرًا من التحدث، قلت له:","zh":"终于开口说话，我对他说：","t":[33368,36815]}]},{"id":"ch02p07","audio":"ch02p07.mp3","sents":[{"ar":"لكن ماذا تفعل هنا؟","zh":"但——你在此做什么？","t":[103,1906]}]},{"id":"ch02p08","audio":"ch02p08.mp3","sents":[{"ar":"وهكذا أجاب ببطء، كما لو كان يتحدث عن أمر مهم جدًا:","zh":"他缓缓地回答，仿佛在谈论一件极重要的事情：","t":[103,5155]}]},{"id":"ch02p09","audio":"ch02p09.mp3","sents":[{"ar":"يرجى رسم لي خروفًا...","zh":"请给我画一只羊吧……","t":[103,1984]}]},{"id":"ch02p10","audio":"ch02p10.mp3","sents":[{"ar":"عندما يكون الغموض قوياً جدًا، لا أحد يجرؤ على عدم الطاعة.","zh":"当神秘的力量压倒一切，人不敢违抗。","t":[103,6171]},{"ar":"مضحكًا كما يبدو لي، بعيدًا عن أي مكان سكني بآلاف الأميال وفي خطر الموت، سحبت من جيبي ورقة ورسمة.","zh":"荒诞至极，远离人烟千里，生死攸关之际，我还是从口袋里掏出了一张纸和一支钢笔。","t":[6171,16474]},{"ar":"لكن بعد ذلك تذكرت كيف كانت دراستي مركزة على الجغرافيا، التاريخ، الحساب، والنحو، وقلت للطفل الصغير (وبألفاظ متوترة أيضًا) أنني لا أعرف كيف أرسم.","zh":"然而，我回想起我的学业专注于地理、历史、算术和语法，便有些不悦地对那个小家伙说，我不会画画。","t":[16474,32553]},{"ar":"قال لي:","zh":"他回答道：","t":[32553,33316]}]},{"id":"ch02p11","audio":"ch02p11.mp3","sents":[{"ar":"هذا لا يهم.","zh":"这无妨。","t":[103,2237]},{"ar":"يرجوك... أرسم لي خروفًا.","zh":"画一只羊吧……","t":[2237,5434]}]},{"id":"ch02p12","audio":"ch02p12.mp3","sents":[{"ar":"لم أرسم قط خروفًا.","zh":"但我从未画过羊。","t":[103,3026]},{"ar":"لذلك رسمت له واحدا من الصورتين اللتين رسمتهما مرارًا وتكرارًا.","zh":"于是，我为他画出了我常画的其中一幅。","t":[3026,9855]},{"ar":"هذا هو الثعبان من الخارج.","zh":"这是从外面看的蟒蛇。","t":[9855,13000]},{"ar":"وكنت مندهشًا عند سماع الصغير يحييها بهذا،","zh":"我惊愕地听见那小家伙对它说：","t":[13000,16540]}]},{"id":"ch02p13","audio":"ch02p13.mp3","sents":[{"ar":"لا، لا، لا!","zh":"不！不！不！","t":[103,761]},{"ar":"لا أريد ثعبانًا يحتوي على فيل.","zh":"我不想在蟒蛇肚子里有一只大象。","t":[761,6316]},{"ar":"الثعبان المضغوط هو مخلوق خطير جدًا، والأفاليس ثقيل جدًا.","zh":"蟒蛇极为危险，而大象又非常笨重。","t":[6316,9789]},{"ar":"حيث أعيش، كل شيء صغير جدًا.","zh":"在我居住的地方，一切都极小。","t":[9789,16711]},{"ar":"أنا بحاجة إلى خروف.","zh":"我需要的是一只羊。","t":[16711,19592]},{"ar":"يرسم لي خروفًا.","zh":"画一只羊吧。","t":[19592,21224]}]},{"id":"ch02p14","audio":"ch02p14.mp3","sents":[{"ar":"ثم رسمت رسمة.","zh":"于是，我画了一幅画。","t":[103,1603]}]},{"id":"ch02p15","audio":"ch02p15.mp3","sents":[{"ar":"نظر إليه بحذر، ثم قال:","zh":"他仔细端详着，然后说道：","t":[103,2918]}]},{"id":"ch02p16","audio":"ch02p16.mp3","sents":[{"ar":"لا!","zh":"不！","t":[103,1382]},{"ar":"الشاة هذه أصبحت مريضة جدًا بالفعل.","zh":"这羊已经病得很重了。","t":[1382,5579]},{"ar":"أرسم لي خروفًا آخر.","zh":"再给我画一个。","t":[5579,7381]}]},{"id":"ch02p17","audio":"ch02p17.mp3","sents":[{"ar":"وهكذا رسمت أخرى.","zh":"于是，我又画了一张。","t":[103,1944]}]},{"id":"ch02p18","audio":"ch02p18.mp3","sents":[{"ar":"صديقي ابتسم بلطف وتراحم.","zh":"我的朋友微笑着，既温柔又宽容。","t":[103,2813]}]},{"id":"ch02p19","audio":"ch02p19.mp3","sents":[{"ar":"هذا ليس خروفًا، إنه كبش.","zh":"这显然不是一只羊。","t":[103,3803]},{"ar":"هذا رام.","zh":"这是一只公羊。","t":[3803,5592]},{"ar":"إنه يملك قرونًا...","zh":"它长着角哩。","t":[5592,7355]}]},{"id":"ch02p20","audio":"ch02p20.mp3","sents":[{"ar":"ثم أعدت رسم رسوماتي مرة أخرى.","zh":"于是，我又重新画了一次。","t":[103,2971]}]},{"id":"ch02p21","audio":"ch02p21.mp3","sents":[{"ar":"لكنها رُفضت أيضًا، مثل الأخرى.","zh":"但这幅画也被拒绝了，就像其他那些一样。","t":[103,3063]}]},{"id":"ch02p22","audio":"ch02p22.mp3","sents":[{"ar":"هذا الطائر جدًّا قديم.","zh":"这只太老了。","t":[103,3013]},{"ar":"أريد خروفًا سيعيش طويلاً.","zh":"我要一只能活很久的羊。","t":[3013,5487]}]},{"id":"ch02p23","audio":"ch02p23.mp3","sents":[{"ar":"لقد استنفدت صبري لأنني كنت في عجلة من أمري لأبدأ في تفكيك محركي.","zh":"我的耐心已耗尽，急于开始拆卸我的发动机。","t":[103,6195]}]},{"id":"ch02p24","audio":"ch02p24.mp3","sents":[{"ar":"وهكذا ألهمت هذه الرسمة.","zh":"于是，我草草地画了这幅画。","t":[103,3171]},{"ar":"وهكذا، قمت بإلقاء تفسير مع ذلك.","zh":"于是，我随口解释道。","t":[3171,6723]}]},{"id":"ch02p25","audio":"ch02p25.mp3","sents":[{"ar":"هذا ليس إلا صندوقه.","zh":"这不过是他的一只箱子。","t":[103,2895]},{"ar":"الشاة التي طلبتها موجودة داخلها.","zh":"那你要的绵羊就在里面。","t":[2895,5921]}]},{"id":"ch02p26","audio":"ch02p26.mp3","sents":[{"ar":"أدهشني أن أرى ضوءًا يلمع على وجه قاضي صغيري:","zh":"我惊讶地看到，我的这位小法官脸上露出了光芒：","t":[103,3905]}]},{"id":"ch02p27","audio":"ch02p27.mp3","sents":[{"ar":"هذا تمامًا ما أردت!","zh":"这正是我想要的！","t":[103,2737]},{"ar":"هل تعتقد أن هذا الحمل سيحتاج إلى الكثير من العشب؟","zh":"这只绵羊需要很多草吗？","t":[2737,6868]}]},{"id":"ch02p28","audio":"ch02p28.mp3","sents":[{"ar":"لماذا؟","zh":"为什么？","t":[103,866]}]},{"id":"ch02p29","audio":"ch02p29.mp3","sents":[{"ar":"لأن حيث أعيش كل شيء صغير جدًا...","zh":"因为在我住的地方，一切都极小。","t":[103,3129]}]},{"id":"ch02p30","audio":"ch02p30.mp3","sents":[{"ar":"سيكون هناك أرض كافية له، قلت.","zh":"我说：“肯定够了。”","t":[103,4276]},{"ar":"هذا هو الشاة الصغيرة جدًا التي أعطيتها لك.","zh":"我给你的是一只很小很小的绵羊。","t":[4276,8118]}]},{"id":"ch02p31","audio":"ch02p31.mp3","sents":[{"ar":"أنحنى رأسه فوق الرسم:","zh":"他俯身细看那幅画。","t":[103,2024]}]},{"id":"ch02p32","audio":"ch02p32.mp3","sents":[{"ar":"ليس صغيرًا جدًا كما... انظر!","zh":"如此小巧，看哪！","t":[103,4447]},{"ar":"لقد غاب عن النوم...","zh":"它已经入睡……","t":[4447,6053]}]},{"id":"ch02p33","audio":"ch02p33.mp3","sents":[{"ar":"وهكذا تعرفت على الأمير الصغير.","zh":"就这样，我结识了小王子。","t":[103,2839]}]}]},{"id":"ch03","title_ar":"الفصل الثالث","title_en":"Chapter III","title_zh":"第 3 章","paras":[{"id":"ch03p00","audio":"ch03p00.mp3","sents":[{"ar":"استغرقت وقتًا طويلًا لأعرف من أين أتى.","zh":"我费了好长时间才弄清他来自何方。","t":[103,4289]},{"ar":"الأمير الصغير، الذي سألني الكثير من الأسئلة، لم يبد أنّه يسمع الأسئلة التي أطرحها عليه.","zh":"小王子虽向我提问无数，却似乎对我的问题充耳不闻。","t":[4289,13487]},{"ar":"من كلمات سقطت بغير قصد، شيئًا فشيئًا، كل شيء كشف لي.","zh":"偶然间的话语，渐渐向我揭示了所有真相。","t":[13487,19290]}]},{"id":"ch03p01","audio":"ch03p01.mp3","sents":[{"ar":"مثلاً، عندما رأى طائرتي أول مرة (لن أرسم طائرتي؛ إن ذلك معقد جدًا بالنسبة لي)، سألني: - ما هذا الشيء؟ - إنها ليست شيئًا. إنها تطير. إنها طائرة. إنها طائرتي. وكنت فخورًا لأنني أستطيع أن أخبره بأنني أستطيع الطيران. فهتف قائلًا: - ماذا؟! هبطت من السماء؟ أجبت بتواضع: - نعم. - أوه، هذا مضحك. وانفجر الأمير الصغير في رنين من الضحك اللطيف، الأمر الذي أزعجني كثيرًا. فأنا أحب أن تأخذ مصائبي بجدية. - إذن أنت أيضًا آت من السماء. من أي كوكب؟ وسرعان ما لاحظت شعاعًا من الضوء في وجوده الغامض، فسألته على الفور: - وأنت أيضًا آت من كوكب آخر؟ لكنه لم يجب. هز رأسه بلطف فيما كان يحدق إلى طائرتي. - الحقيقة أنه لا يمكن أن تكون قد أتيت من مكان بعيد جدًا على متن هذا. وغرق في تفكير عميق، ثم بعد أن تناول خروفي من جيبه، أخذ يتأمل في كنزه. يمكنك أن تتخيل كم أُثير فضولي بهذا النصف من الثقة بشأن « الكواكب الأخرى ». وهكذا حاولت أن أكتشف المزيد. - من أين أنت آت أيها المخلوق الصغير؟ أين هذه « حيث أعيش » التي تتحدث عنها؟ إلى أين تريد أن تأخذ خروفي؟ أجاب بعد استغراق في التفكير: - ما يعجبني في الصندوق الذي أعطيتني إياه أن باستطاعته أن يستخدمه كبيت له أثناء الليل. - طبعًا. وإن كنت صالحًا سأعطيك حبلًا تربطه به أثناء النهار، وعمودًا لتربطه إليه. بدا الأمير الصغير مصعوقًا من اقتراحي. - أربطه؟ يا لها من فكرة مضحكة! - لكن إن لم تربطه فإنه سيتجول ويضيع. انفجر صديقي بالضحك مرة أخرى: - لكن إلى أين سيذهب؟ - إلى أي مكان. سيهيم على وجهه. الأمير الصغير فوق كوكبه « ب ٦١٢ » عندئذ علق الأمير الصغير بجدية: - لا يهم، فكل شيء صغير جدًا حيث أعيش. (وربما بشيء من الدهاء أضاف قائلًا) لا يمكن للمرء أن يضيع إذا سار مستقيمًا...","zh":"例如，他头一回见到我的飞机时（我不愿画飞机，那太复杂了），便问我：","t":[103,169987]}]},{"id":"ch03p02","audio":"ch03p02.mp3","sents":[{"ar":"ما هذا الشئ؟","zh":"那是什么玩意儿？","t":[103,1076]}]},{"id":"ch03p03","audio":"ch03p03.mp3","sents":[{"ar":"ذلك ليس شيئًا.","zh":"那不是玩意儿。","t":[103,2539]},{"ar":"هي تطير.","zh":"它会飞。","t":[2539,4382]},{"ar":"هذا طائرة.","zh":"这是飞机。","t":[4382,6434]},{"ar":"هذا طائري.","zh":"这是我的飞机。","t":[6434,7606]}]},{"id":"ch03p04","audio":"ch03p04.mp3","sents":[{"ar":"كنت فخورًا بأنني أستطيع أن أعلّمه أنني أستطيع الطيران","zh":"我为他能知道我会飞而自豪。","t":[103,4537]}]},{"id":"ch03p05","audio":"ch03p05.mp3","sents":[{"ar":"أنفجر الأمل الصغير في صوت عالٍ، ثم:","zh":"他突然喊道：","t":[103,3602]}]},{"id":"ch03p06","audio":"ch03p06.mp3","sents":[{"ar":"ماذا؟!","zh":"怎么！","t":[103,1605]},{"ar":"من السماء هبطت؟","zh":"你是从天上掉下来的吗？","t":[1605,3105]}]},{"id":"ch03p07","audio":"ch03p07.mp3","sents":[{"ar":"نعم، أجبت بتبجيل.","zh":"是的，我谦逊地回答。","t":[103,2208]}]},{"id":"ch03p08","audio":"ch03p08.mp3","sents":[{"ar":"أوه!","zh":"啊！","t":[103,1526]},{"ar":"هذا مضحك!","zh":"这倒有趣！","t":[1526,2632]}]},{"id":"ch03p09","audio":"ch03p09.mp3","sents":[{"ar":"ثم انفجر الأمير الصغير في ضحك جميل، مما أزعجني كثيرًا.","zh":"那小王子突然发出一阵清脆的笑声，这笑声让我非常恼火。","t":[103,5934]},{"ar":"أود أن يُتخذ من مصائبي على محمل الجد.","zh":"我愿我的不幸得到认真对待。","t":[5934,9342]}]},{"id":"ch03p10","audio":"ch03p10.mp3","sents":[{"ar":"ثم أضاف:","zh":"他接着又说：","t":[103,1155]}]},{"id":"ch03p11","audio":"ch03p11.mp3","sents":[{"ar":"أنت أيضًا آت من السماء؟","zh":"你们也是从天上来的！","t":[103,3066]},{"ar":"هذا كوكبك؟","zh":"这是你的星球吗？","t":[3066,4224]}]},{"id":"ch03p12","audio":"ch03p12.mp3","sents":[{"ar":"في تلك اللحظة لاحظت ضوءاً يتلألأ في غموض وجوده؛ فسألت فجأة:","zh":"那一刻，我瞥见了他神秘身影中的光芒；于是，我突兀地问道：","t":[103,5734]}]},{"id":"ch03p13","audio":"ch03p13.mp3","sents":[{"ar":"هل تأتي من كوكب آخر؟","zh":"你们也是从另一个星球来的吗？","t":[103,2024]}]},{"id":"ch03p14","audio":"ch03p14.mp3","sents":[{"ar":"لم يرد.","zh":"他并未回答。","t":[103,1816]},{"ar":"أنطون دو سانت إكزوبيري الأبجدية العربية الأصلية: \nهذا المكان ليس مكانًا بعيدًا، إنه مكان صغير جدًا، لا يمكن أن يضيع المرء إذا سار مستقيمًا...","zh":"他轻轻摇晃着头，目光未离我的飞机。","t":[1816,15106]}]},{"id":"ch03p15","audio":"ch03p15.mp3","sents":[{"ar":"ذلك صحيح، لا يمكنك أن تأتي من مكان بعيد جدًا في هذا...","zh":"那确实，你不可能从很远处来到这里……","t":[103,5221]}]},{"id":"ch03p16","audio":"ch03p16.mp3","sents":[{"ar":"وانغمس في تأمل، استمر لفترة طويلة.","zh":"他陷入沉思，久久未能自拔。","t":[103,4816]},{"ar":"ثم، بعد أن أخرجت خروفي من جيبه، غرق في تأمل كنزه.","zh":"他掏出我的绵羊，便沉浸在心爱宝物的沉思之中。","t":[4816,10185]}]},{"id":"ch03p17","audio":"ch03p17.mp3","sents":[{"ar":"كانت فضولي محرّكًا بهذا الشك المتبادل فيما يتعلق بالكواكب الأخرى، لذا عملت بجد لمعرفة المزيد عن هذا الموضوع.","zh":"我好奇之心被他对“其他星球”的这种半信半疑所激起，因此我竭力想了解更多关于这个话题。","t":[103,9563]}]},{"id":"ch03p18","audio":"ch03p18.mp3","sents":[{"ar":"يا صغيري، من أي مكان تأتي؟","zh":"我的小家伙，你从哪里来？","t":[103,3908]},{"ar":"ما هذا 'أين أعيش' الذي تتحدث عنه؟","zh":"这“我住在哪里”，你所说的那是什么意思？","t":[3908,8105]},{"ar":"أين تريد أن تأخذ غنمك؟","zh":"你打算把你的绵羊带到哪里去？","t":[8105,10343]}]},{"id":"ch03p19","audio":"ch03p19.mp3","sents":[{"ar":"بعد صمت مليء بالتفكير، أجاب:","zh":"沉思片刻后，他回答道：","t":[103,3156]}]},{"id":"ch03p20","audio":"ch03p20.mp3","sents":[{"ar":"ما يعجبني في الصندوق الذي أعطيتني إياه أن باستطاعته أن يستخدمه كبيت له أثناء الليل.","zh":"这箱子你送给我真是太好了，夜里他可以用它做屋子。","t":[103,7352]}]},{"id":"ch03p21","audio":"ch03p21.mp3","sents":[{"ar":"هذا صحيح.","zh":"这倒是。","t":[103,2013]},{"ar":"إذا كنت صالحًا سأعطيك حبلاً لتقيده به أثناء النهار، وعمدة لتقيده إليها.","zh":"若你听话，我还会给你一根绳子，白天用来拴住它，再给你一个桩子。","t":[2013,8908]}]},{"id":"ch03p22","audio":"ch03p22.mp3","sents":[{"ar":"لكن الأمير الصغير بدا مذهولاً من هذا العرض:","zh":"小王子对这个提议似乎感到震惊：","t":[103,3406]}]},{"id":"ch03p23","audio":"ch03p23.mp3","sents":[{"ar":"ربطه!","zh":"拴住他！","t":[103,1737]},{"ar":"فكرة غريبة حقًا!","zh":"真是个古怪的主意！","t":[1737,3553]}]},{"id":"ch03p24","audio":"ch03p24.mp3","sents":[{"ar":"لكن إن لم تربطه، سيهيم في مكان ما ويضيع.","zh":"“可是，如果你不拴住他，”我说，“他会到处乱跑，然后走失的。”","t":[103,4142]}]},{"id":"ch03p25","audio":"ch03p25.mp3","sents":[{"ar":"صديقي انفجر في ضحك آخر:","zh":"我的朋友又爆发出一阵笑声：","t":[103,2589]}]},{"id":"ch03p26","audio":"ch03p26.mp3","sents":[{"ar":"لكن أين تظن أنه سيذهب؟","zh":"他以为它会跑到哪里去呢？","t":[103,2602]}]},{"id":"ch03p27","audio":"ch03p27.mp3","sents":[{"ar":"أينما كان","zh":"无论哪里。","t":[103,945]},{"ar":"فوق كوكبه \"ب ٦١٢\" عندئذ علق الأمير الصغير بجدية: - لا يهم، فكل شيء صغير جدًّا حيث أعيش. (وربما بشيء من الدهاء أضاف قائلًا) لا يمكن للمرء أن يضيع إذا سار مستقيمًا...","zh":"前方，就在他面前。","t":[945,18895]}]},{"id":"ch03p28","audio":"ch03p28.mp3","sents":[{"ar":"ثم قال الأمير الصغير، بجدية:","zh":"小王子认真地说：","t":[103,2865]}]},{"id":"ch03p29","audio":"ch03p29.mp3","sents":[{"ar":"لا يهم.","zh":"那无关紧要。","t":[103,1868]},{"ar":"أين أعيش، كل شيء صغير جدًا!","zh":"我所在之处的万物都如此渺小。","t":[1868,4895]}]},{"id":"ch03p30","audio":"ch03p30.mp3","sents":[{"ar":"وبإشارة إلى بعض الحزن، أضاف:","zh":"带着一丝忧伤，他补充道：","t":[103,3129]}]},{"id":"ch03p31","audio":"ch03p31.mp3","sents":[{"ar":"لا يمكن للمرء أن يضيع إذا سار مستقيمًا...","zh":"前方，无人能走得太远……","t":[103,3484]}]}]},{"id":"ch04","title_ar":"الفصل الرابع","title_en":"Chapter IV","title_zh":"第 4 章","paras":[{"id":"ch04p00","audio":"ch04p00.mp3","sents":[{"ar":"وهكذا تعلمت حقيقة أخرى مهمة جدًا: إن كوكب الأمير الصغير لم يكن أكبر من حجم بيت!","zh":"我因此得知了第二个重要的事实：小王子来自的星球，其大小不过是一座房子的规模。","t":[103,7879]}]},{"id":"ch04p01","audio":"ch04p01.mp3","sents":[{"ar":"لكن ذلك لم يدهشني في الواقع كثيرًا","zh":"但这并未真正让我感到惊讶。","t":[103,2971]},{"ar":"أعرف جيدًا أن هناك العديد من الكواكب الكبيرة مثل الأرض، جوبيتر، المريخ، وفينوس التي أعطيناها أسماء، ولكن هناك أيضًا مئات من الكواكب الأخرى، بعضها صغير جدًا بحيث يكون من الصعب رؤيته من خلال التلسكوب.","zh":"除了那些被我们命名的巨大行星——如地球、木星、火星、金星——之外，还有数百颗其他行星，其中一些小得连望远镜都难以辨认。","t":[2971,22605]},{"ar":"عندما يكتشف عالم الفلك أحد هذه الكواكب، لا يمنحها إسمًا، بل يمنحها رقمًا فقط.","zh":"天文学家发现这类星球时，并不赋予它们名字，而只赋予它们编号。","t":[22605,31026]},{"ar":"قد يسميه، مثلًا، \"كوكب 325\".","zh":"他或许会称之为“小行星325号”。","t":[31026,35829]}]},{"id":"ch04p02","audio":"ch04p02.mp3","sents":[{"ar":"لدي أسباب جدية لأعتقد أن كوكب الأمير الصغير هو الكوكب المعروف باسم ب-٦١٢، وقد شوهد هذا الكويكب مرة واحدة فقط من خلال تلسكوب بواسطة عالم فلك تركي في العام ۱۹۰۹.","zh":"我有充分的理由相信，小王子来自的星球是B-612号小行星。","t":[103,16105]}]},{"id":"ch04p03","audio":"ch04p03.mp3","sents":[{"ar":"هذا الكويكب لم يُرى إلا مرة واحدة من خلال التلسكوب.","zh":"这颗小行星仅被望远镜观测过一次。","t":[103,5408]},{"ar":"كان ذلك من عالم فلك تركي في عام 1909.","zh":"那是一位土耳其天文学家在1909年观测到的。","t":[5408,10250]}]},{"id":"ch04p04","audio":"ch04p04.mp3","sents":[{"ar":"عندما اكتشف ذلك، قدمه عالم الفلك إلى المؤتمر الدولي للفلك في عرض كبير.","zh":"天文学家在发现之际，曾于国际天文大会上作了一场盛大的演示。","t":[103,7566]},{"ar":"لكن كان يرتدي ثوبًا تركيًا، فلا يؤمن به أحد بما يقوله.","zh":"但他身着土耳其服装，因此无人相信他的话。","t":[7566,12776]}]},{"id":"ch04p05","audio":"ch04p05.mp3","sents":[{"ar":"كبار السن هم هكذا...","zh":"大人就是这样……","t":[103,1826]}]},{"id":"ch04p06","audio":"ch04p06.mp3","sents":[{"ar":"لحسن الحظ، لصالح سمعة كوكب ب-612، فرض دكتاتور تركي على رعاياه تغيير الزي الأوروبي تحت طائلة العقوبة بالموت.","zh":"幸而，为了B-612小行星的声誉，土耳其独裁者颁布了一道法令，规定臣民必须改穿欧洲服装，违者处以死刑。","t":[103,12934]},{"ar":"وهكذا في عام 1920 أعاد الفلكي عرض عرضه مرة أخرى، مرتديًا زينًا وأنيقًا.","zh":"于是，1920年，这位天文学家再次身着考究的服饰，仪态万方地展示了他的演示。","t":[12934,22145]},{"ar":"وفي هذه المرة قبل كل أحد تقبّل تقريره.","zh":"这一次，众人都接受了他的报告。","t":[22145,25658]}]},{"id":"ch04p07","audio":"ch04p07.mp3","sents":[{"ar":"إذا كنت قد أخبرتك عن تفاصيل الكوكب هذا، وكنت قد سجلت رقمه لك، فهذا بسبب البالغين وطرقهم.","zh":"若非为了这些大人及其习性，我才不会向你们详述这颗小行星的细节，并记下它的编号。","t":[103,9987]},{"ar":"عندما تخبرهم بأنك وضعت صديقًا جديدًا، لا يطرحون عليك أي أسئلة عن الأمور الأساسية.","zh":"告诉他们你交了一个新朋友，他们从不询问任何重要的事情。","t":[9987,18395]},{"ar":"لم يطرحوا عليكم أبدًا: كيف صوته؟ ما هي ألعابه المفضلة؟ هل يجمع الفراشات؟","zh":"他们从不会问你：“他的嗓音是怎样的？”","t":[18395,27684]},{"ar":"ما الألعاب التي يحبها أكثر؟","zh":"他最喜欢玩什么游戏？","t":[27684,30934]},{"ar":"هل يجمع فراشات؟ بدلاً من ذلك، يطلبون: \"كم عمره؟\"","zh":"他是否采集蝴蝶标本？","t":[30934,36934]},{"ar":"كم عدد إخوته؟","zh":"他有多少个兄弟？","t":[36934,39105]},{"ar":"كم يزن؟","zh":"他体重多少？","t":[39105,40842]},{"ar":"من خلال هذه الأرقام فقط يعتقدون أنهم قد تعلموا شيئًا عنه.","zh":"他们只从这些数字中认为他们已经了解了他。","t":[40842,45790]}]},{"id":"ch04p08","audio":"ch04p08.mp3","sents":[{"ar":"إذا قلت للبالغين: \"رأيت بيتًا جميلًا من الطوب الأحمر، مع نباتات البابونج في النوافذ وحمامات على السطح\"، لن يتمكنوا من تصور هذا البيت على الإطلاق.","zh":"若你对大人说：“我看见一幢红砖砌成的美丽房子，窗台上种着天竺葵，屋顶栖息着鸽子，”他们便无法想象这房子的模样。","t":[103,13250]},{"ar":"كنتُ أرى بيتًا قيمته عشرون ألف دولار. ثم يفاجأون ويقولون: \"أوه، ما منزل جميل هذا!\"","zh":"你们得对他们说：“我看见一幢价值两万法郎的房子。”他们就会惊叹：“哦，多美的房子啊！”","t":[13250,22066]}]},{"id":"ch04p09","audio":"ch04p09.mp3","sents":[{"ar":"البرهان على أن الأمير الصغير كان موجودًا هو أنه كان لطيفًا، وأنه ضحك وأنه كان يبحث عن خروف.","zh":"小王子存在的证据，便是他风度翩翩、笑声朗朗，且在寻找一只绵羊。","t":[103,9461]},{"ar":"إذا كان أحد يريد شاة، فهذا دليل على وجوده. وما الفائدة من إخبارهم بذلك؟","zh":"若有人想要一只绵羊，这便是他存在的证明。告诉他们这些又有什么用呢？","t":[9461,17987]},{"ar":"يبرزون كتفاهم، ويقومون بمعاملتك كطفل.","zh":"他们耸耸肩，把你当做个孩子。","t":[17987,23382]},{"ar":"إذا قلت لهم: إن الكوكب الذي أتى منه هو الكويكب ب-٦١٢، فإنهم سيقتنعون ويتركونك لشأنك.","zh":"若你对他们说：“他来自的星球是B-612号小行星，”他们便会信服，不再对你纠缠不休。","t":[23382,33328]}]},{"id":"ch04p10","audio":"ch04p10.mp3","sents":[{"ar":"هم كذلك.","zh":"他们就是这样。","t":[103,2079]},{"ar":"لا يجب أن نحمل عليهم هذا.","zh":"不可因此而怪罪他们。","t":[2079,5355]},{"ar":"يجب أن يظهر الأطفال تفهمًا كبيرًا تجاه البالغين.","zh":"孩子们理应对大人怀有极大的宽容。","t":[5355,9513]}]},{"id":"ch04p11","audio":"ch04p11.mp3","sents":[{"ar":"لكن بالتأكيد، لنا الذين نفهم الحياة، الأرقام أمر من باب التافهة.","zh":"然而，对于我们这些懂得生活的人来说，数字不过是无关紧要之物。","t":[103,7184]},{"ar":"كنتُ أرغبُ في بدء هذه القصة بلغة الأساطير.","zh":"我本想以童话的形式开始这个故事。","t":[7184,11789]},{"ar":"كان هناك أمير صغير عاش على كوكب ليس أكبر منه واحتاج إلى صديق","zh":"从前有个小王子，他住在一颗比他自己大不了多少的星球上，需要一只绵羊。","t":[11789,17355]}]},{"id":"ch04p12","audio":"ch04p12.mp3","sents":[{"ar":"سيجعل ذلك قصتي تبدو أكثر حقيقة للذين يفهمون الحياة.","zh":"这会让我的故事显得更加真实，对于那些懂得生活的人来说。","t":[103,5102]}]},{"id":"ch04p13","audio":"ch04p13.mp3","sents":[{"ar":"لا أريد أن يُقرأ كتابي بلا مبالاة، فقد عانيت حزنًا شديدًا أثناء تسجيل هذه الذكريات.","zh":"我不愿有人漫不经心地读我的书。","t":[103,8447]},{"ar":"لقد عانيت من حزن كبير في تسجيل هذه الذكريات.","zh":"我记录这些回忆，心中满是哀伤。","t":[8447,13434]},{"ar":"مرت ست سنوات منذ أن تركني صديقي الصغير مع خروفه.","zh":"六年来，我的朋友带着他的羊离我远去。","t":[13434,18803]},{"ar":"إذا حاولت أن أصفه هنا، فإن ذلك لضمان عدم نسيانه.","zh":"若我尝试在此描述他，那是为了确保我不会忘记他。","t":[18803,24592]},{"ar":"النسيان صديقًا يُحزن.","zh":"遗忘朋友是可悲的。","t":[24592,27434]},{"ar":"ليس الجميع قد كان لديه صديق.","zh":"并非人人都有过朋友。","t":[27434,31092]},{"ar":"وإذا نسيتُه، قد أصبحت مثل البالغين الذين لم يعدوا مهتمين بأي شيء سوى الأرقام...","zh":"若我忘记了他，我或许会变成那些只对数字感兴趣的成年人……","t":[31092,38171]}]},{"id":"ch04p14","audio":"ch04p14.mp3","sents":[{"ar":"لذلك، مرة أخرى، هو السبب الذي جعلني أشتغل علبة من الألوان وأقلام الرصاص.","zh":"为此，我又买了一盒颜料和几支铅笔。","t":[103,8118]},{"ar":"من الصعب العودة إلى الرسم في مثل هذا العمر، عندما لم أرسم سوى صور لثعبان من الخارج وثعبان من الداخل، منذ أن كنت في السادسة من عمري.","zh":"在这个年纪重拾绘画，对我而言实属不易，自从六岁那年画过一条从外面看的蟒蛇和一条从里面看的蟒蛇后，我从未再画过其他图画。","t":[8118,20289]},{"ar":"سأحاول بالتأكيد أن أجعل رسوماتي واقعية قدر الإمكان.","zh":"我将尽力让我的肖像画尽可能逼真。","t":[20289,26013]},{"ar":"لكنني لست متأكدًا من النجاح على الإطلاق.","zh":"但我并不确信能成功。","t":[26013,30395]},{"ar":"رسم جيد، ورسم آخر لا يشبه موضوعه على الإطلاق.","zh":"一幅画得还可以，另一幅却与原型相差甚远。","t":[30395,36197]},{"ar":"أرتكبت بعض الأخطاء أيضًا في طول الأمير الصغير: في مكان يكون طويلاً جدًا وفي آخر يكون قصيرًا جدًا.","zh":"我描绘小王子的身高时，也犯了一些错误：有时他画得太高，有时又太矮。","t":[36197,45553]},{"ar":"وأشك في ألوان ثوبه.","zh":"我对他的服装颜色也有些疑虑。","t":[45553,48184]},{"ar":"أنا أتردد في السير، الآن جيد، الآن سيء، وأتمنى أن تكون في الغالب مقبولة.","zh":"我笨拙地摸索前行，时而出色，时而糟糕，但愿总体上还能过得去。","t":[48184,55460]}]},{"id":"ch04p15","audio":"ch04p15.mp3","sents":[{"ar":"سأرتكب أخطاء في التفاصيل الهامة أيضًا.","zh":"在某些更为重要的细节上，我也难免出错。","t":[103,4329]},{"ar":"لكن ذلك ليس خطأي.","zh":"但这并非是我的过错。","t":[4329,7250]},{"ar":"صديقي لم يشرح لي شيئًا قط.","zh":"我的朋友从不向我解释任何事。","t":[7250,10539]},{"ar":"ربما كان يعتقد أنني أشبهه.","zh":"他或许以为我与他相似。","t":[10539,14145]},{"ar":"ولكني، أوف قلب، لا أعرف كيف أرى الأغنام عبر جدران الصناديق.","zh":"然而，唉，我不知如何透过箱子的墙壁看到绵羊。","t":[14145,20961]},{"ar":"ربما أنا قليلاً مثل البالغين.","zh":"或许我也有点像大人了。","t":[20961,24408]},{"ar":"لقد أضحت شابًا كبيرًا.","zh":"我不得不变老。","t":[24408,26395]}]}]},{"id":"ch05","title_ar":"الفصل الخامس","title_en":"Chapter V","title_zh":"第 5 章","paras":[{"id":"ch05p00","audio":"ch05p00.mp3","sents":[{"ar":"كل يوم، كنت أكتشف شيئًا ما عن كوكب الأمير الصغير، وعن مغادرته له، وعن رحلته.","zh":"随着日复一日，在与他的交谈中，我逐渐了解了小王子的星球、他离开那里的经过以及他的旅行。","t":[103,8513]},{"ar":"المعلومات تأتي ببطء شديد، كأنها قد تسقط من تفكيره.","zh":"信息缓缓而来，如同偶然自他思绪中飘落。","t":[8513,14263]},{"ar":"وهكذا سمعت، في اليوم الثالث، عن كارثة أشجار الباوباب.","zh":"就这样，第三天，我听说了猴面包树的灾难。","t":[14263,19263]}]},{"id":"ch05p01","audio":"ch05p01.mp3","sents":[{"ar":"هذا المرة، مرة أخرى، كانت الذبابة هي من أرشدني لذلك.","zh":"这次，又是绵羊让我得以知晓。","t":[103,6474]},{"ar":"إنه لأمر صحيح، أليس كذلك، أن الخراف تأكل الشجيرات الصغيرة؟","zh":"小王子突然严肃地问我：“羊真的会吃小灌木吗？”","t":[6474,12408]}]},{"id":"ch05p02","audio":"ch05p02.mp3","sents":[{"ar":"نعم، هذا صحيح.","zh":"是的，千真万确。","t":[103,1813]}]},{"id":"ch05p03","audio":"ch05p03.mp3","sents":[{"ar":"آه!","zh":"啊！","t":[103,1421]},{"ar":"أنا سعيد!","zh":"啊，太好了！","t":[1421,2540]}]},{"id":"ch05p04","audio":"ch05p04.mp3","sents":[{"ar":"لم أفهم لماذا تأكل الخراف شجيرات بهذه الأهمية.","zh":"我不懂羊儿为何要吃那些小灌木如此重要。","t":[103,5329]},{"ar":"لكن الأمير الصغير أضاف قائلًا: - وهكذا، فإنها تأكل أيضًا أشجار الباوباب؟","zh":"小王子接着说：","t":[5329,11895]}]},{"id":"ch05p05","audio":"ch05p05.mp3","sents":[{"ar":"ثم يتبع ذلك أنهم يأكلون من الباباوباب أيضًا؟","zh":"那么，它们也会吃猴面包树吗？","t":[103,4076]}]},{"id":"ch05p06","audio":"ch05p06.mp3","sents":[{"ar":"أوضحت للأمير الصغير أن أشجار الباوباب ليست شجيرات صغيرة، بل هي أشجار بعلو الكنائس، وأنه إذا ما أخذ قطيعًا من الفيلة معه، فإن القطيع لن يكون قادرًا على أكل شجرة باوباب واحدة.","zh":"我向小王子指出，猴面包树并非小灌木，相反，它们是像城堡一般巨大的树木；即便他带上一群大象，那群大象也无法吃掉一棵猴面包树。","t":[103,15724]}]},{"id":"ch05p07","audio":"ch05p07.mp3","sents":[{"ar":"الفكرة جماعة الفيلة جعلت الأمير الصغير يضحك.","zh":"那群大象的念头让小王子忍不住笑了。","t":[103,4208]}]},{"id":"ch05p08","audio":"ch05p08.mp3","sents":[{"ar":"على المرء أن يكدسهم الواحد فوق الآخر.","zh":"它们必须得一个挨一个地叠上去。","t":[103,3327]}]},{"id":"ch05p09","audio":"ch05p09.mp3","sents":[{"ar":"لكن قدم تعليقًا حكيمًا:","zh":"但他却说了句明智的话：","t":[103,2432]}]},{"id":"ch05p10","audio":"ch05p10.mp3","sents":[{"ar":"قبل أن تنمو كبيرة، تبدأ البوابة بالكونة الصغيرة.","zh":"在它们长得太大之前，猴面包树起初只是小小的。","t":[103,4576]}]},{"id":"ch05p11","audio":"ch05p11.mp3","sents":[{"ar":"هذا صحيح، أليس كذلك؟","zh":"那完全正确。","t":[103,3474]},{"ar":"لماذا تريد أن تأكل الأغنام الشجيرات الصغيرة من البابوا؟","zh":"可你为何要让羊儿吃掉那些小猴面包树苗呢？","t":[3474,7895]}]},{"id":"ch05p12","audio":"ch05p12.mp3","sents":[{"ar":"لقد أجابني على الفور، \"أوه، تعال، تعال!\" كما لو كان يتحدث عن شيء واضح للعيان.","zh":"他立刻回答道：“哦，哦，当然啦！”仿佛在谈论一件不言而喻的事。","t":[103,8842]},{"ar":"لقد اضطررت إلى بذل جهود فكرية كبيرة لحل هذه المشكلة دون أي مساعدة.","zh":"我不得不竭尽全力去解决这个问题，毫无助力。","t":[8842,15250]}]},{"id":"ch05p13","audio":"ch05p13.mp3","sents":[{"ar":"بالطبع، كما تعلمت، كانت هناك على كوكب حيث عاش الأمير الصغير – كما في كل كواكب – نباتات صالحة ونباتات سيئة.","zh":"确实，正如我所了解的，小王子居住的星球上——就像所有星球一样——既有好植物也有坏植物。","t":[103,11289]},{"ar":"لذلك، كانت هناك بذور جيدة من نباتات جيدة وبذور سيئة من نباتات سيئة.","zh":"因此，既有来自好植物的良种，也有来自坏植物的恶种。","t":[11289,19513]},{"ar":"البذور غير مرئية، تبقى مستترة في عمق الأرض حتى يقرر أحدها فجأة أن يستيقظ، ويبدأ في نشر جذوره.","zh":"种子是看不见的。","t":[19513,29789]},{"ar":"هم ينامون عميقاً في ظلام الأرض، حتى يُسيطر على أحدهم رغبة في الاستيقاظ.","zh":"它们在地球黑暗的深处沉睡，直至其中一颗被唤醒的欲望所攫获。","t":[29789,37000]},{"ar":"ثم سيتمدد هذا البذور الصغير ويبدأ – في البداية بتهدئة – في دفع غصين صغير وجميل نحو الشمس بغير إزعاج.","zh":"这颗小小的种子将伸展身躯，起初是胆怯地，开始向上向太阳推送一根迷人的小嫩枝。","t":[37000,47145]},{"ar":"إذا كان مجرد برعم فجل أو غصن من شجيرة ورد، فيمكن تركه ينمو كما يريد، لكن إذا كان نباتًا ضارًا، فيجب نزعه فورًا، وحالما يتم تحديد طبيعته.","zh":"若它只是一株萝卜苗或玫瑰枝，便任其生长，无论它愿往何处。","t":[47145,62263]},{"ar":"لكن إذا كان نباتًا سيئًا، يجب تدميره في أسرع وقت ممكن، في اللحظة الأولى التي يُمكن فيه التعرف عليه.","zh":"但若是恶草，一经辨认，便须立即铲除，绝不可拖延。","t":[62263,71540]}]},{"id":"ch05p14","audio":"ch05p14.mp3","sents":[{"ar":"على هذا الكوكب كانت بعض البذور المروعة، وهي بذور الشجيرات الكبيرة.","zh":"这颗星球上长着可怕的种子，那是猴面包树的种子。","t":[103,6671]},{"ar":"تربة ذلك الكوكب مفترسة بهم.","zh":"那颗星球的土壤被它们侵扰。","t":[6671,10434]},{"ar":"إذاً فإن الشجرة الكبيرة من نوع الباباوباب، إن لم تتم مراقبتها في الوقت المناسب، لن تستطيع التخلص منها أبدًا.","zh":"若你晚些时候才留意，那猴面包树你将永远无法摆脱。","t":[10434,20684]},{"ar":"يغطي الكوكب بأسره.","zh":"它覆盖了整个星球。","t":[20684,23395]},{"ar":"الجذور تمر عبرها بكل وضوح.","zh":"根须将它彻底穿透。","t":[23395,27105]},{"ar":"وإذا كان الكوكب صغيرًا جدًا، وإذا كان هنالك الكثير من أشجار الباوباب، فإن الكوكب ينفجر.","zh":"若星球太小，而猴面包树太多，它们就会把星球撕裂成碎片。","t":[27105,34842]}]},{"id":"ch05p15","audio":"ch05p15.mp3","sents":[{"ar":"هذا شأن تقوى النفس، قال لي الأمير الصغير لاحقًا.","zh":"“这关乎自律，”小王子后来对我说。","t":[103,5250]},{"ar":"عند انتهائك من تنظيف نفسك في الصباح، فحينها يأتي وقت العناية بتنظيف كوكبك، بل بكل عناية فائقة.","zh":"清晨梳洗完毕，便要细心照料你那颗星球的清洁。","t":[5250,14882]},{"ar":"يجب أن تتحقق من إزالة جميع الباوباب بانتظام عند أول لحظة يمكن فيها تمييزها عن الأشجيرات التي تشبهها كثيرًا في شبابها الأول.","zh":"务必在猴面包树与玫瑰花苗初生时难以区分之际，立即将它们连根拔除。","t":[14882,26526]},{"ar":"هذا العمل مملا جدًا، لكنه سهل جدًا.","zh":"这活儿单调乏味，却也极易完成。","t":[26526,30302]}]},{"id":"ch05p16","audio":"ch05p16.mp3","sents":[{"ar":"وفي يوم من الأيام قال لي: \"يجب أن ترسم رسمًا جميلًا، حتى يستطيع الأطفال الذين يسكنون معك رؤية كل هذا بالضبط.","zh":"于是有一天他对我说：“你应该画一幅漂亮的画，好让你们那里的孩子们能清楚地看到这一切。”","t":[103,11039]},{"ar":"إذا سافروا في يوم من الأيام، فإنه يفيدهم.","zh":"若他们日后旅行，这将会很有用。","t":[11039,16039]},{"ar":"في بعض الأحيان، أضاف، \"لا ضرر في تأجيل عمل إلى يوم آخر.","zh":"有时，他补充道，“推迟一件工作到另一天也无妨。","t":[16039,22526]},{"ar":"لكن عندما يكون الأمر بخصوص البابوابيات، فهذا دائمًا يعني كارثة.","zh":"但若是猴面包树的事，那就总是意味着灾难。","t":[22526,29263]},{"ar":"كان لدي كوكب يسكنه رجل كسول.","zh":"那颗星球上住着一个懒惰的人。","t":[29263,33395]},{"ar":"كان عليه أن يهتم بأشجار البابوباب الثلاث...","zh":"他忽略了三株小灌木……","t":[33395,36724]}]},{"id":"ch05p17","audio":"ch05p17.mp3","sents":[{"ar":"لذلك، كما وصفها لي الأمير الصغير، رسمت رسمًا لكوكبه.","zh":"于是，按照小王子向我描述的那样，我画下了那颗星球。","t":[103,6447]},{"ar":"لا أحب أن أظهر شكل المثقف.","zh":"我不喜欢摆出一副道德家的嘴脸。","t":[6447,9908]},{"ar":"لكن خطر شجر البابو ليس معروفًا جيدًا، وسيتم تحمل مخاطر كبيرة من قبل من قد يفقد على كوكب، لذا فأنا أتخلص من تحفظي مرة واحدة.","zh":"然而，人们对猴面包树的危害认识不足，而在小行星上迷路的人面临的风险又如此之大，我不得不打破一贯的矜持。","t":[9908,23539]},{"ar":"يا أطفال، احذروا الأشجار العملاقة!","zh":"孩子们，当心猴面包树！","t":[23539,26592]}]},{"id":"ch05p18","audio":"ch05p18.mp3","sents":[{"ar":"أصدقائي، كأنا، كانوا يتهربون من هذا الخطر لفترة طويلة دون أن يدركوا ذلك؛ ولذا كان من أجلهم أنني عملت بجد على هذا الرسم.","zh":"朋友们，就像我一样，他们长期以来一直在不知不觉中规避这个危险；因此，为了他们，我才在这幅画上倾注了如此多的心血。","t":[103,12395]},{"ar":"الدرس الذي أقوم بتبليغه بهذه الطريقة يستحق كل العناء الذي تكبدها.","zh":"这教训，虽费尽周折，却值得我付出所有。","t":[12395,18408]}]},{"id":"ch05p19","audio":"ch05p19.mp3","sents":[{"ar":"ربما ستسألوني: لماذا لا توجد رسوم أخرى مذهلة في هذا الكتاب كرسوم أشجار الباوباب؟ الجواب بسيط جدًا: لقد حاولت لكن لم يكن نجاحي كبيرًا مع الرسوم الأخرى. عندما رسمت أشجار الباوباب، كنت مدفوعًا بشعور الحاجة الملحة.","zh":"或许你们会问我：“为什么这本书里的其他插画没有这幅猴面包树的画那么雄伟、那么令人印象深刻？”","t":[103,20579]}]},{"id":"ch05p20","audio":"ch05p20.mp3","sents":[{"ar":"الإجابة بسيطة.","zh":"答案简单。","t":[103,2513]},{"ar":"لقد جربت.","zh":"我曾尝试。","t":[2513,4474]},{"ar":"لكن مع الآخرين لم أحقق نجاحًا.","zh":"但画那些其他的画，我并不成功。","t":[4474,8421]},{"ar":"عندما رسمت شجيرات الباباوباب، كانتني القوة الإلهامية للضرورة الملحة أفرطت في نفسي.","zh":"在绘制猴面包树时，紧迫的需求激励着我，我的画笔超越了自我。","t":[8421,15987]}]}]},{"id":"ch06","title_ar":"الفصل السادس","title_en":"Chapter VI","title_zh":"第 6 章","paras":[{"id":"ch06p00","audio":"ch06p00.mp3","sents":[{"ar":"آه! الأمير الصغير.","zh":"哦，小王子！","t":[103,3671]},{"ar":"شيئًا فشيئًا أدركت أسرار حياتك الصغيرة الحزينة...","zh":"逐渐地，我逐渐洞悉了你那悲伤的小生活的秘密……","t":[3671,8724]},{"ar":"كان مصدر سرورك الوحيد، لفترة طويلة، في استمتاعك بمراقبة غروب الشمس.","zh":"长久以来，你唯一的乐趣便是在观赏夕阳的宁静中寻找快乐。","t":[8724,16553]},{"ar":"في صباح اليوم الرابع، عندما قلت لي: - إنني مولع جدًا بغروب الشمس. لنذهب ونراقب غروب الشمس.. - لكن ينبغي أن ننتظر. - ننتظر ماذا؟ - ننتظر الشمس لتغيب. بدوت مذهولًا في بادئ الأمر، ثم ضحكت وقلت لي: - لا أنفك عن الاعتقاد بأنني في وطني. نعم بالتأكيد. عندما يكون النهار في منتصفه في الولايات المتحدة، تكون الشمس، كما يعلم كل شخص، تغرب في فرنسا. على المرء أن يسافر في دقيقة واحدة إلى فرنسا كي يتمكن من مراقبة غروب الشمس هناك. لسوء الحظ، إن فرنسا بعيدة جدًا، لكن على كوكبك الصغير، كل ما أنت بحاجة إليه هو تحريك كرسيك بضع خطوات. وباستطاعتك مشاهدة الشفق وهو يتلاشى كلما رغبت في ذلك... قال لي: - ذات يوم رأيت الشمس تغرب أربعًا وأربعين مرة. وقلت مضيفًا بعد ذلك بقليل: - هل تعلم... يعشق المرء غروب الشمس عندما يكون حزينًا للغاية... سألته: - هل كنت حزينًا يوم شاهدت الأربعة والأربعين غروبًا؟ لكن الأمير الصغير لم يعطِ أي جواب.","zh":"第四天清晨，你向我提及了这个新细节：","t":[16553,104882]}]},{"id":"ch06p01","audio":"ch06p01.mp3","sents":[{"ar":"أحب غروب الشمس كثيرًا.","zh":"我偏爱那夕阳的余晖。","t":[103,3224]},{"ar":"هيا، لنذهب نرى غروب الشمس الآن.","zh":"让我们去看日落吧。","t":[3224,6329]}]},{"id":"ch06p02","audio":"ch06p02.mp3","sents":[{"ar":"لكن يجب أن ننتظر، قلت.","zh":"但我道：“然而，我们必须等待。”","t":[103,2589]}]},{"id":"ch06p03","audio":"ch06p03.mp3","sents":[{"ar":"أنتظر؟","zh":"然而，为何等待？","t":[103,1816]},{"ar":"لماذا ننتظر؟","zh":"为何等待？","t":[1816,3171]}]},{"id":"ch06p04","audio":"ch06p04.mp3","sents":[{"ar":"للشفق.","zh":"只为那日落。","t":[103,1803]},{"ar":"علينا أن ننتظر حتى يأتي الوقت.","zh":"我们得等到那时。","t":[1803,4395]}]},{"id":"ch06p05","audio":"ch06p05.mp3","sents":[{"ar":"بدأت تظهر لك دهشة كبيرة.","zh":"你起初显得非常惊讶。","t":[103,3526]},{"ar":"ثم ضحكت لنفسك.","zh":"你自嘲地笑了。","t":[3526,6105]},{"ar":"أنتقلت إليّ:","zh":"你对我说：","t":[6105,7395]}]},{"id":"ch06p06","audio":"ch06p06.mp3","sents":[{"ar":"أنا دائمًا أعتقد أنني في وطني!","zh":"我总以为我是在自己家里呢！","t":[103,2945]}]},{"id":"ch06p07","audio":"ch06p07.mp3","sents":[{"ar":"كذلك فقط.","zh":"如此而已。","t":[103,2250]},{"ar":"كل شخص يعرف أن يكون الوقت ظهرًا في الولايات المتحدة الشمس تغرب في فرنسا.","zh":"人人皆知，当美国正值正午时分，法国已是夕阳西下。","t":[2250,8329]}]},{"id":"ch06p08","audio":"ch06p08.mp3","sents":[{"ar":"إذا كان بإمكانك الطيران إلى فرنسا في دقيقة واحدة، يمكنك الذهاب مباشرة إلى غروب الشمس، من منتصف النهار.","zh":"若能瞬间飞往法国，便可从正午直奔日落。","t":[103,10618]},{"ar":"للأسف، فرنسا بعيدة جدًا لذلك.","zh":"遗憾的是，法国太远了。","t":[10618,14855]},{"ar":"ولكن على كوكبك الصغير، يا أمير الصغير، كل ما تحتاجه هو تحريك كرسيك خطوات قليلة.","zh":"然而，在你那小小的星球上，小王子，你只需挪动你的椅子几步。","t":[14855,23868]},{"ar":"يمكنك رؤية نهاية اليوم وغروب الشفق في أي وقت تشاء...","zh":"你随时都能目睹白昼落幕，暮色降临。","t":[23868,28711]}]},{"id":"ch06p09","audio":"ch06p09.mp3","sents":[{"ar":"لقد رأيت الشمس تغرب أربعًا وأربعين مرة.","zh":"“有一天，”你对我说，“我看了四十四次日落！”","t":[103,3589]}]},{"id":"ch06p10","audio":"ch06p10.mp3","sents":[{"ar":"وأضاف لاحقًا:","zh":"你后来又补充道：","t":[103,1497]}]},{"id":"ch06p11","audio":"ch06p11.mp3","sents":[{"ar":"تعرفـ- أحب الظلمات عندما يكون الإنسان حزينًا جدًا...","zh":"你深知——当一个人愁绪满怀时，便偏爱那夕阳的余晖……","t":[103,4760]}]},{"id":"ch06p12","audio":"ch06p12.mp3","sents":[{"ar":"هل كنت حزينًا يومًا رأيت فيه أربعًا وأربعين غروبًا؟","zh":"那天，四十四次日落，你如此忧伤吗？","t":[103,4511]}]},{"id":"ch06p13","audio":"ch06p13.mp3","sents":[{"ar":"لكن الأمير الصغير لم يرد.","zh":"小王子默然不语。","t":[103,2247]}]}]},{"id":"ch07","title_ar":"الفصل السابع","title_en":"Chapter VII","title_zh":"第 7 章","paras":[{"id":"ch07p00","audio":"ch07p00.mp3","sents":[{"ar":"في اليوم الخامس، ومرة أخرى، شكرًا للخروف، كشفت لي أسرار حياة الأمير الصغير.","zh":"第五天——又像往常一样，多亏了那只绵羊——小王子生活的秘密向我透露了出来。","t":[103,8539]},{"ar":"فجأة، دون أي تقدم، وكأن السؤال ولد من تفكير عميق ومداومة على مشكلته، طلب مني: - هل يأكل الخروف الشجيرات، هل يأكل الأزهار أيضًا؟","zh":"他突然提出，仿佛这个问题经过他长时间的沉默深思才诞生出来。","t":[8539,21658]}]},{"id":"ch07p01","audio":"ch07p01.mp3","sents":[{"ar":"الأنثى إذا أكلت الأعشاب الصغيرة، هل تأكل الزهور أيضًا؟","zh":"绵羊若吃小灌木，也会吃花吗？","t":[103,4773]}]},{"id":"ch07p02","audio":"ch07p02.mp3","sents":[{"ar":"الخروف يأكل كل ما يجده في متناول يده.","zh":"绵羊，见什么吃什么。","t":[103,3735]}]},{"id":"ch07p03","audio":"ch07p03.mp3","sents":[{"ar":"حتى الزهور ذات الأشواك؟","zh":"连带刺的花也吃吗？","t":[103,2023]}]},{"id":"ch07p04","audio":"ch07p04.mp3","sents":[{"ar":"نعم، حتى الزهور ذات الشوك.","zh":"是的，连带刺的花也吃。","t":[103,2708]}]},{"id":"ch07p05","audio":"ch07p05.mp3","sents":[{"ar":"ما هي فائدة الشوك؟","zh":"那刺还有什么用呢？","t":[103,1707]}]},{"id":"ch07p06","audio":"ch07p06.mp3","sents":[{"ar":"لم أعرف السبب.","zh":"我不知其所以然。","t":[103,2395]},{"ar":"في تلك اللحظة كنت مشغولاً في محاولة فك اتصال مفتاح علق في محركي، وأنا قلق لأن تحطم طائري بدأ يبدو أمرًا خطيرًا جدًا، ومياه الشرب بدأت تنفد بسرعة ولم أستطع إلا خشية الأسوأ.","zh":"那时我正忙于拧下卡在发动机里的螺栓。","t":[2395,19526]},{"ar":"كنت قلقاً جدًا، لأنه أصبح واضحًا لي أن انكسار طائري كان خطيرًا للغاية.","zh":"我深感忧虑，因为我的飞机故障显然极其严重。","t":[19526,26842]},{"ar":"الباقي من الماء شديد الندرة، ولم أستطع إلا أن أخاف من الأسوأ.","zh":"我剩下的饮用水寥寥无几，不禁担忧着最坏的结果。","t":[26842,32145]}]},{"id":"ch07p07","audio":"ch07p07.mp3","sents":[{"ar":"الشوك... ما الفائدة منها؟","zh":"刺，它们有何用？","t":[103,3105]}]},{"id":"ch07p08","audio":"ch07p08.mp3","sents":[{"ar":"لم يترك الأمير الصغير سؤالاً بعد أن طرحه.","zh":"小王子一旦提问，便锲而不舍。","t":[103,4447]},{"ar":"حولي، كنت غاضباً من ذلك المسامير.","zh":"至于我，那螺栓让我心烦意乱。","t":[4447,8513]},{"ar":"وإذا سألني على حين غرة: - إن أكل الخروف الشجيرات، هل يأكل الأزهار أيضًا؟ - الخروف يأكل كل ما يصادفه. - حتى الأزهار ذات الأشواك؟ - أجل، حتى الأزهار ذات الأشواك. - الأشواك.. ما الفائدة منها؟ لم أعرف السبب؛ كنت منهمكًا أحاول فك مسمار علق في محركي، وكنت في أشد القلق لأن تحطم طائرتي بدأ يبدو لي أمرًا خطيرًا جدًّا، فمياه الشرب بدأت تنفد بسرعة ولم أستطع إلا خشية الأسوأ. - الأشواك - ما الفائدة منها؟ لم يكن الأمير الصغير ليتخلى عن سؤال يطرحه في أي وقت. كنت قلقًا بشأن مسماري فأجبت بأول شيء خطر في بالي: - إن الأشواك عديمة الفائدة. الأزهار تكتسبها لمجرد الأذية. وبعد لحظة صمت، قال بنوع من الازدراء: - لا أصدقك؛ إن الأزهار ضعيفة. إنها ساذجة، وهي تضمن أنفسها بأفضل ما يمكن. إنها تعتقد بأن أشواكها رهيبة... لم أجب. وكنت أقول في تلك اللحظة لنفسي: « إن استمر هذا المسمار في مقاومتي، سأضربه بالمطرقة ». ومرة أخرى تدخل الأمير الصغير في أفكاري: - وهل تعتقد فعلًا بأن الأزهار... - لا! لا! لا أعتقد شيئًا. لقد أجبت كيفما كان. إنني منهمك في أمور مهمة. حدق إليَّ بدهشة تامة. - أمور مهمة؟ استطاع أن يراني والمطرقة في يدي وأصابعي سوداء من شحم المحرك، أنحني فوق شيء بدا.... قبيحًا للغاية. - تتحدث مثل الكبار تماما. جعلني هذا أشعر بالخجل. أضاف مثابرًا: - إنك تفسد كل شيء... تخلط كل شيء. كان غاضبًا حقًّا. أخذ يحرك خصل شعره الذهبية في الريح: - أعرف كوكبًا حيث يوجد سيد ذو وجه أحمر، لم يسبق له أن شم زهرة. لم ينظر قط إلى نجمة، لم يحب أحدًا، أمضى حياته كلها وهو يجمع الأرقام. كان يردد مثلك طوال النهار: إنني منهمك بأمور مهمة، إنني منهمك بأمور مهمة. مرارًا وتكرارًا وهو ينتفخ كبرياء. لكنه ليس رجلًا، إنه فطر. - ماذا؟ - فطر. شحص وجه الأمير الصغير من الغضب. - إن الأزهار تنتج الأشواك منذ ملايين السنين، وعلى مدى ملايين السنين تأكل الخراف الأزهار. أليس جديرًا بالاهتمام بذل الجهد لمحاولة فهم لماذا تنتج الأشواك التي لا فائدة منها؟ أليست الحرب بين الخراف والأزهار مهمة؟ أليست أكثر جدية وأكثر أهمية من مبالغ أموال السيد ذو الوجه الأحمر؟ وإذا أنا علمت بأمر زهرة فريدة من نوعها في العالم لا تنمو في أي مكان غير كوكبي ويمكن لخروف صغير أن يتلفها بقضمة واحدة، ببساطة هكذا، ذات صباح، من دون أن يدرك ماذا يفعل، أليس هذا مهمًّا؟ احمر وجهه وتابع: - إذا أحب شخص ما زهرة وحيدة على ملايين النجوم، النظر إليها يجعله سعيدًا، ويستطيع القول لنفسه: إن زهرتي في مكان ما هناك في الخارج... وإذا أكل الخروف الزهرة، وبدا له أن النجوم كافة أصبحت مظلمة فجأة! فأنت تعتقد بأن الأمر غير مهم! لم يستطع قول المزيد لأن الدموع غلبته. هبط الليل، تركت عدتي، لم أعد أكترث بمطرقتي ومسماري، بالعطش أو الموت، فهنالك على نجم، كوكب، هو الأرض، أمير صغير ينبغي تهدئته! حملته بذراعي وجعلته يتأرجح بلطف. قلت له: - ليست الزهرة التي تحب في خطر، سأرسم لك كمامة لخروفك، سأرسم سياجًا لزهرتك... لم أعرف حقًّا ماذا أقول له. شعرت بارتباك شديد، لم أعرف كيف أصل إليه وكيف ألحق به... إن بلاد الدموع غامضة جدًّا.","zh":"我随口答道：","t":[8513,304543]}]},{"id":"ch07p09","audio":"ch07p09.mp3","sents":[{"ar":"الشوك لا فائدة منها على الإطلاق.","zh":"刺毫无用处。","t":[103,3684]},{"ar":"الزهور تزين نفسها بالأشواك فقط للإيذاء.","zh":"花儿长刺，只为泄愤。","t":[3684,7289]}]},{"id":"ch07p10","audio":"ch07p10.mp3","sents":[{"ar":"أوه!","zh":"哦！","t":[103,629]}]},{"id":"ch07p11","audio":"ch07p11.mp3","sents":[{"ar":"لحظة صمت تامة","zh":"一时寂静无声。","t":[103,1747]},{"ar":"ثم ألقى الأمل الصغير نظرة علي، بروح من الإحباط:","zh":"小王子带着一丝怨恨，向我闪过一瞥。","t":[1747,6142]}]},{"id":"ch07p12","audio":"ch07p12.mp3","sents":[{"ar":"لا أؤمن بك!","zh":"我不信你的话！","t":[103,2197]},{"ar":"الزهور كائنات ضعيفة.","zh":"花儿是脆弱的生物。","t":[2197,5211]},{"ar":"هم بسيطون.","zh":"她们天真无邪。","t":[5211,7224]},{"ar":"تحاولن أن تطمئنّ أنفسهن بأفضل ما يمكن.","zh":"她们尽力自我安慰。","t":[7224,11737]},{"ar":"هم يعتقدون أن شوكهم أسلحة مخيفة...","zh":"它们以为自己的刺是可怕的武器……","t":[11737,15066]}]},{"id":"ch07p13","audio":"ch07p13.mp3","sents":[{"ar":"لم أجب.","zh":"我默然不语。","t":[103,1737]},{"ar":"في تلك اللحظة كنت أقول لنفسي: \"إذا لم يزال هذا البرغي لا يتحرك، سأضربه بالمطرقة.\" مرة أخرى، أزعجني الأمير الصغير من تفكيري.","zh":"那一刻，我自言自语道：“如果这颗螺栓还是拧不动，我就用锤子把它砸下来。”小王子又一次打断了我在思考。","t":[1737,13645]}]},{"id":"ch07p14","audio":"ch07p14.mp3","sents":[{"ar":"وأنتم تؤمنون فعلاً بأن الزهورـ","zh":"而你竟然相信花儿——","t":[103,2892]}]},{"id":"ch07p15","audio":"ch07p15.mp3","sents":[{"ar":"أوه، لا! أنا صرخت.","zh":"哦，不！我惊呼。","t":[103,4329]},{"ar":"لا، لا، لا!","zh":"不，不，不！","t":[4329,4987]},{"ar":"لا أؤمن بأي شيء.","zh":"我不信任何事。","t":[4987,9684]},{"ar":"أجبت بلا تفكير، أول ما تردد في ذهني كان الجواب.","zh":"随口应道，我脑海中浮现的第一个念头便是答案。","t":[9684,15250]},{"ar":"ألا ترى - أنا مشغول بأمور هامة جدًا!","zh":"您忙于正事，无暇他顾。","t":[15250,18947]}]},{"id":"ch07p16","audio":"ch07p16.mp3","sents":[{"ar":"انهى نظره علي، مصاب بالذهول.","zh":"他瞪着我，惊愕不已。","t":[103,3181]}]},{"id":"ch07p17","audio":"ch07p17.mp3","sents":[{"ar":"أمور مهمة!","zh":"事关重大！","t":[103,1340]}]},{"id":"ch07p18","audio":"ch07p18.mp3","sents":[{"ar":"ها هو الأمير الصغير يحدق في، بيدي مقلع، أصابعي أسود من زيت المحرك، ينحني أمام شيء يبدو له قبيحًا جدًا...","zh":"他瞧着我，手里握着锤子，指头沾满了发动机的机油，俯身对着在他看来极其丑陋的物件。","t":[103,10208]}]},{"id":"ch07p19","audio":"ch07p19.mp3","sents":[{"ar":"تتحدث مثل الكبار تمامًا.","zh":"你说话就像大人一样！","t":[103,2405]}]},{"id":"ch07p20","audio":"ch07p20.mp3","sents":[{"ar":"هذا جعلني أشعر بالخجل قليلاً.","zh":"这让我感到有些羞愧。","t":[103,3987]},{"ar":"لكن استمر في الحديث، بلا هوادة:","zh":"但他却继续说，毫不留情。","t":[3987,6842]}]},{"id":"ch07p21","audio":"ch07p21.mp3","sents":[{"ar":"تخلط كل شيء معًا...","zh":"你把一切都搅和在一起……","t":[103,2855]},{"ar":"تُخلط كل شيء... تُدمج كل شيء.","zh":"你把一切都混为一谈……","t":[2855,6882]}]},{"id":"ch07p22","audio":"ch07p22.mp3","sents":[{"ar":"كان غاضبًا جدًا.","zh":"他真的非常生气。","t":[103,2500]},{"ar":"أرفع شعره الذهبي في الهواء","zh":"他金黄色的卷发在风中飘扬。","t":[2500,4789]}]},{"id":"ch07p23","audio":"ch07p23.mp3","sents":[{"ar":"أعلم كوكباً حيث يوجد سيد ذو وجه أحمر لم يسبق له أن شم زهرة.","zh":"我知道有一个星球上住着一位红脸先生。","t":[103,6553]},{"ar":"لم يشم الأزهار قط.","zh":"他未曾嗅过一瓣花。","t":[6553,9224]},{"ar":"لم ينظر إلى نجمة قط.","zh":"他从未仰望过一颗星星。","t":[9224,12237]},{"ar":"لم يسبق له أن أحب أحدًا.","zh":"他从未爱过任何人。","t":[12237,15487]},{"ar":"لم يفعل في حياته شيء إلا جمع الأرقام.","zh":"他一生只做加法。","t":[15487,19882]},{"ar":"ويكرر طوال اليوم، كما أنت: 'أنا مشغول بأمور هامة!' ويجعل هذا جفنه يتضخم بالفخر.","zh":"他整天反复说着，就像你一样：“我正忙于要紧的事！”这让他骄傲得膨胀起来。","t":[19882,29053]},{"ar":"لكن هو ليس إنسانًا، إنه فطر!","zh":"但他并非凡人——他只是一朵蘑菇！","t":[29053,32145]}]},{"id":"ch07p24","audio":"ch07p24.mp3","sents":[{"ar":"ما هذا؟","zh":"“这是什么？”","t":[103,905]}]},{"id":"ch07p25","audio":"ch07p25.mp3","sents":[{"ar":"الطعم!","zh":"蘑菇！","t":[103,866]}]},{"id":"ch07p26","audio":"ch07p26.mp3","sents":[{"ar":"الأمير الصغير قد أصبح أبيض الوجه من الغضب.","zh":"小王子气得脸色煞白。","t":[103,3695]}]},{"id":"ch07p27","audio":"ch07p27.mp3","sents":[{"ar":"الزهور تنمو الشوك منذ ملايين السنين.","zh":"花儿已长刺数百万年。","t":[103,4092]},{"ar":"لأمئات السنين، الأغنام تأكلها بنفس الطريقة.","zh":"数百万年来，绵羊一直这样吃着它们。","t":[4092,9092]},{"ar":"وهل ليس الأمر مهمًا محاولة فهم لماذا تذهب الزهور إلى كل هذا العناء لتنمو أشواك، التي لا تنفعها بأي حال؟","zh":"探究为何花儿费尽心机长出无用的刺，这难道不是一件重要的事吗？","t":[9092,19408]},{"ar":"هل معركة الأغنام والزهور ليست مهمة؟","zh":"羊与花的战争难道不重要吗？","t":[19408,23434]},{"ar":"هذا ليس أكثر أهمية من حسابات رجل سمين ذو وجه أحمر؟","zh":"这难道不是比那位红脸胖子的算术更重要吗？","t":[23434,29289]},{"ar":"وهل أعلم أنني أعرف زهرة فريدة في العالم تنمو في كوكبي وحدها، ويمكن للخروف الصغير أن يهلكها في قضمته الواحدة، بلا أن يشعر بما يفعله، أليس هذا مهم؟","zh":"哦！若我深知——我自己——世间仅此一朵独一无二的花，它只生长在我的星球，而一只小小的绵羊却能在某个清晨不经意间将它一口吞噬，甚至未曾察觉自己的行为——哦！","t":[29289,44355]},{"ar":"هذا ليس مهماً!","zh":"这难道不重要吗？","t":[44355,45934]}]},{"id":"ch07p28","audio":"ch07p28.mp3","sents":[{"ar":"وجهه تحول من أبيض إلى أحمر وهو يستمر في قوله:","zh":"他的脸色由白转红，继续说道：","t":[103,4313]}]},{"id":"ch07p29","audio":"ch07p29.mp3","sents":[{"ar":"إذا أحب شخص ما زهرة وحيدة على ملايين النجوم، النظر إليها يجعله سعيدًا، ويستطيع القول لنفسه: إن زهرتي في مكان ما هناك في الخارج... وإذا أكل الخروف الزهرة، وبدا له أن النجوم كافة أصبحت مظلمة فجأة! فأنت تعتقد بأن الأمر غير مهم!","zh":"若有人爱上了一朵生长在亿万星辰中的一朵花，只需仰望星空，便足以使他心满意足。","t":[103,24000]},{"ar":"هو يمكن أن يقول لنفسه: 'بمكان ما، وردتي هناك...' لكن إذا أكل الخروف الوردة، في لحظة واحدة ستظلم كل نجومه...","zh":"他可以对自己说：“我的花儿在那儿……”但若绵羊吃掉了那朵花，他的所有星星在一瞬间都将黯淡无光……","t":[24000,36053]},{"ar":"وهل تعتقد أن ذلك غير مهم؟ لم يستطع أن يقول شيئًا أكثر.","zh":"这难道不重要吗？他再也无法说下去了。","t":[36053,43026]},{"ar":"كلماته تعثرت بسبب البكاء","zh":"他的话语被抽泣所哽咽。","t":[43026,45658]}]},{"id":"ch07p30","audio":"ch07p30.mp3","sents":[{"ar":"الليل قد غطى السماء.","zh":"夜幕降临。","t":[103,2737]},{"ar":"كنت قد تركت أدواتي تسقط من يدي.","zh":"我手中的工具纷纷落地。","t":[2737,6645]},{"ar":"ما هو أهمية مطرقي أو بولتي أو عطشي أو الموت الآن؟","zh":"我的锤子、螺栓、干渴或死亡，此刻又算得了什么？","t":[6645,12355]},{"ar":"على نجم، كوكب، هو الأرض، الأمير الصغير ينبغي تهدئته!","zh":"在地球，我的星球上，有一个小王子需要安慰。","t":[12355,18658]},{"ar":"أنا أخذته في أحضاني وأهتزته بلطف.","zh":"将他紧紧抱在怀里，轻轻摇晃着他。","t":[18658,22750]},{"ar":"قلت له:","zh":"我对他说：","t":[22750,23487]}]},{"id":"ch07p31","audio":"ch07p31.mp3","sents":[{"ar":"الوردة التي تحبها ليست في خطر.","zh":"你爱的那朵花并无危险。","t":[103,3934]},{"ar":"سأرسم لك كمامة لخروفك","zh":"我给你那绵羊画个口罩。","t":[3934,6263]},{"ar":"سأرسم لك سورًا حول وردتك.","zh":"我为你那朵花画一道栅栏。","t":[6263,9684]},{"ar":"سأفعلـ\"","zh":"我将——","t":[9684,10605]}]},{"id":"ch07p32","audio":"ch07p32.mp3","sents":[{"ar":"لم أعرف ما أقوله له.","zh":"我不知该如何向他开口。","t":[103,2750]},{"ar":"شعرت بالحرج والتبلد.","zh":"我感到尴尬而笨拙。","t":[2750,5711]},{"ar":"لم أعرف كيف أستطيع اللحاق به، أين يمكنني أن ألتقي به وأتوجه معه مرة أخرى يد بيد.","zh":"我不知如何才能追上他，在哪里才能与他并肩前行，再次携手同行。","t":[5711,13514]}]},{"id":"ch07p33","audio":"ch07p33.mp3","sents":[{"ar":"مكان سرّي، أرض الدموع.","zh":"泪水的王国，如此神秘。","t":[103,2471]}]}]},{"id":"ch08","title_ar":"الفصل الثامن","title_en":"Chapter VIII","title_zh":"第 8 章","paras":[{"id":"ch08p00","audio":"ch08p00.mp3","sents":[{"ar":"سرعان ما تعلمت أن أعرف هذه الزهرة على نحو أفضل.","zh":"我很快便更深入地了解了这朵花。","t":[103,5342]},{"ar":"على كوكب الأمير الصغير كانت الزهور دائمًا بسيطة جدًا.","zh":"小王子的星球上，花朵总是极为朴素。","t":[5342,10763]},{"ar":"الوردة لها حلقة واحدة من البتلات، لا تأخذ مساحة، ولا تسبب أي إزعاج لأحد.","zh":"花瓣仅一环，不占空间，不惹尘埃。","t":[10763,19526]},{"ar":"في صباحهم تبرز في العشب، وفي الليل تذوب بسلام.","zh":"清晨它们在草间绽放，夜晚便平静地凋谢。","t":[19526,24855]},{"ar":"لكن يوماً ما، من بذرة هبطة من مكان لا يعرف أحد عنه، نبتت زهرة جديدة؛ وراقب الأمير الصغير عن كثب البرعم الصغير الذي لم يكن يشبه أي برعم آخر على كوكبه.","zh":"然而，一天，一朵来自无人知晓之处的种子发芽了；小王子密切地关注着这株与众不同的嫩芽，它不同于他星球上其他任何嫩芽。","t":[24855,39908]},{"ar":"ربما كان نوعاً جديداً من الباوباب.","zh":"或许，它可能是一种新型的猴面包树。","t":[39908,42671]}]},{"id":"ch08p01","audio":"ch08p01.mp3","sents":[{"ar":"سرعان ما توقفت النبتة عن النمو وبدأت تنمو زهرة.","zh":"灌木很快停止了生长，开始准备绽放花朵。","t":[103,5382]},{"ar":"الأمير الصغير، الذي كان حاضراً عند ظهور بُتة ضخمة، شعر فوراً بأن نوعاً من الظاهرة السحرية يجب أن تنشأ منها.","zh":"小王子目睹那硕大的花蕾初现，便预感其中将诞生某种奇迹般的景象。","t":[5382,16211]},{"ar":"لكن الزهرة لم تكن راضية بأن تكتمل جمالها في حماية غرفتها الخضراء.","zh":"但那朵花并不满足于只在绿屋的庇护下完成她美丽的准备。","t":[16211,23013]},{"ar":"اختيارت ألوانها بعناية فائقة","zh":"她挑选色彩极是用心。","t":[23013,25763]},{"ar":"تعدل أوراقها واحدة تلو الأخرى.","zh":"她逐一调整着花瓣。","t":[25763,29553]},{"ar":"لم تكن تريد الذهاب إلى العالم مرتبكة كالزهور البرية.","zh":"她不愿像野罂粟花那样，皱巴巴地闯进世界。","t":[29553,34947]},{"ar":"كانت تريد أن تظهر فقط في أبهى جمالها.","zh":"她只愿在美丽绽放的极致中露面。","t":[34947,39092]},{"ar":"أوه، نعم!","zh":"哦，是的！","t":[39092,41329]},{"ar":"كانت مخلوقة عجيبة بالجمال!","zh":"她是个爱美的生灵。","t":[41329,44855]},{"ar":"وكان زينها الغامض يستمر يوما بعد يوم.","zh":"她的神秘装扮持续了好多天。","t":[44855,48474]}]},{"id":"ch08p02","audio":"ch08p02.mp3","sents":[{"ar":"ثم في صباح واحد، تمامًا عند شروق الشمس، ظهرت فجأة.","zh":"就在一个清晨，正逢日出时分，她突然现身。","t":[103,5340]}]},{"id":"ch08p03","audio":"ch08p03.mp3","sents":[{"ar":"وبعد أن عملت بجد وبذلت مثل ذلك الجهد، تثاءبت وقالت: - آه! أنا نصف يقظة... سامحوني... فأنا ما زلت غير مرتبة... لكن الأمير الصغير لم يستطع أن يخفي إعجابه، فقال: - أوه، كم أنت جميلة! ألست كذلك؟ أجابت الزهرة بلطف: - لقد وُلدت في الوقت الذي أشرق فيه الشمس... كان على الأمير الصغير أن يعترف بأنها لم تكن متواضعة وأنها فاتنة للغاية! - أعتقد بأن وقت الفطور قد حان، (أضافت بعد لحظة) هلا تفضلت لتلبي حاجاتي؟ في الحال جلب الأمير الصغير بارتباك تام وعاء نثر منه الماء العذب على الزهرة. وهكذا شرعت منذ البداية تعذبه بكبريائها الملححة. وعلى سبيل المثال، قالت ذات يوم للأمير الصغير وهي تشير إلى أشواكها الأربعة: - ليأت النمور بمخالبهم. اعترض الأمير الصغير: - لكن ليس هنالك نمور على كوكبي، وفي أي حال، لا تأكل النمور الأعشاب الضارة. قالت الزهرة برقة: - لكنني لست عشبة ضارة. - رجاء سامحيني... - لا أخاف النمور، لكنني أكره تيارات الهواء، ألن تأتيني بستارة؟ أشار الأمير الصغير وهو يفكر في نفسه: « رعب من تيَّارات الهواء... إن ذلك لحظ سيئ حقًّا بالنسبة إلى نبتة، وإن هذه الزهرة لهي بالفعل مخلوق معقد جدًّا ». - في المساء أريد أن تضعني تحت قبة زجاجية؛ البرد قارس جدًّا هنا حيث تعيش. إن هذا الأمر غير مريح. والآن من حيث أنا أتيت... قاطعت نفسها بعد وقت متأخر، لقد وصلَت كحلة، ولم تكن تعرف شيئًا عن العوالم الأخرى، وعندما أحست بالارتباك لاكتشافها حقيقة هذا الوضع الساذج، سعلت مرات عديدة كي تربك الأمير الصغير. - أين الستارة؟ - أردت أن آتي بها لكنك كنت تتحدثين إلي! عندئذ سعلت أكثر كي يشعر بالندم، وهكذا، على الرغم من النية الطيبة التي ولدها حبه تجاهها، بدأ الأمير الصغير شيئًا فشيئًا يرتاب بها. أخذ كلمات ليست بذي أهمية على محمل الجد وأصبح حزينًا جدًّا. أفضى لي بدخيلة نفسه ذات يوم: - كان ينبغي لي ألا أصغي لها. لا ينبغي أن يصغي المرء إلى الأزهار. على المرء أن يُعجب بها ويتنشق عطرها. لقد عطرت زهرتي كوكبي، لكنني لم أعرف كيف أستمتع بها. كان ينبغي لحكاية المخالب التي أزعجتني كثيرًا أن تلامس قلبي ببساطة.. وأفضى بالمزيد: - آنذاك لم أستطع أن أفهم شيئًا! كان يجب أن أبني حكمي طبقًا للأفعال وليس للكلمات. لقد غمرتني بعبيرها وتألقها. كان ينبغي ألا أهرب منها! كان ينبغي أن أكتشف المحبة الكامنة وراء حيلها الصغيرة البسيطة، فالأزهار متقلبة جدًّا! وقد كنت صغيرًا جدًّا، فلم أعرف كيف أحبها.","zh":"经过这番苦心孤诣的精心打扮，她打了个哈欠说道：","t":[103,220039]}]},{"id":"ch08p04","audio":"ch08p04.mp3","sents":[{"ar":"آه!","zh":"唉！","t":[103,1421]},{"ar":"أنا ما زلت غافلاً...","zh":"我刚刚醒来，尚感朦胧。","t":[1421,4066]},{"ar":"أرجو أن تعذروني على جريتي.","zh":"请您原谅我的冒昧。","t":[4066,7355]},{"ar":"أوراقي مازالت في فوضى...","zh":"我的花瓣仍凌乱不堪……","t":[7355,9237]}]},{"id":"ch08p05","audio":"ch08p05.mp3","sents":[{"ar":"لكن الأمير الصغير لم يستطع أن يكبح إعجابه:","zh":"小王子忍不住赞叹：","t":[103,3813]}]},{"id":"ch08p06","audio":"ch08p06.mp3","sents":[{"ar":"أوه!","zh":"哦！","t":[103,1526]},{"ar":"أنتِ جميلة جدًا!","zh":"您真美啊！","t":[1526,3171]}]},{"id":"ch08p07","audio":"ch08p07.mp3","sents":[{"ar":"أنا، نعم، أجبت الزهرة بلطف.","zh":"“是啊，”花儿柔声回应。","t":[103,4184]},{"ar":"وولدت في نفس اللحظة التي أشرقت فيها الشمس...","zh":"我与太阳同日而生。","t":[4184,7764]}]},{"id":"ch08p08","audio":"ch08p08.mp3","sents":[{"ar":"كان الأمير الصغير يستطيع التنبؤ بسهولة بأنها ليست متواضعة جدًا، ولكنها كانت مذهلة ومثيرة!","zh":"小王子不难看出她并不怎么谦逊——然而她是多么动人——多么令人兴奋！","t":[103,8787]}]},{"id":"ch08p09","audio":"ch08p09.mp3","sents":[{"ar":"هي قالت بعد لحظة: \"هذا الوقت مناسب للإفطار.\"","zh":"她随即又补充道：“现在是吃早餐的时候了。”","t":[103,4076]},{"ar":"إذا كنت لطيفًا بما يكفي لتأمل احتياجاتي...","zh":"若您能体谅我的所需——","t":[4076,7615]}]},{"id":"ch08p10","audio":"ch08p10.mp3","sents":[{"ar":"وقد شعر الأمير الصغير بالخجل الشديد، فذهب يبحث عن قارورة ماء عذب.","zh":"小王子羞愧难当，去找一壶清水。","t":[103,6987]},{"ar":"لقد رعى الزهرة.","zh":"于是，他照料着这朵花。","t":[6987,8329]}]},{"id":"ch08p11","audio":"ch08p11.mp3","sents":[{"ar":"لقد بدأت بسرعة تؤذيه بفوقانيتها التي كانت صعبة التعامل إذا ما عرفت الحقيقة.","zh":"于是，她很快便开始用她的虚荣心折磨他——若真相大白，这实在有些难以应对。","t":[103,7763]},{"ar":"اليوم، مثلاً، عندما كانت تتحدث عن أوراقها الأربعة، قالت للأمير الصغير:","zh":"有一天，当她谈到她那四根刺时，她对小王子说：","t":[7763,14671]}]},{"id":"ch08p12","audio":"ch08p12.mp3","sents":[{"ar":"ليأت النمور بمخالبها.","zh":"让老虎带着它们的爪子来吧！","t":[103,2129]}]},{"id":"ch08p13","audio":"ch08p13.mp3","sents":[{"ar":"ليس هنالك نمر على كوكبي.","zh":"我的星球上没有老虎。","t":[103,3474]},{"ar":"النمور لا تأكل الأعشاب الضارة.","zh":"老虎不吃杂草。","t":[3474,5908]}]},{"id":"ch08p14","audio":"ch08p14.mp3","sents":[{"ar":"أنا لست نباتًا مزروعًا، أجابت الزهرة بلطف.","zh":"“我不是杂草。”花儿柔声回答。","t":[103,4010]}]},{"id":"ch08p15","audio":"ch08p15.mp3","sents":[{"ar":"سامحوني...","zh":"请原谅……","t":[103,1103]}]},{"id":"ch08p16","audio":"ch08p16.mp3","sents":[{"ar":"أنا لست خائفاً من النمور، ولكنني أخاف من الرياح العاتية.","zh":"“我对老虎毫不畏惧，却最怕穿堂风。”","t":[103,6053]},{"ar":"هل لديكم شاشة لي؟","zh":"您这儿有屏风吗？","t":[6053,7710]}]},{"id":"ch08p17","audio":"ch08p17.mp3","sents":[{"ar":"الخوف من الرياح العاتية هذا يعد من الحظ السيء بالنسبة للنبات، قال الأمير الصغير وأضاف لنفسه، هذه الزهرة مخلوقة معقدة جدًا...","zh":"“对穿堂风如此恐惧——这对植物来说可真是不幸，”小王子评论道，心中暗想，“这朵花真是个复杂的生物……”","t":[103,11589]}]},{"id":"ch08p18","audio":"ch08p18.mp3","sents":[{"ar":"في الليل، أريدك أن تضعيني تحت كرة زجاجية.","zh":"夜晚，请您把我罩在玻璃球里。","t":[103,5237]},{"ar":"حيث تعيش بارد جدًا جدًا.","zh":"你住的地方非常寒冷。","t":[5237,8632]},{"ar":"في المكان الذي أتيت منهـ\"","zh":"在我来的那个地方——","t":[8632,10658]}]},{"id":"ch08p19","audio":"ch08p19.mp3","sents":[{"ar":"لكنها قطعت نفسها عند ذلك النقطة.","zh":"她话未说完便打住了。","t":[103,3882]},{"ar":"كانت قد جاءت على شكل بذرة.","zh":"她以种子的形式降临。","t":[3882,6974]},{"ar":"لم تكن تعرف شيئًا عن العوالم الأخرى.","zh":"她不可能了解任何其他世界。","t":[6974,11013]},{"ar":"خجلت من أن تكون قد وقعت في مثل هذا الثرثرة الجهلاء، فسعلت مرتين أو ثلاث مرات لترتكب خطأ الأمير الصغير.","zh":"羞愧于让自己陷入如此幼稚谎言的边缘，她咳嗽了两三声，企图让小王子承担过错。","t":[11013,20224]}]},{"id":"ch08p20","audio":"ch08p20.mp3","sents":[{"ar":"هل لديك شاشة؟","zh":"您有屏风吗？","t":[103,1445]}]},{"id":"ch08p21","audio":"ch08p21.mp3","sents":[{"ar":"كنت أحاول البحث عنها عندما تحدثت إليّ…","zh":"我正要去找，是你和我说话的呀……","t":[103,3458]}]},{"id":"ch08p22","audio":"ch08p22.mp3","sents":[{"ar":"ثم أجبرت نفسها على السعال بصوت أعلى قليلاً حتى يشعر هو أيضًا بالندم.","zh":"她故意咳嗽得更重，让他也感到内疚。","t":[103,6142]}]},{"id":"ch08p23","audio":"ch08p23.mp3","sents":[{"ar":"لقد بدأ الأمير الصغير يشك في الوردة، رغم الطيبة التي كان يحملها في حبه لها.","zh":"尽管小王子对她的爱中充满了善意，但他很快便开始怀疑她了。","t":[103,7697]},{"ar":"كان يأخذ الكلمات بجدية، وهي دون أهمية، مما جعله حزيناً جدًا.","zh":"他认真对待了无关紧要的话语，这让他非常不快乐。","t":[7697,13974]}]},{"id":"ch08p24","audio":"ch08p24.mp3","sents":[{"ar":"كان يجب أن لا أستمع إليها.","zh":"我那天不该听她的话。","t":[103,3461]},{"ar":"لا يجب على أحد الاستماع إلى الزهور.","zh":"永远也别信花儿讲的话。","t":[3461,7355]},{"ar":"يجب ببساطة النظر إليها واستنشق رائحتها.","zh":"只需凝视它们，感受它们的芬芳。","t":[7355,12382]},{"ar":"كانت زهرة كوكبي تُعطره.","zh":"我的星球上弥漫着花香。","t":[12382,15487]},{"ar":"لكن لم أعرف كيف أستمتع بكل جمالها.","zh":"但我不知如何享受她的所有优雅。","t":[15487,19632]},{"ar":"هذه الحكاية عن الأنياب التي أزعجتني كثيرًا، كان يجب أن تملأ قلبي الرأفة والشفقة فقط.","zh":"这关于爪子的故事，本应只在我心中激起温柔与怜悯。","t":[19632,27355]}]},{"id":"ch08p25","audio":"ch08p25.mp3","sents":[{"ar":"وواصل سردها.","zh":"他继续倾诉着。","t":[103,1524]}]},{"id":"ch08p26","audio":"ch08p26.mp3","sents":[{"ar":"الحقيقة هي أنني لم أعرف كيف أفهم أي شيء!","zh":"事实上，我并不懂得如何理解任何事物！","t":[103,4908]},{"ar":"يجب أن أقوم بالحكم بالأفعال وليس بالكلمات.","zh":"应凭行为而非言语来评判。","t":[4908,9987]},{"ar":"لقد أرسلت نصًا طويلاً يتضمن عدة جمل، بينما كان المطلوب هو ترجمة جملة واحدة. سأقوم الآن بترجمة الجملة المطلوبة فقط:\n\nلقد أرسلت رائحتها وضوءها علي.","zh":"她的芬芳与光辉洒落在我身上。","t":[9987,27026]},{"ar":"لم أكن يجب أن أهرب منها...","zh":"我本不该逃离她……","t":[27026,30276]},{"ar":"كان يجب أن أتوقع كل الحب الذي كان وراء تلك الخدع الصغيرة التي كانت تستخدمها.","zh":"我本应猜透她那可怜的小伎俩背后深藏的柔情。","t":[30276,37921]},{"ar":"الزهور غير مستقرة جدًا!","zh":"花儿真是反复无常！","t":[37921,41303]},{"ar":"لكن كنت صغيرًا جدًا لأعرف كيف أحبها...","zh":"那时我还太年轻，不懂如何去爱她……","t":[41303,44855]}]}]},{"id":"ch09","title_ar":"الفصل التاسع","title_en":"Chapter IX","title_zh":"第 9 章","paras":[{"id":"ch09p00","audio":"ch09p00.mp3","sents":[{"ar":"أعتقد أن لجمعه الهروب، استفاد من هجرة قطيع من الطيور البرية.","zh":"他可能是趁着那群野鸟迁徙之际逃离的。","t":[103,6724]},{"ar":"في صباح يوم رحيله رتب كوكبه بشكل تام؛ نظف براكينه النشطة بعناية.","zh":"他离开那天早晨，把他的星球整理得井井有条。","t":[6724,14526]},{"ar":"يُنظف براكينه النشطة بعناية","zh":"他仔细清理了他的活火山。","t":[14526,17237]},{"ar":"كان لديه بركانين نشطين، ملائمين تمامًا لتسخين فطوره في الصباح.","zh":"他拥有两座活火山，早晨煮早餐极为方便。","t":[17237,24289]},{"ar":"كان لديه بركانًا منقرضًا.","zh":"他还拥有一座熄灭的火山。","t":[24289,27566]},{"ar":"لكن، كما قال، \"لا يمكن أن يعرف أحد!\" لذا، نظف أيضًا بركانًا متوقفًا عن التوهج، لأنه إذا نظف البراكين جيدًا، تضيء بلطف وتنظم، دون أي انفجارات. إن الانفجارات البركانية مثل نيران المدفأة. ونحن على الأرض صغار جدًا بالطبع، لذا لا نظف براكيننا، لذا تسبب لنا في الكثير من المتاعب.","zh":"然而，正如他所说：“世事难料！”于是，他也清理了那座死火山。","t":[27566,57474]},{"ar":"إذا كانت محتملة جيدًا، تنضج البراكين ببطء واستقرار، دون أي انفجارات.","zh":"火山清理得当，火焰便缓缓而稳定地燃烧，不会喷发。","t":[57474,65237]},{"ar":"انفجارات البراكين تشبه نيران المدفأة في المدخنة.","zh":"火山喷发犹如烟囱中的火焰。","t":[65237,69579]}]},{"id":"ch09p01","audio":"ch09p01.mp3","sents":[{"ar":"نحن على الأرض صغار جدًا بالطبع، فلا نكنس براكيننا، لذلك تتسبب لنا في كثير من المتاعب.","zh":"在我们地球上，我们显然太小了，无法清理我们的火山。","t":[103,9447]},{"ar":"هذا السبب الذي يجلب لنا الكثير من المتاعب.","zh":"这便是它们给我们带来无尽烦恼的原因。","t":[9447,13014]}]},{"id":"ch09p02","audio":"ch09p02.mp3","sents":[{"ar":"الأمير الصغير أزال أيضًا، بروح الإحباط، آخر الشتلات الصغيرة من الشجيرات الكبيرة.","zh":"小王子带着一丝沮丧，拔除了最后几株猴面包树苗。","t":[103,8184]},{"ar":"لن أريد العودة أبدًا.","zh":"他坚信自己不会再想回来。","t":[8184,11026]},{"ar":"لكن في هذا الصباح الأخير، بدا جميع هذه المهام المألوفة له قيمًا جدًا.","zh":"然而，在这最后的早晨，所有这些熟悉的任务在他看来都变得异常珍贵。","t":[11026,18000]},{"ar":"وعندما قام بغسل الزهرة لأخر مرة، وأعد لوضعها تحت غطاء كرة الزجاج، أدرك أن قلبه على حافة الدموع.","zh":"最后一次为花儿浇水，准备给她罩上玻璃罩，他意识到自己几乎要泪流满面了。","t":[18000,27500]}]},{"id":"ch09p03","audio":"ch09p03.mp3","sents":[{"ar":"وداعاً، قال للأميرة.","zh":"再见，他对花儿说。","t":[103,2221]}]},{"id":"ch09p04","audio":"ch09p04.mp3","sents":[{"ar":"لكنها لم تجب.","zh":"她默然不语。","t":[103,1577]}]},{"id":"ch09p05","audio":"ch09p05.mp3","sents":[{"ar":"وداعًا، قال مرة أخرى.","zh":"再见，他又说。","t":[103,2510]}]},{"id":"ch09p06","audio":"ch09p06.mp3","sents":[{"ar":"الزهرة صارت تزفر.","zh":"花儿轻咳。","t":[103,2711]},{"ar":"لكن لم يكن لأنها كانت مصابة بالبرد.","zh":"但并非因为她感冒了。","t":[2711,5961]}]},{"id":"ch09p07","audio":"ch09p07.mp3","sents":[{"ar":"لقد كنت سخيفة. أرجوك سامحني. حاول أن تكون سعيدًا.","zh":"她终于对他说：“我真是愚蠢。”","t":[103,7684]},{"ar":"أرجوك أغفر لي.","zh":"请原谅我。","t":[7684,10053]},{"ar":"حاول أن تكون سعيدًا...","zh":"试着快乐吧……","t":[10053,11881]}]},{"id":"ch09p08","audio":"ch09p08.mp3","sents":[{"ar":"فوجئ بغياب الإدانة هذا.","zh":"她对他的离去毫无责怪。","t":[103,3184]},{"ar":"كان الأمير الصغير مستغربًا واقفًا هناك، يحمل كرة الزجاج محكومًا في منتصف الهواء.","zh":"他愣愣地站在那里，手中的玻璃罩悬停在半空。","t":[3184,11158]},{"ar":"لم يفهم هذا الحلوة الهادئة.","zh":"他不懂这宁静的甜美。","t":[11158,13342]}]},{"id":"ch09p09","audio":"ch09p09.mp3","sents":[{"ar":"بالطبع، أحبك، قالت الزهرة له.","zh":"当然，我爱你。","t":[103,4276]},{"ar":"لقد كنت السبب في أن لم تعرف ذلك طوال الوقت.","zh":"你一直未曾察觉到，这全是我的过错。","t":[4276,8776]},{"ar":"هذا لا يهم.","zh":"那无关紧要。","t":[8776,10908]},{"ar":"لكن أنتـكـمـا قد كنـا غبـيـاءـنـيـن مثـلـي.","zh":"但你——你也和我一样傻。","t":[10908,14079]},{"ar":"حاول أن تكون سعيدًا...","zh":"试着快乐吧……","t":[14079,16789]},{"ar":"اتركوا كرة الزجاج تذهب إلى الجحيم.","zh":"让玻璃罩见鬼去吧。","t":[16789,20789]},{"ar":"لست بحاجة إليه بعد الآن.","zh":"我不再需要它了。","t":[20789,23171]}]},{"id":"ch09p10","audio":"ch09p10.mp3","sents":[{"ar":"لكن الريح...","zh":"但风……","t":[103,1248]}]},{"id":"ch09p11","audio":"ch09p11.mp3","sents":[{"ar":"ليس مرضي سيئًا جدًا...","zh":"我的感冒并没有那么严重……","t":[103,3171]},{"ar":"البرد الليلي المعتدل سيكون مفيدًا لي.","zh":"清新的夜风对我大有裨益。","t":[3171,7513]},{"ar":"أنا زهرة.","zh":"我是一朵花。","t":[7513,8461]}]},{"id":"ch09p12","audio":"ch09p12.mp3","sents":[{"ar":"لكن الحيوانات...","zh":"但那些动物——","t":[103,1668]}]},{"id":"ch09p13","audio":"ch09p13.mp3","sents":[{"ar":"إذا كنت أريد التعرف على الفراشات، يجب أن أتحمل وجود بضعة خيطيات.","zh":"我若想结识蝴蝶，就得忍受两三条毛虫的陪伴。","t":[103,7316]},{"ar":"يبدو أنهم جميلون جدًا.","zh":"它们似乎非常美丽。","t":[7316,10434]},{"ar":"وإذا لم تأتي الفراشات... وماذا عن الحوريات؟","zh":"蝴蝶不来，毛虫又何来拜访我呢？","t":[10434,16158]},{"ar":"ستكون بعيدًا...","zh":"你将远行……","t":[16158,18513]},{"ar":"حول الكائنات الكبيرة-- أنا لا أخاف منها على الإطلاق.","zh":"至于大动物——我一点也不怕它们。","t":[18513,24487]},{"ar":"لدي مخالب.","zh":"我有我的爪子。","t":[24487,25750]}]},{"id":"ch09p14","audio":"ch09p14.mp3","sents":[{"ar":"ثم ببساطة كشفت عن أربعة شوكها.","zh":"她天真地伸出她的四根刺。","t":[103,4211]},{"ar":"ثم أضافت:","zh":"她接着说：","t":[4211,5303]}]},{"id":"ch09p15","audio":"ch09p15.mp3","sents":[{"ar":"لا تتجول هكذا.","zh":"别这样拖延。","t":[103,2684]},{"ar":"لقد قررت الرحيل.","zh":"你已决定离去。","t":[2684,5184]},{"ar":"اذهب الآن!","zh":"那就走吧。","t":[5184,6250]}]},{"id":"ch09p16","audio":"ch09p16.mp3","sents":[{"ar":"لم تكن تريد أن يراه يبكي.","zh":"她不愿让他看到自己哭泣。","t":[103,3355]},{"ar":"كانت الزهرة فاخرة جدًا...","zh":"她是一朵多么骄傲的花儿……","t":[3355,5671]}]}]},{"id":"ch10","title_ar":"الفصل العاشر","title_en":"Chapter X","title_zh":"第 10 章","paras":[{"id":"ch10p00","audio":"ch10p00.mp3","sents":[{"ar":"وجد نفسه في جوار الكواكب 325، 326، 327، 328، 329، و330.","zh":"他发现自己来到了小行星325号、326号、327号、328号、329号和330号所在的地区。","t":[103,19685]},{"ar":"بدأ يزورهم ليزيد من معرفته.","zh":"于是他开始逐一拜访，以增长见识。","t":[19685,20185]}]},{"id":"ch10p01","audio":"ch10p01.mp3","sents":[{"ar":"الكوكب الأول كان يسكنه ملك.","zh":"那颗星球上住着一位国王。","t":[103,3816]},{"ar":"لبس الأمير الصغير ثوبًا ملكيًا من البُرُدي والفُرس، وجلس على عرش بسيط ومهيب.","zh":"身着皇家紫袍与貂皮，他端坐在既简单又威严的宝座上。","t":[3816,10829]}]},{"id":"ch10p02","audio":"ch10p02.mp3","sents":[{"ar":"أوه!","zh":"啊！","t":[103,1526]},{"ar":"\"ها هو موضوع، قال الملك عندما رأى الأمير الصغير قادما:\"","zh":"“来了一位臣民，”国王看见小王子走来，大声说道。","t":[1526,6171]}]},{"id":"ch10p03","audio":"ch10p03.mp3","sents":[{"ar":"وكان الأمير الصغير يتساءل لنفسه:","zh":"小王子自问：","t":[103,3010]}]},{"id":"ch10p04","audio":"ch10p04.mp3","sents":[{"ar":"كيف يمكن له أن يتعرف علي عندما لم يره من قبل؟","zh":"他从未见过我，怎能认出我呢？","t":[103,4352]}]},{"id":"ch10p05","audio":"ch10p05.mp3","sents":[{"ar":"لم يكن يعرف أن العالم بالنسبة إلى الملوك يُبسط للغاية، فجميع الناس رعايا لهم.","zh":"国王们眼中，世界变得简单了。","t":[103,7882]},{"ar":"في نظرهم، جميع البشر ملوكهم.","zh":"在他们眼中，世人皆为臣民。","t":[7882,11000]}]},{"id":"ch10p06","audio":"ch10p06.mp3","sents":[{"ar":"اقترب قليلاً كي أتمكن من رؤيتك على نحو أفضل، قال الملك الذي شعر بفخر جامح لأن لديه أخيرًا من يستطيع أن يكون ملكًا عليه.","zh":"“走近些，让我好好端详你，”国王说，他因终于统治了某个臣民而感到无比自豪。","t":[103,10590]}]},{"id":"ch10p07","audio":"ch10p07.mp3","sents":[{"ar":"الأمير الصغير نظر في كل مكان ليجد مكانًا للجلوس؛ ولكن كامل الكوكب كان ممتلئًا ومحجوبًا بثوب الدببة الملكي الرائع.","zh":"小王子环顾四周，寻找可坐之处；但整个星球已被国王那华丽的貂皮袍子塞满，无处下脚。","t":[103,11237]},{"ar":"بقي مستقيماً، وقد كان متعبًا، فأخذ يهمس.","zh":"他挺直了身子站立，由于疲惫，他打了个哈欠。","t":[11237,15592]}]},{"id":"ch10p08","audio":"ch10p08.mp3","sents":[{"ar":"من غير اللائق أن تتثاءب بحضور الملك.","zh":"在国王面前打哈欠，有失礼节。","t":[103,4145]},{"ar":"أنا أمنعك من فعل ذلك.","zh":"我禁止你这么做。","t":[4145,6237]}]},{"id":"ch10p09","audio":"ch10p09.mp3","sents":[{"ar":"لا أستطيع المقاومة؛ لقد قمت برحلة طويلة ولم أنم قط...","zh":"我忍不住了。","t":[103,6053]},{"ar":"لا أستطيع مقاومة، لقد قمت برحلة طويلة ولم أنم قط...","zh":"我忍不住了，小王子回答说，满脸尴尬。","t":[6053,12079]},{"ar":"لقد جئت في رحلة طويلة ولم أنم قط...","zh":"我长途跋涉，未曾合眼……","t":[12079,15382]}]},{"id":"ch10p10","audio":"ch10p10.mp3","sents":[{"ar":"أه، إذن، قال الملك.","zh":"啊，那么，国王说。","t":[103,3382]},{"ar":"أمرتك بالسعال.","zh":"我命令你打哈欠。","t":[3382,5789]},{"ar":"منذ سنوات لم أر أحد يهمس.","zh":"多年来未见有人打哈欠了。","t":[5789,9316]},{"ar":"التنهدات، بالنسبة لي، هي أجسام من الفضول.","zh":"打哈欠在我眼里是件稀奇事。","t":[9316,14895]},{"ar":"تعال، الآن!","zh":"快点儿！","t":[14895,17434]},{"ar":"أنفخ مرة أخرى!","zh":"再打一个哈欠！","t":[17434,20039]},{"ar":"هذا أمر.","zh":"这是命令。","t":[20039,20974]}]},{"id":"ch10p11","audio":"ch10p11.mp3","sents":[{"ar":"هذا يخيفني...","zh":"这让我害怕……","t":[103,2237]},{"ar":"لا أستطيع، بعد الآن... همس الأمير الصغير، وهو الآن محتار تمامًا.","zh":"我无法再……小王子羞愧地低语。","t":[2237,9145]}]},{"id":"ch10p12","audio":"ch10p12.mp3","sents":[{"ar":"همم!","zh":"哼！","t":[103,1684]},{"ar":"هم! أجاب الملك.","zh":"哼！国王答道。","t":[1684,5013]},{"ar":"ثم أنا - أنا أمرك أحياناً بالسعال وأحياناً لا...","zh":"那么，我——我命令你有时打哈欠，有时不打——","t":[5013,9000]}]},{"id":"ch10p13","audio":"ch10p13.mp3","sents":[{"ar":"هو نثر بعض الكلمات، وبدى غاضبًا.","zh":"他咕哝了几句，似乎有些恼火。","t":[103,3365]}]},{"id":"ch10p14","audio":"ch10p14.mp3","sents":[{"ar":"ما كان يصر عليه الملك هو أن يتم احترام سلطانه.","zh":"国王根本坚持的是他的权威必须得到尊重。","t":[103,5066]},{"ar":"لا يتحمل أي تمرد.","zh":"他不容许任何违抗。","t":[5066,7961]},{"ar":"كان ملكًا مطلقًا.","zh":"他是一位绝对的君主。","t":[7961,10487]},{"ar":"لكن، لأنه كان رجلاً صالحًا جدًا، أصدر أوامره بمنطق.","zh":"然而，由于他是个非常善良的人，他发布的命令总是合情合理。","t":[10487,16118]}]},{"id":"ch10p15","audio":"ch10p15.mp3","sents":[{"ar":"إذا أمرت قائدًا بأن يتحول إلى طائر بحري، فإن لم يطع القائد الأمر، فإن ذلك ليس خطأ القائد بل خطأي لأنني أمرته بشيء مستحيل.","zh":"“假如我命令一位将军，”他举例说，“假如我命令他变成一只海鸟，而将军不服从，那责任不在将军。”","t":[103,12342]},{"ar":"هذا خطأ في التنفيذ، يجب أن أرجع إليك النص الأصلي باللغة العربية فقط، وليس النص بالكامل كما تم تقديمه. إليك النص الأصلي باللغة العربية:\n\n\"كانت خطأي.\"\n\nهذا هو النص الأصلي باللغة العربية.","zh":"那责任在我。","t":[12342,31474]}]},{"id":"ch10p16","audio":"ch10p16.mp3","sents":[{"ar":"هل يمكنني الجلوس؟ جاء الآن استفسار خجول من الأمير الصغير.","zh":"小王子怯生生地问道：“我可以坐下吗？”","t":[103,6039]}]},{"id":"ch10p17","audio":"ch10p17.mp3","sents":[{"ar":"أمرني الملك بفعل ذلك، وأجمع بفوقية ثوبه من فراء القوووس.","zh":"陛下如此命令，国王答道，威严地卷起他的貂皮披风。","t":[103,5958]}]},{"id":"ch10p18","audio":"ch10p18.mp3","sents":[{"ar":"لكن الأمير الصغير كان يتساءل...","zh":"小王子心中暗自思忖……","t":[103,3684]},{"ar":"الكوكب كان صغيرًا جدًا.","zh":"这颗星球小得可怜。","t":[3684,6829]},{"ar":"ما الذي يمكن لهذا الملك أن يحكمه حقًا؟","zh":"这位国王究竟能统治什么？","t":[6829,10039]}]},{"id":"ch10p19","audio":"ch10p19.mp3","sents":[{"ar":"يا صاحب الجلالة، سأطلب منك أن تسامحني على سؤالك سؤالاً—","zh":"陛下，他向他说道，请您原谅我向您提一个问题——","t":[103,5300]}]},{"id":"ch10p20","audio":"ch10p20.mp3","sents":[{"ar":"أمرني الملك بالسؤال، والملك عجل بضمانه: \"أنا أمرتك بطرح سؤال علي.\"","zh":"陛下急忙保证道：“我命令你向我提一个问题。”","t":[103,6839]}]},{"id":"ch10p21","audio":"ch10p21.mp3","sents":[{"ar":"يا سيد——ماذا تحكم عليه؟","zh":"陛下——您统治着什么？","t":[103,2681]}]},{"id":"ch10p22","audio":"ch10p22.mp3","sents":[{"ar":"الملك قال: \"على كل شيء،\" ببساطة مذهلة.","zh":"统治一切，国王以非凡的简洁说道。","t":[103,4392]}]},{"id":"ch10p23","audio":"ch10p23.mp3","sents":[{"ar":"هل تُحكمُ على كل شيء؟","zh":"统治一切？","t":[103,2037]}]},{"id":"ch10p24","audio":"ch10p24.mp3","sents":[{"ar":"الملك أومأ برأسه، وأخذت الإشارة كل كوكبه وكواكبه الأخرى والنجوم.","zh":"国王一挥手，涵盖了他的星球、其他星球以及所有星星。","t":[103,6642]}]},{"id":"ch10p25","audio":"ch10p25.mp3","sents":[{"ar":"هل تُحكمُ على كل هذا؟ سأل الأُمير الصغير.","zh":"统治这一切？小王子问道。","t":[103,4447]}]},{"id":"ch10p26","audio":"ch10p26.mp3","sents":[{"ar":"وعلى كل ذلك، قال الملك.","zh":"统治这一切？国王回答道。","t":[103,2629]}]},{"id":"ch10p27","audio":"ch10p27.mp3","sents":[{"ar":"كان حكمه ليس فقط مطلقًا: بل كان عالميًا أيضًا.","zh":"他的统治不仅是绝对的，而且是普遍的。","t":[103,4576]}]},{"id":"ch10p28","audio":"ch10p28.mp3","sents":[{"ar":"وهل تستمع النجوم لك؟","zh":"星星都听命于您吗？","t":[103,2142]}]},{"id":"ch10p29","audio":"ch10p29.mp3","sents":[{"ar":"بالطبع، قال الملك.","zh":"当然啦，国王说。","t":[103,2908]},{"ar":"هم يتبعون فورًا.","zh":"它们立刻服从。","t":[2908,5513]},{"ar":"لا أسمح بالتمرد.","zh":"我禁止违抗。","t":[5513,7158]}]},{"id":"ch10p30","audio":"ch10p30.mp3","sents":[{"ar":"كان ذلك قوة تُثير دهشة الأمير الصغير.","zh":"这股力量令小王子惊叹不已。","t":[103,4408]},{"ar":"إذا كان له سلطان كامل، كان يستطيع أن يشاهد غروب الشمس، ليس أربعًا وأربعين مرة في يوم واحد، بل سبعين أو حتى مئة أو مئة وثمانين مرة، دون أن يحرك كرسيه أبدًا.","zh":"若他拥有如此至高无上的权力，便能每日观赏七十二次，甚至一百次，甚至两百次日落，而无需挪动座椅。","t":[4408,20579]},{"ar":"ولأنه شعر بقليل من الحزن وهو يتذكر كوكبه الصغير الذي هجره، فقد أثنى على نفسه ليطلب من الملك معروفًا:","zh":"因为想起被他遗弃的小行星，他鼓起勇气向国王提出一个请求：","t":[20579,30184]}]},{"id":"ch10p31","audio":"ch10p31.mp3","sents":[{"ar":"أرغب في رؤية غروب شمس...","zh":"我想看看日落……","t":[103,3237]},{"ar":"من فضلكِ أفعلى هذا البركة...","zh":"请行此善举……","t":[3237,6382]},{"ar":"أعطِ الشمس أمرًا كي تغيب...","zh":"命令太阳落山……","t":[6382,8487]}]},{"id":"ch10p32","audio":"ch10p32.mp3","sents":[{"ar":"إذا أمرت قائدًا أن يطير من زهرة إلى أخرى كفراشة، أو يكتب مأساة، أو أن يحول نفسه إلى طائر بحري، ولم ينفذ القائد الأمر، فمن منا يكون على خطأ؟ قال الأمير الصغير بحزم: - أنت ستكون على خطأ. - تمامًا. على المرء أن يطلب من كل شخص ما يستطيعه، فالسلطة ترتكز أولًا وأخيرًا على العقل. إذا أمرت شعبك بأن يلقوا بأنفسهم إلى البحر، فإنك ستشعل ثورة. أنا لي الحق في طلب الطاعة لأن أوامري معقولة. - وماذا عن طلبي لغروب الشمس؟ ذكَّره الأمير الصغير بهذا الأمر، لأنه لم يكن ينسى أبدًا سؤالًا طرحه ذات مرة. - ستحصل على طلبك لغروب الشمس، سآمر به. لكن طبقًا لمنطق الحكومة العلمية سأتريث إلى أن تكون الظروف مؤاتية. سأل الأمير الصغير: - ومتى يكون ذلك؟ - هم! هم! (أجاب الملك مستشيرا روزنامته) سيكون ذلك حوالي... حوالي... سيكون ذلك هذا المساء حوالي الثامنة إلا ثلث. ولسوف ترى كم تُطاع أوامري. تثاءب الأمير الصغير، أسِف على أن يفوته غروب الشمس، وبدأ يشعر بالسأم. قال للملك: - ليس لدي ما أفعله هنا، سأمضي في طريقي. قال الملك الذي شعر بالفخر لحصوله على تابع: - لا ترحل، سأجعل منك وزيرًا. - وزيرًا لأي وزارة؟ - وزيرًا... وزيرًا للعدل. - لكن ما من أحد هنا لأحكم عليه! قال الملك: - نحن لا نعرف ذلك، فأنا لم أقم بعد بجولة كاملة على مملكتي. أنا متقدم في السن والمشي يتعبني، ولا مجال هنا من استخدام عربة. قال الأمير الصغير وهو ينحني ليلقي نظرة أخرى متفحصة على الجانب الآخر من الكوكب: - أوه! لقد نظرت الآن. أجاب الملك: - إن هذا لهو أصعب شيء على الإطلاق. إن من الصعب جدًّا أن تحكم نفسك، بل وأصعب من أن تحكم الآخرين. إن حكمت على نفسك بعدل، تكون حكيمًا جدًّا بالفعل. قال الأمير الصغير: - فيما يختص بي، أستطيع أن أحكم على نفسي حيثما كان. ليس علي أن أقيم هنا. قال الملك: - هم! هم! أعتقد بأنه يوجد جرذ عجوز في مكان ما على كوكبي، يمكنني أن أسمعه في الليل. يمكنك أن تحكم هذا الجرذ العجوز. ولسوف تحكم عليه بالموت من وقت إلى آخر. وهكذا تعتمد حياته على عدلك. لكن ستصفح عنه في كل مناسبة لكي تبقيه على قيد الحياة؛ إنه الوحيد لدينا. أجاب الأمير الصغير: - لا أحب أن أحكم على أي شيء بالموت، وأعتقد بأن عليَّ المضي في طريقي. قال الملك: - لا. وبعد أن أتم الأمير الصغير استعداداته، لم يشأ أن يؤذي مشاعر الملك العجوز، فقال: - إذا رغبت يا صاحب الجلالة في أن تُطاع فورًا، فعليك أن تعطيني أمرًا معقولًا. تستطيع مثلًا أن تأمرني بالرحيل في أقل من دقيقة. يبدو لي أن الظروف ملائمة. وعندما لم يقل الملك شيئًا، تردد الأمير لحظة، ثم غادر متنهدًا. صاح الملك بسرعة: - سأجعلك سفيرًا لي. وكان لديه فراغ كبير في السلطة. قال الأمير الصغير وهو يتابع رحلته: - إن الكبار غريبو الأطوار!","zh":"陛下质问道：“若我命令一位将军像蝴蝶般在花间飞舞，或撰写一部悲剧，或变成海鸟，而将军不遵从命令，那么，错的是我们中的哪一个？”","t":[103,255947]},{"ar":"الجيش، أم أنا؟","zh":"将军，还是我自己？","t":[255947,258390]}]},{"id":"ch10p33","audio":"ch10p33.mp3","sents":[{"ar":"أنت، قال الأمير الصغير بثبات.","zh":"“你，”小王子坚定地说。","t":[103,2931]}]},{"id":"ch10p34","audio":"ch10p34.mp3","sents":[{"ar":"بالضبط.","zh":"正是如此。","t":[103,1789]},{"ar":"كل شخص يجب أن يطلب من كل شخص ما يمكنه القيام به، قال الملك.","zh":"国王继续说道：“每个人都必须尽其所能履行职责。”","t":[1789,8303]},{"ar":"السلطة المقبولة ترتكز أولاً على العقل.","zh":"权威首先建立在理性之上。","t":[8303,12592]},{"ar":"إذا أمرت شعبك بأن يلقوا بأنفسهم إلى البحر، فإنك ستشعل ثورة.","zh":"若你命令你的子民跳海，他们便会起义反抗。","t":[12592,19184]},{"ar":"لدي الحق في طلب الطاعة لأن أوامري معقولة.","zh":"我有权要求服从，因为我的命令合乎情理。","t":[19184,22908]}]},{"id":"ch10p35","audio":"ch10p35.mp3","sents":[{"ar":"ثم غروبي؟ ذكّرني الأمير الصغير: لأنه لا ينسى سؤالاً بعد أن يطرحه.","zh":"“那么，我的日落呢？”小王子提醒他，因为他一旦提出问题就绝不会忘记。","t":[103,7066]}]},{"id":"ch10p36","audio":"ch10p36.mp3","sents":[{"ar":"ستشاهد غروب شمسك، أرجوك، حقق لي ذلك، أعطِ الشمس أمرًا كي تغيب...","zh":"你将看到你的日落。","t":[103,7737]},{"ar":"أمرته بالاستسلام.","zh":"我命令它。","t":[7737,10329]},{"ar":"لكن، وفقًا علمي الحكومي، سأنتظر حتى تكون الظروف ملائمة.","zh":"但根据我的治国之策，我将等待时机成熟。","t":[10329,16053]}]},{"id":"ch10p37","audio":"ch10p37.mp3","sents":[{"ar":"لماذا سيكون ذلك؟ سأل الأمير الصغير.","zh":"小王子问道：“那会是什么时候？”","t":[103,4407]}]},{"id":"ch10p38","audio":"ch10p38.mp3","sents":[{"ar":"همم!","zh":"哼！","t":[103,1684]},{"ar":"هم! أجاب الملك وقد استشرف في دفتره الكبير.","zh":"哼！国王答道，随即查阅了一本厚重的星历。","t":[1684,7316]},{"ar":"همم!","zh":"哼！","t":[7316,8894]},{"ar":"هم!","zh":"哼！","t":[8894,10237]},{"ar":"سيكون ذلك حوالي... حوالي... سيكون ذلك هذا المساء حوالي الثامنة إلا ثلث.","zh":"大约——大约——今晚八点差二十分左右。","t":[10237,19421]},{"ar":"وسترى كيف تُطاع أوامري بشكل جيد.","zh":"你将见识到我的命令被遵从得多么得体。","t":[19421,22632]}]},{"id":"ch10p39","audio":"ch10p39.mp3","sents":[{"ar":"الأمير الصغير ابتسم.","zh":"小王子打了个哈欠。","t":[103,2882]},{"ar":"كان يتأسف على فقدانه للشفق.","zh":"他惋惜那失去的日落。","t":[2882,6526]},{"ar":"ثم، أصبح يبدأ يشعر بالملل قليلاً.","zh":"他渐渐开始感到有些无聊了。","t":[6526,10263]}]},{"id":"ch10p40","audio":"ch10p40.mp3","sents":[{"ar":"ليس لدي ما أفعله هنا، سأمضي في طريقي.","zh":"“我在这里已无事可做，”他对国王说。","t":[103,4829]},{"ar":"سأبدأ مرة أخرى في رحلتي.","zh":"我将再次踏上旅程。","t":[4829,7224]}]},{"id":"ch10p41","audio":"ch10p41.mp3","sents":[{"ar":"لا تذهب، قال الملك الذي كان فخورًا بوجود مُنصبٍ تحت إمرته.","zh":"“别走，”国王说，他对拥有一个臣民感到非常自豪。","t":[103,6197]},{"ar":"لا تذهب.","zh":"别走。","t":[6197,7934]},{"ar":"سأجعلك وزيرًا.","zh":"我封你为部长！","t":[7934,9592]}]},{"id":"ch10p42","audio":"ch10p42.mp3","sents":[{"ar":"من وزير ما؟","zh":"司法部长？","t":[103,1208]}]},{"id":"ch10p43","audio":"ch10p43.mp3","sents":[{"ar":"وزير العدل!","zh":"司法部长！","t":[103,1194]}]},{"id":"ch10p44","audio":"ch10p44.mp3","sents":[{"ar":"ليس هنا أحد ليحكم!","zh":"但这里无人可审。","t":[103,1985]}]},{"id":"ch10p45","audio":"ch10p45.mp3","sents":[{"ar":"لا نعرف ذلك، قال الملك له.","zh":"“我们并不知道，”国王对他说。","t":[103,3605]},{"ar":"لم أزور بعد ملكيتي بالكامل.","zh":"我尚未巡游完我的王国。","t":[3605,7276]},{"ar":"أنا عجوز جدًا.","zh":"我年事已高。","t":[7276,9737]},{"ar":"لا مكان هنا لخيمة.","zh":"这里容不下马车。","t":[9737,12408]},{"ar":"يصيبني الملل من المشي.","zh":"行走令我疲惫不堪。","t":[12408,14447]}]},{"id":"ch10p46","audio":"ch10p46.mp3","sents":[{"ar":"أوه، لكنني قد نظرت بالفعل! قال الأمير الصغير، وهو يلتفت ليراقب الجانب الآخر من الكوكب مرة أخرى.","zh":"哦，但我已经看过了！小王子转身，又朝星球的另一端瞥了一眼。","t":[103,11026]},{"ar":"في ذلك الجانب، كما في هذا الجانب، لم يكن هناك أحد على الإطلاق...","zh":"在那一边，就像这边一样，根本无人居住。","t":[11026,16605]}]},{"id":"ch10p47","audio":"ch10p47.mp3","sents":[{"ar":"ثم ستحكم على نفسك، قال الملك.","zh":"那么，你将自我审判。","t":[103,4145]},{"ar":"هذا أصعب شيء على الإطلاق. إنه من الصعب جدًا أن تحكم نفسك، بل وأصعب من أن تحكم الآخرين.","zh":"这是最难的事。","t":[4145,13934]},{"ar":"يصعب على الإنسان أن يقيّم نفسه أكثر من قيامه بقياس الآخرين.","zh":"评判自己远比评判他人困难。","t":[13934,20053]},{"ar":"إذا كنت تُحكم نفسك بشكل صحيح، فإنك بالفعل رجل حكيم حقيقي.","zh":"若能正确审判自己，你便真正成为智者。","t":[20053,26118]}]},{"id":"ch10p48","audio":"ch10p48.mp3","sents":[{"ar":"نعم، قال الأمير الصغير، \"لكنني أستطيع أن أقضي حكمي على نفسي في أي مكان.","zh":"是的，小王子说，“但我在任何地方都能审判自己。”","t":[103,8053]},{"ar":"لا أحتاج إلى العيش على هذا الكوكب.","zh":"我不必居住在这颗星球上。","t":[8053,10763]}]},{"id":"ch10p49","audio":"ch10p49.mp3","sents":[{"ar":"همم!","zh":"哼！","t":[103,1684]},{"ar":"هم! قال الملك.","zh":"哼！国王说道。","t":[1684,4895]},{"ar":"أنا أعتقد أن هناك فأراً عجوزاً في مكان ما على كوكبي، يمكنني سماعه في الليل. يمكنك أن تحكم على هذا الفأر العجوز.","zh":"在这颗星球上，我确信某个角落住着一只老耗子。","t":[4895,16526]},{"ar":"سمعته في الليل","zh":"我在夜里听到他。","t":[16526,17776]},{"ar":"يمكنك الحكم على هذا الفأر العجوز.","zh":"你可以审判这只老耗子。","t":[17776,21500]},{"ar":"من وقت لآخر ستقوم بتحكيمه على الإعدام.","zh":"时而将他判处死刑。","t":[21500,26158]},{"ar":"حياته تعتمد على عدلك.","zh":"他的生命将取决于你的公正。","t":[26158,29355]},{"ar":"لكن في كل مناسبة يجب أن تعفو عنه؛ لأنه يجب أن يتم التعامل معه باقتصاد.","zh":"但每次你都得赦免他；因为他必须被节省使用。","t":[29355,37237]},{"ar":"هو الوحيد الذي نملكه.","zh":"他是我们唯一拥有的。","t":[37237,39013]}]},{"id":"ch10p50","audio":"ch10p50.mp3","sents":[{"ar":"لا أريد أن أدان أي أحد إلى الموت.","zh":"我不愿将任何人判处死刑。","t":[103,3803]},{"ar":"والآن أفكر في أنني سأواصل رحلتي.","zh":"现在我想继续我的旅程了。","t":[3803,7105]}]},{"id":"ch10p51","audio":"ch10p51.mp3","sents":[{"ar":"لا، قال الملك.","zh":"“不，”国王说。","t":[103,1760]}]},{"id":"ch10p52","audio":"ch10p52.mp3","sents":[{"ar":"لكن الأمير الصغير، بعد أن أنهى إعدادات رحيله، لم يكن يريد أن يجرح مشاعر الملك العجوز.","zh":"但小王子完成离行准备后，不愿让老国王感到悲伤。","t":[103,7905]}]},{"id":"ch10p53","audio":"ch10p53.mp3","sents":[{"ar":"إذا كان جلالتك يرغب في أن يتم اتباع أوامره بسرعة، يجب أن يكون قادرًا على إعطاء أوامر معقولة.","zh":"陛下若欲令行禁止，便应能下达合理的命令。","t":[103,9421]},{"ar":"يمكنه أن يأمرني بالرحيل في أقل من دقيقة. يبدو لي أن الظروف ملائمة.","zh":"他可以命令我，比如说，在一分钟内离开。","t":[9421,17092]},{"ar":"يبدو لي أن الظروف ملائمة...","zh":"在我看来，条件似乎很适宜……","t":[17092,19290]}]},{"id":"ch10p54","audio":"ch10p54.mp3","sents":[{"ar":"لم يجب الملك، فتردد الأمير الصغير لحظة.","zh":"国王沉默不语，小王子犹豫了片刻。","t":[103,4684]},{"ar":"ثم، ببكاء، قال وداعًا.","zh":"带着一声叹息，他告辞离去。","t":[4684,7657]}]},{"id":"ch10p55","audio":"ch10p55.mp3","sents":[{"ar":"أعلن الملك: \"جعلتك سفيري\"، بسرعة.","zh":"我封你为大使。","t":[103,3695]}]},{"id":"ch10p56","audio":"ch10p56.mp3","sents":[{"ar":"كان له جو رائع من السلطة.","zh":"他威严非凡。","t":[103,2576]}]},{"id":"ch10p57","audio":"ch10p57.mp3","sents":[{"ar":"الكبار غريبون!","zh":"大人们真是奇怪，小王子边走边自言自语。","t":[103,1642]}]}]},{"id":"ch11","title_ar":"الفصل الحادي عشر","title_en":"Chapter XI","title_zh":"第 11 章","paras":[{"id":"ch11p00","audio":"ch11p00.mp3","sents":[{"ar":"الكوكب الثاني كان يسكنه رجل مرائي، صاح عن بعد عندما نظر إلى الأمير الصغير: - لقد جاء شخص معجب بنفسه! فإن الرجال المرائيون يرون جميع الرجال معجبين بأنفسهم. قال الأمير الصغير: - صباح الخير، أنت ترتدي قبعة مضحكة. أجاب المرائي: - إنها قبعة ترحاب، أرفعها عندما يهلل لي الناس. لسوء الحظ، لا أحد يمر على هذه الطريق. - حقًا؟ (قال الأمير الصغير الذي لم يفهم ما الذي يتحدث عنه المرائي). وقال المرائي نصحًا: - اضغط بيديك. ضغط الأمير الصغير بيديه. رفع المرائي قباعته في تحية متواضعة. قال الأمير الصغير لنفسه: « إن هذا أكثر إثارة من زيارتنا إلى الملك »، وحاول أن يضغط بيديه ثانية. ومرة أخرى رفع المرائي قباعته في تحية. وبعد خمس دقائق من هذا التمرين سئم الأمير الصغير من رتابة اللعبة. سأله: - ولكي تخفض قباعتك، ماذا ينبغي للمرء أن يفعل؟ لكن المرائي لم يسمعه، فإن المرائيون يسمعون المديح فقط. - هل أنت معجب بي كثيرًا؟ سأل الأمير الصغير: - وماذا تعني كلمة (معجب)؟ - (معجب بـ) تعني أن تعدني الشخص الأكثر وسامة، الأكثر أناقة، الأغنى والأذكى في هذا الكوكب. - لكنك وحيد على كوكبك! - قدم لي هذه الخدمة. أعبر عن إعجابك بي! قال الأمير الصغير وهو يهز كتفيه بلا مبالاة: - إنني معجب بك، لكن لماذا ينبغي أن يعني ذلك لك الكثير؟ ورحل الأمير الصغير، وقال لنفسه وهو يتابع رحلته: « إن الكبار غريبون حقًا ».","zh":"第二颗星球住着一个自负的人。","t":[103,127934]}]},{"id":"ch11p01","audio":"ch11p01.mp3","sents":[{"ar":"أوه!","zh":"啊！","t":[103,1526]},{"ar":"آه!","zh":"啊！","t":[1526,2842]},{"ar":"أنا على وشك استقبال زيارة من معجب! هلهل من فرجه عندما رآني الأمير الصغير يأتي.","zh":"他远远望见小王子走来，便大声喊道：“我正要接待一位崇拜者！”","t":[2842,10632]}]},{"id":"ch11p02","audio":"ch11p02.mp3","sents":[{"ar":"لأن، بالنسبة للمرائيين، جميع البشر مجدون.","zh":"对自负的人来说，所有人都是崇拜者。","t":[103,4642]}]},{"id":"ch11p03","audio":"ch11p03.mp3","sents":[{"ar":"صباح الخير، قال الأمير الصغير.","zh":"早上好，小王子说。","t":[103,3921]},{"ar":"هذا القبعة التي ترتديها غريبة للغاية","zh":"这顶帽子戴得真古怪。","t":[3921,7421]}]},{"id":"ch11p04","audio":"ch11p04.mp3","sents":[{"ar":"هذا القبعة للاحترام، أجاب المرائي.","zh":"这顶帽子是敬礼用的。","t":[103,4382]},{"ar":"هذا القبعة لرفعها في التحية عندما يصفق لي الناس","zh":"这顶帽子是人们欢呼时用来敬礼的。","t":[4382,8566]},{"ar":"للأسف، لا أحد يمر بهذه الطريق أبداً.","zh":"可惜，从来没有人经过这里。","t":[8566,12329]}]},{"id":"ch11p05","audio":"ch11p05.mp3","sents":[{"ar":"نعم؟ قال الأمير الصغير الذي لم يفهم ما الذي يتحدث عنه المرائي.","zh":"小王子问道：“什么？”他不懂这位自负的人究竟在说什么。","t":[103,6197]}]},{"id":"ch11p06","audio":"ch11p06.mp3","sents":[{"ar":"صفق بيديك، يا أمير الصغير، يديك ضد بعضها البعض، قال المرائي الآن.","zh":"请用手掌相击，一只手对另一只手，自负的人现在这样指示他。","t":[103,6616]}]},{"id":"ch11p07","audio":"ch11p07.mp3","sents":[{"ar":"الأمير الصغير ضرب بيديه.","zh":"小王子拍起了手。","t":[103,3263]},{"ar":"المرائي رفع قباعته في تحية متواضعة.","zh":"自负的人谦恭地举帽致意。","t":[3263,6894]}]},{"id":"ch11p08","audio":"ch11p08.mp3","sents":[{"ar":"هذا أكثر إثارة من زيارة الملك، قال للأمير الصغير لنفسه.","zh":"这比拜访国王有趣多了，小王子自言自语道。","t":[103,6237]},{"ar":"وبدأ الأمير الصغير يضرب بيديه، واحدة بaltra.","zh":"他再次开始拍手，一只手对另一只手。","t":[6237,11026]},{"ar":"المرائي رفع ربطة عنقه في تحية.","zh":"自负的人举起帽子行礼。","t":[11026,14079]}]},{"id":"ch11p09","audio":"ch11p09.mp3","sents":[{"ar":"بعد خمس دقائق من هذا التمرين شعر الأمير الصغير بالملل من رتابة اللعبة.","zh":"五分钟后，小王子对这场单调的游戏感到厌倦。","t":[103,5945]}]},{"id":"ch11p10","audio":"ch11p10.mp3","sents":[{"ar":"لكي يُنزل القبعة، ماذا ينبغي للمرء أن يفعل؟","zh":"他问道：“那怎样才能让这顶帽子放下呢？”","t":[103,4169]}]},{"id":"ch11p11","audio":"ch11p11.mp3","sents":[{"ar":"لكن المرائي لم يسمعه.","zh":"但自负的人没有听见他。","t":[103,3013]},{"ar":"المرائيون لا يسمعون إلا المدح.","zh":"自负的人只听见赞美之词。","t":[3013,5658]}]},{"id":"ch11p12","audio":"ch11p12.mp3","sents":[{"ar":"هل أنت تعجبني كثيرًا؟ سأل الأمير الصغير: وماذا تعني كلمة (تعجب)؟","zh":"你真的非常崇拜我吗？他向小王子质问道。","t":[103,7184]}]},{"id":"ch11p13","audio":"ch11p13.mp3","sents":[{"ar":"ماذا يعني ذلك - 'يُعجب'؟","zh":"那“崇拜”究竟是什么意思？","t":[103,2432]}]},{"id":"ch11p14","audio":"ch11p14.mp3","sents":[{"ar":"تعجبك تعني أن تروني كأجمل رجل، وأنيق في ملابسي، وأغنى، وأذكى على هذا الكوكب.","zh":"您认为我是这星球上最英俊、最讲究衣着、最富有、最聪明的人。","t":[103,7945]}]},{"id":"ch11p15","audio":"ch11p15.mp3","sents":[{"ar":"لكن أنت الرجل الوحيد في كوكبك!","zh":"但你是你那星球上唯一的人！","t":[103,2787]}]},{"id":"ch11p16","audio":"ch11p16.mp3","sents":[{"ar":"افعلى لي هذا البر","zh":"请行此善举。","t":[103,1339]},{"ar":"استمر في تعجبك بي كما العادة.","zh":"依旧崇拜我吧。","t":[1339,3879]}]},{"id":"ch11p17","audio":"ch11p17.mp3","sents":[{"ar":"أعجبني أنت، قال الأمير الصغير، مرفعاً كتفه قليلاً، ولكن ما الذي في ذلك يجعلك تستمتع به كثيرًا؟","zh":"“我崇拜你，”小王子轻轻耸了耸肩，“但这又有什么能让你如此高兴呢？”","t":[103,9458]}]},{"id":"ch11p18","audio":"ch11p18.mp3","sents":[{"ar":"وغادر الأمير الصغير.","zh":"小王子离去了。","t":[103,1945]}]},{"id":"ch11p19","audio":"ch11p19.mp3","sents":[{"ar":"الكبار حقًا غريبون في طريقة تفكيرهم، قال للأمير الصغير وهو يستمر في رحلته.","zh":"大人们确实古怪得可以，他边走边自言自语。","t":[103,6997]}]}]},{"id":"ch12","title_ar":"الفصل الثاني عشر","title_en":"Chapter XII","title_zh":"第 12 章","paras":[{"id":"ch12p00","audio":"ch12p00.mp3","sents":[{"ar":"الكوكب التالي كان يسكنه سكير","zh":"下一颗星球住着一个酒徒。","t":[103,2774]},{"ar":"كانت الزيارة قصيرة جدًا، لكنها أودعت الأمير الصغير في حزن عميق.","zh":"这次拜访虽短，却让小王子陷入深深的忧郁。","t":[2774,8905]}]},{"id":"ch12p01","audio":"ch12p01.mp3","sents":[{"ar":"ماذا تفعل هنا؟ قال للأمير الصغير الذي وجده جالسًا صامتًا أمام مجموعة من الزجاجات البعض منها فارغ والبعض ملآن.","zh":"“你在此做什么？”他对那个酒徒说，只见他静静地坐在面前的一大堆空瓶子和满瓶之间。","t":[103,10908]}]},{"id":"ch12p02","audio":"ch12p02.mp3","sents":[{"ar":"- أنا... أشرب.","zh":"“我正喝着呢，”酒徒带着哀伤的神情答道。","t":[103,2106]}]},{"id":"ch12p03","audio":"ch12p03.mp3","sents":[{"ar":"لماذا تشرب؟ سأل الأمير الصغير.","zh":"“你为何饮酒？”小王子质问道。","t":[103,3828]}]},{"id":"ch12p04","audio":"ch12p04.mp3","sents":[{"ar":"لأني قد أنسى، قال السكير.","zh":"为了忘记，酒徒答道。","t":[103,2656]}]},{"id":"ch12p05","audio":"ch12p05.mp3","sents":[{"ar":"ماذا أنسى؟ سأل الأُمير الصغير، وقد شعر بالأسف له.","zh":"“为了什么？”小王子问，心中已对他生出了怜悯。","t":[103,5553]}]},{"id":"ch12p06","audio":"ch12p06.mp3","sents":[{"ar":"نسيت أنني آسف، قال السكير، مرفوعا رأسه.","zh":"“忘了我说我羞愧吧，”酒徒低垂着头，老实承认。","t":[103,4445]}]},{"id":"ch12p07","audio":"ch12p07.mp3","sents":[{"ar":"- ماذا تشعر بالخزي؟ أصر الأمير الصغير، الذي أراد مساعدته.","zh":"“羞愧什么？”小王子坚持问道，他想要帮助他。","t":[103,6355]}]},{"id":"ch12p08","audio":"ch12p08.mp3","sents":[{"ar":"أنا آسف على الشرب! السكير أوقف كلامه، وغلق نفسه في صمت لا يمكن اختراقه.","zh":"羞愧于饮酒！酒徒话音戛然而止，将自己封闭在坚不可摧的沉默之中。","t":[103,7842]}]},{"id":"ch12p09","audio":"ch12p09.mp3","sents":[{"ar":"الأمير الصغير غادر، محيرًا.","zh":"小王子困惑地走了。","t":[103,2984]}]},{"id":"ch12p10","audio":"ch12p10.mp3","sents":[{"ar":"البالغون بالتأكيد غريبون جدًا، قال لنفسه وهو يستمر في رحلته.","zh":"大人们确实非常、非常古怪，他边走边自言自语。","t":[103,5892]}]}]},{"id":"ch13","title_ar":"الفصل الثالث عشر","title_en":"Chapter XIII","title_zh":"第 13 章","paras":[{"id":"ch13p00","audio":"ch13p00.mp3","sents":[{"ar":"الكوكب الرابع يخص رجل أعمال","zh":"第四颗星球属于一个商人。","t":[103,2629]},{"ar":"هذا الرجل كان مشغولاً جدًا حتى لم يرفع رأسه عندما وصل الأمير الصغير.","zh":"这位商人如此忙碌，以至于在小王子到来时，连头都没抬一下。","t":[2629,8497]}]},{"id":"ch13p01","audio":"ch13p01.mp3","sents":[{"ar":"صباح الخير، قال الأمير الصغير له.","zh":"早上好，小王子对他说。","t":[103,3947]},{"ar":"لقد انطفأت سيجارتك!","zh":"您的香烟熄灭了。","t":[3947,5974]}]},{"id":"ch13p02","audio":"ch13p02.mp3","sents":[{"ar":"ثلاثة زائد إثنين يساوي خمسة.","zh":"三加二等于五。","t":[103,3474]},{"ar":"خمسة زائد سبعة يساوي اثني عشر","zh":"五加七等于十二。","t":[3474,6079]},{"ar":"اثنا عشر وأربعة عشر يساوي خمسة عشر","zh":"十二加三等于十五。","t":[6079,9237]},{"ar":"صباح الخير","zh":"早上好。","t":[9237,10079]},{"ar":"عشرين عشر زائد سبعة يساوي اثنين وعشرين","zh":"十五加七等于二十二。","t":[10079,13750]},{"ar":"ثمانية وعشرون زائد ستة يساوي ثلاثون.","zh":"二十二加六等于二十八。","t":[13750,17842]},{"ar":"ليس لدي وقت لشعلها ثانية.","zh":"没空再点一根。","t":[17842,21342]},{"ar":"واحد وعشرون زائد خمسة يساوي ثلاثة وثلاثون.","zh":"二十六加五等于三十一。","t":[21342,26197]},{"ar":"يا لها من دهشة!","zh":"哎呀！","t":[26197,28421]},{"ar":"خمسمئة مليون ستة عشر ألفاً وسبعمئة وثلاثون","zh":"五亿零一百六十二万二千七百三十一。","t":[28421,32671]}]},{"id":"ch13p03","audio":"ch13p03.mp3","sents":[{"ar":"خمسمئة مليون ماذا؟ سأل الأمير الصغير.","zh":"五亿零一百……这是什么？小王子问道。","t":[103,4513]}]},{"id":"ch13p04","audio":"ch13p04.mp3","sents":[{"ar":"أه؟","zh":"哎呀？","t":[103,1434]},{"ar":"هل ما زلت هناك؟","zh":"您还在吗？","t":[1434,3776]},{"ar":"خمسة مئة مليون وواحد——لا أستطيع التوقف...","zh":"五亿零一百万——我无法停下...","t":[3776,8618]},{"ar":"لدي الكثير من العمل!","zh":"我事务繁多。","t":[8618,11408]},{"ar":"أنا مهتم بأمور هامة.","zh":"我关注的是重要之事。","t":[11408,14368]},{"ar":"لا أضيع وقتي في أمور لا معنى لها.","zh":"我从不浪费时间在无聊的事情上。","t":[14368,18066]},{"ar":"إثنان زائد خمسة يساوي سبعة...","zh":"二加五等于七……","t":[18066,20684]}]},{"id":"ch13p05","audio":"ch13p05.mp3","sents":[{"ar":"مائة مليون ماذا؟ كرر الأُمير الصغير الذي لم يتخل في حياته عن سؤال طرحه ذات مرة.","zh":"五亿零一百万个什么？小王子反复问道，他一生中一旦提问就绝不会放弃。","t":[103,8000]}]},{"id":"ch13p06","audio":"ch13p06.mp3","sents":[{"ar":"رجل الأعمال رفع رأسه.","zh":"商人抬起了头。","t":[103,2169]}]},{"id":"ch13p07","audio":"ch13p07.mp3","sents":[{"ar":"في الخمسين سنة التي عشتها على هذا الكوكب، تمتدديت ثلاث مرات فقط.","zh":"在这颗星球上居住的五十四年里，我只被打扰过三次。","t":[103,7276]},{"ar":"كانت المرة الأولى قبل عشرين عامًا، عندما سقطت طائرتان من مكان لا أعلمه.","zh":"第一次是二十二年前，不知从何而来的疯子一头栽了下来。","t":[7276,14724]},{"ar":"كان الصوت الذي أطلقته مخيفًا جدًا، وحدثت أربعة أخطاء في حسابي.","zh":"他发出震耳欲聋的巨响，我的加法出了四个错。","t":[14724,21342]},{"ar":"المرّة الثانية، قبل عشر سنوات، أزعجني نوبه من الروماتيزم.","zh":"第二次，十一年前，我被关节炎的发作打扰。","t":[21342,28079]},{"ar":"ليس لدي ما يكفي من التمرين.","zh":"我缺乏锻炼。","t":[28079,31434]},{"ar":"ليس لدي وقت للكسل.","zh":"我无暇闲逛。","t":[31434,34368]},{"ar":"الثالثة - حسنًا، هذه هي المرة الثالثة!","zh":"第三次——嗯，就是这一次！","t":[34368,39118]},{"ar":"أقول، ثم، خمسمئة مليون وواحد——","zh":"那么，我接着说，五亿零一百万——","t":[39118,43092]}]},{"id":"ch13p08","audio":"ch13p08.mp3","sents":[{"ar":"مليون وخمسمئة من ماذا؟","zh":"五亿零一百万个什么？","t":[103,2366]}]},{"id":"ch13p09","audio":"ch13p09.mp3","sents":[{"ar":"الرجل الأعمال أدرك فجأة أنه لا أمل في تركه في سلام حتى يجيب على هذا السؤال.","zh":"商人突然意识到，除非回答这个问题，否则他永远无法安宁。","t":[103,6760]}]},{"id":"ch13p10","audio":"ch13p10.mp3","sents":[{"ar":"ملايين هذه الأشياء الصغيرة، التي يُرى أحياناً في السماء.","zh":"那些小小的东西，有时在天空里可以看到。","t":[103,4773]}]},{"id":"ch13p11","audio":"ch13p11.mp3","sents":[{"ar":"ذباب؟","zh":"苍蝇吗？","t":[103,853]}]},{"id":"ch13p12","audio":"ch13p12.mp3","sents":[{"ar":"أوه، لا.","zh":"哦，不。","t":[103,2263]},{"ar":"أجسام صغيرة مضيئة.","zh":"小小的闪烁之物。","t":[2263,4303]}]},{"id":"ch13p13","audio":"ch13p13.mp3","sents":[{"ar":"نحل؟","zh":"蜜蜂吗？","t":[103,695]}]},{"id":"ch13p14","audio":"ch13p14.mp3","sents":[{"ar":"أوه، لا.","zh":"哦，不。","t":[103,2263]},{"ar":"أجسام صغيرة ذهبية تجعل الرجال الكسالى يحلمون أحلامًا لا جدوى منها.","zh":"那金色的小东西，让闲散的人沉醉于梦幻之中。","t":[2263,9184]},{"ar":"أنا أهتم بأمور هامة فقط.","zh":"至于我，我只关心重要的事。","t":[9184,12697]},{"ar":"لا يوجد وقت للراحة والتخمين في حياتي.","zh":"生活中不容我闲散做梦。","t":[12697,16066]}]},{"id":"ch13p15","audio":"ch13p15.mp3","sents":[{"ar":"آه!","zh":"哎呀！","t":[103,1421]},{"ar":"هل تعني النجوم؟","zh":"您是指星星吗？","t":[1421,2750]}]},{"id":"ch13p16","audio":"ch13p16.mp3","sents":[{"ar":"نعم، هذا هو.","zh":"是的，就是这样。","t":[103,2737]},{"ar":"النجوم.","zh":"星星。","t":[2737,3632]}]},{"id":"ch13p17","audio":"ch13p17.mp3","sents":[{"ar":"وماذا تفعل بسبعمئة مليون نجمة؟","zh":"你用五亿颗星星做什么呢？","t":[103,3182]}]},{"id":"ch13p18","audio":"ch13p18.mp3","sents":[{"ar":"خمسمئة مليون ستة وثلاثين ألف سبعمئة وثلاثة وثلاثون","zh":"五亿零一百六十二万二千七百三十一","t":[103,4866]},{"ar":"أنا مهتم بأمور هامة: أنا دقيق.","zh":"我专注于重要之事：我追求精确。","t":[4866,8169]}]},{"id":"ch13p19","audio":"ch13p19.mp3","sents":[{"ar":"ماذا تفعل بهذه النجوم؟","zh":"您用这些星星做什么呢？","t":[103,2274]}]},{"id":"ch13p20","audio":"ch13p20.mp3","sents":[{"ar":"ماذا أفعل بها؟","zh":"我拿它们怎么办呢？","t":[103,1589]}]},{"id":"ch13p21","audio":"ch13p21.mp3","sents":[{"ar":"نعم.","zh":"是的。","t":[103,774]}]},{"id":"ch13p22","audio":"ch13p22.mp3","sents":[{"ar":"لا شيء.","zh":"没什么。","t":[103,1763]},{"ar":"أمتلكها.","zh":"我拥有它们。","t":[1763,2829]}]},{"id":"ch13p23","audio":"ch13p23.mp3","sents":[{"ar":"هل تملك النجوم؟","zh":"您拥有星星吗？","t":[103,1432]}]},{"id":"ch13p24","audio":"ch13p24.mp3","sents":[{"ar":"نعم.","zh":"是的。","t":[103,774]}]},{"id":"ch13p25","audio":"ch13p25.mp3","sents":[{"ar":"لكني رأيت ملكًا...","zh":"但我已见过一个国王，他——","t":[103,1800]}]},{"id":"ch13p26","audio":"ch13p26.mp3","sents":[{"ar":"الملوك لا يمتلكون، بل يحكمون.","zh":"国王并非“拥有”，而是“统治”。","t":[103,4132]},{"ar":"هذا أمر مختلف تمامًا.","zh":"这大不相同。","t":[4132,6342]}]},{"id":"ch13p27","audio":"ch13p27.mp3","sents":[{"ar":"وماهي الفائدة من امتلاك النجوم؟","zh":"拥有星星对你有何益处？","t":[103,2721]}]},{"id":"ch13p28","audio":"ch13p28.mp3","sents":[{"ar":"يُجعلني ذلك يُغنّي.","zh":"这使我变得富有。","t":[103,1905]}]},{"id":"ch13p29","audio":"ch13p29.mp3","sents":[{"ar":"ما الجيد في أن تكون غنياً لك؟","zh":"这财富对你有何益处？","t":[103,2563]}]},{"id":"ch13p30","audio":"ch13p30.mp3","sents":[{"ar":"إذا اكتشف أحد نجومًا، سأستطيع شراء المزيد.","zh":"若有人发现新的星星，我便可以买下更多。","t":[103,4010]}]},{"id":"ch13p31","audio":"ch13p31.mp3","sents":[{"ar":"هذا الرجل، قال للأمير الصغير لنفسه، يفكر قليلاً مثل سكيري الفقير...","zh":"这位小王子心想：“这个人啊，他的推理方法有点像我那可怜的酒鬼。”","t":[103,6379]}]},{"id":"ch13p32","audio":"ch13p32.mp3","sents":[{"ar":"ومع ذلك، كان لديه بعض الأسئلة الأخرى.","zh":"然而，他仍有许多疑问。","t":[103,3774]}]},{"id":"ch13p33","audio":"ch13p33.mp3","sents":[{"ar":"كيف يمكن للمرء أن يمتلك النجوم؟","zh":"一个人怎能拥有星星呢？","t":[103,2918]}]},{"id":"ch13p34","audio":"ch13p34.mp3","sents":[{"ar":"من يملكها؟ رد رجل الأعمال بغضب.","zh":"商人愤愤地反问：“它们属于谁？”","t":[103,4145]}]},{"id":"ch13p35","audio":"ch13p35.mp3","sents":[{"ar":"لا أعلم.","zh":"我不知道。","t":[103,1921]},{"ar":"لا شيء. لا تخص أحدًا.","zh":"对任何人都不属于。","t":[1921,5000]}]},{"id":"ch13p36","audio":"ch13p36.mp3","sents":[{"ar":"ذلك ينتمي إليّ لأنني كنت أول من فكر في ذلك.","zh":"那它们就属于我了，因为我是第一个想到这个主意的人。","t":[103,4287]}]},{"id":"ch13p37","audio":"ch13p37.mp3","sents":[{"ar":"هذا يكفي؟","zh":"这还不够吗？","t":[103,1050]}]},{"id":"ch13p38","audio":"ch13p38.mp3","sents":[{"ar":"بالطبع.","zh":"当然。","t":[103,1816]},{"ar":"عندما تجد ماسة لا تخص أحدًا، تكون لك.","zh":"当你发现一颗无主之钻，它便属于你了。","t":[1816,6737]},{"ar":"عندما تجد جزيرة لا تخص أحد، تكون لك.","zh":"当你发现一座无人的岛屿，它便属于你。","t":[6737,11632]},{"ar":"عندما تأتي بفكرة قبل أحد آخرين، تأخذ براءة اختراعها: هي لك.","zh":"当你第一个想到一个主意，你就申请专利：那主意就是你的了。","t":[11632,18789]},{"ar":"لذا، بالنسبة لي: أنا أملك النجوم، لأن لا أحد قبلني فكر في امتلاكها.","zh":"如此，于我而言：我拥有星星，因为在我之前，无人曾想过拥有它们。","t":[18789,25658]}]},{"id":"ch13p39","audio":"ch13p39.mp3","sents":[{"ar":"نعم، هذا صحيح، قال الأمير الصغير.","zh":"是的，这倒是真的，小王子说。","t":[103,4645]},{"ar":"ماذا تفعل بها؟","zh":"您拿它们怎么办呢？","t":[4645,6131]}]},{"id":"ch13p40","audio":"ch13p40.mp3","sents":[{"ar":"أنا أديرها","zh":"我管理着它们。","t":[103,1024]},{"ar":"أعددتها وأعددتها.","zh":"我数了又数。","t":[1024,3750]},{"ar":"يصعب.","zh":"这很困难。","t":[3750,5395]},{"ar":"ولكنني رجل يهمه الطباعي أمور الأهمية.","zh":"然而，我天生对重要之事感兴趣。","t":[5395,9040]}]},{"id":"ch13p41","audio":"ch13p41.mp3","sents":[{"ar":"الأمير الصغير لم يكن راضيًا بعد.","zh":"小王子依旧不满足。","t":[103,2787]}]},{"id":"ch13p42","audio":"ch13p42.mp3","sents":[{"ar":"إذا كان لدي شال حريري، أستطيع أن أضعه حول عنقي وأأخذه معي.","zh":"如果我拥有一条丝巾，我就能围在脖子上带走。","t":[103,6921]},{"ar":"إذا كان لدي زهرة، أستطيع أن أقطفها وأأخذها معي.","zh":"若我拥有这朵花，便可摘下它，随身带走。","t":[6921,12697]},{"ar":"لا يمكنك سحب النجوم من السماء...","zh":"你不能从天空中摘下星星...","t":[12697,15303]}]},{"id":"ch13p43","audio":"ch13p43.mp3","sents":[{"ar":"لا","zh":"不。","t":[103,405]},{"ar":"لكني يمكنني وضعهما في المصرف.","zh":"但我可以把它们存进银行。","t":[405,3260]}]},{"id":"ch13p44","audio":"ch13p44.mp3","sents":[{"ar":"ماذا يعني ذلك؟","zh":"这究竟是什么意思呢？","t":[103,1524]}]},{"id":"ch13p45","audio":"ch13p45.mp3","sents":[{"ar":"يعني ذلك أنني أكتب عدد نجومي على ورقة صغيرة.","zh":"这意味着我在一张小纸条上写下我的星星数目。","t":[103,5368]},{"ar":"ثم أضع هذا الورق في الدرج وأقفله بمفتاح.","zh":"然后我把这张纸条放进抽屉，并用钥匙锁上。","t":[5368,9066]}]},{"id":"ch13p46","audio":"ch13p46.mp3","sents":[{"ar":"هل هذا كل شيء؟","zh":"这便是全部了吗？","t":[103,1590]}]},{"id":"ch13p47","audio":"ch13p47.mp3","sents":[{"ar":"هذا يكفي، قال رجل الأعمال.","zh":"那便足够了，商人说。","t":[103,2826]}]},{"id":"ch13p48","audio":"ch13p48.mp3","sents":[{"ar":"هذا ممتع، الأمل الصغير فكر.","zh":"这倒有趣，小王子心想。","t":[103,3934]},{"ar":"هذا يبدو شاعريًا نوعًا ما.","zh":"这倒颇有诗意。","t":[3934,7158]},{"ar":"لكن ذلك ليس له أهمية كبيرة.","zh":"但这并无大碍。","t":[7158,10119]}]},{"id":"ch13p49","audio":"ch13p49.mp3","sents":[{"ar":"الأمير الصغير كان لديه أفكار في أمور هامة مختلفة عن أفكار البالغين.","zh":"小王子在事关重大之事上，所持见解与成人迥异。","t":[103,6076]}]},{"id":"ch13p50","audio":"ch13p50.mp3","sents":[{"ar":"أنا أمتلك وردة أسقيها كل يوم، كما أمتلك ثلاثة براكين أزيلها كل أسبوع، وأُشمل البركان الخامد بعنايتي دائمًا، ما من أحد يعلم ذلك.","zh":"“我自己养着一朵花，”他继续与商人交谈，“每天都要给它浇水。”","t":[103,13237]},{"ar":"أملك ثلاثة براكين، وأزيل عنها الأتربة كل أسبوع (لأنني أزيل أيضًا عن البركان الخامل؛ لا أحد يعلم).","zh":"我拥有三座火山，每周都要清理一番（包括那座死火山；毕竟，世事难料）。","t":[13237,23500]},{"ar":"إنها تجعل براكاني لها معنى، وتجعل وردتي لها قيمة.","zh":"它使我的火山有了意义，也使我的玫瑰有了价值。","t":[23500,29276]},{"ar":"لكنك لا فائدة لك النجوم...","zh":"但对星星来说，你毫无用处……","t":[29276,31671]}]},{"id":"ch13p51","audio":"ch13p51.mp3","sents":[{"ar":"رجل الأعمال فتح فمه، لكن لم يجد شيئًا يقوله، فتابع الأمير الصغير طريقه.","zh":"商人张口结舌，无言以对。","t":[103,7684]},{"ar":"الأمير الصغير غادر.","zh":"小王子离去了。","t":[7684,9355]}]},{"id":"ch13p52","audio":"ch13p52.mp3","sents":[{"ar":"الكبار حقًا غريبون للغاية، قال ببساطة، يتحدث إلى نفسه وهو يستمر في رحلته.","zh":"大人们真是奇怪得不可思议，他边走边自言自语。","t":[103,7432]}]}]},{"id":"ch14","title_ar":"الفصل الرابع عشر","title_en":"Chapter XIV","title_zh":"第 14 章","paras":[{"id":"ch14p00","audio":"ch14p00.mp3","sents":[{"ar":"الكوكب الخامس كان غريبًا جدًا.","zh":"第五颗星球颇为奇异。","t":[103,3737]},{"ar":"كان هذا الكوكب الأصغر من بين الكواكب جميعها.","zh":"那是所有星球中最小的一颗。","t":[3737,8355]},{"ar":"كان الكوكب يكفيه مكان لعمود الإنارة وعامل الإنارة فقط.","zh":"这颗星球仅能容纳一盏路灯和一个点灯人。","t":[8355,14053]},{"ar":"لم يتمكن الأمير الصغير من تفسير سبب وجود مصابيح الشارع ومشعل المصابيح في مكان ما في السماء، على كوكب لا يوجد به سكان ولا منازل.","zh":"小王子无法解释清楚，在某个星球上，天空中，为何会有路灯和点灯人的存在，而这个星球既无人居住，也无房屋。","t":[14053,26132]},{"ar":"لكن قال لنفسه، ومع ذلك:","zh":"然而，他自言自语道：","t":[26132,28842]}]},{"id":"ch14p01","audio":"ch14p01.mp3","sents":[{"ar":"ربما يكون هذا الرجل سخيفًا.","zh":"这盏灯的人或许有些荒唐。","t":[103,3553]},{"ar":"لكن هو ليس سخيفًا كالملك أو المرائي أو رجل الأعمال أو السكير","zh":"但他并不像国王、自负的人、商人、酒鬼那样荒谬。","t":[3553,8539]},{"ar":"على الأقل لعملي معنى","zh":"至少他的工作尚有意义。","t":[8539,10368]},{"ar":"عندما يضيء مصباح الشارع، فكأنه أتى بنجم إضافي إلى الحياة، وعندما يطفئ مصباحه، فإنه يدفع الزهرة أو النجمة إلى النوم.","zh":"他点亮街灯，仿佛又唤醒了一颗星星，或一朵花儿。","t":[10368,22289]},{"ar":"عندما يطفئ مصباحه، يرسل الزهرة أو النجمة إلى النوم.","zh":"他熄灭灯火，便让花儿或星星进入梦乡。","t":[22289,27987]},{"ar":"هذا مهنة جميلة","zh":"这是一份美好的职业。","t":[27987,29645]},{"ar":"ولأنه جميل، فهو حقًا مفيد.","zh":"既然美好，便真正有益。","t":[29645,32644]}]},{"id":"ch14p02","audio":"ch14p02.mp3","sents":[{"ar":"عندما وصل إلى الكوكب ألقى التحية على عامل الإنارة باحترام.","zh":"他抵达星球时，向点灯人毕恭毕敬地行礼。","t":[103,4839]}]},{"id":"ch14p03","audio":"ch14p03.mp3","sents":[{"ar":"صباح الخير يا سيدي","zh":"早上好。","t":[103,1721]},{"ar":"لماذا قمت بإطفاء مصابيحك الآن؟","zh":"你为何刚刚熄了灯？","t":[1721,4484]}]},{"id":"ch14p04","audio":"ch14p04.mp3","sents":[{"ar":"هذه الأوامر، أجاب عامل الإنارة. صباح الخير.","zh":"这是规定。","t":[103,6079]},{"ar":"صباح الخير يا سيدي","zh":"早上好。","t":[6079,7921]}]},{"id":"ch14p05","audio":"ch14p05.mp3","sents":[{"ar":"ما هي الأوامر؟","zh":"这是命令。","t":[103,1353]}]},{"id":"ch14p06","audio":"ch14p06.mp3","sents":[{"ar":"هذه الأوامر هي أن أطفئ مصابيحي.","zh":"这是熄灯的命令。","t":[103,3934]},{"ar":"مساء الخير.","zh":"晚安。","t":[3934,5119]}]},{"id":"ch14p07","audio":"ch14p07.mp3","sents":[{"ar":"وأشعل مصباحه ثانية.","zh":"他又点亮了灯火。","t":[103,2222]}]},{"id":"ch14p08","audio":"ch14p08.mp3","sents":[{"ar":"لكن لماذا أعدت إشعال النور مرة أخرى؟","zh":"你为何又把灯点亮了？","t":[103,3445]}]},{"id":"ch14p09","audio":"ch14p09.mp3","sents":[{"ar":"هذه الأوامر، أجاب عامل الإنارة. صباح الخير.","zh":"这是命令。","t":[103,5158]}]},{"id":"ch14p10","audio":"ch14p10.mp3","sents":[{"ar":"أنا لا أفهم، قال الأمير الصغير.","zh":"我不明白，小王子说。","t":[103,2892]}]},{"id":"ch14p11","audio":"ch14p11.mp3","sents":[{"ar":"ليس هناك ما يُفهم، قال عامل الإنارة.","zh":"“这没什么好理解的，”点灯人说。","t":[103,4355]},{"ar":"الأوامر هي الأوامر.","zh":"命令就是命令。","t":[4355,7039]},{"ar":"صباح الخير يا سيدي","zh":"早上好。","t":[7039,8881]}]},{"id":"ch14p12","audio":"ch14p12.mp3","sents":[{"ar":"وضع مصباحه خارجًا","zh":"他熄灭了灯火。","t":[103,2076]}]},{"id":"ch14p13","audio":"ch14p13.mp3","sents":[{"ar":"ثم نظف جبينه بمنديل مزخرف بمربعات حمراء","zh":"他用手帕上的红格子方巾擦拭额头。","t":[103,4405]}]},{"id":"ch14p14","audio":"ch14p14.mp3","sents":[{"ar":"أتبع مهنة سيئة.","zh":"我从事着一份糟糕的职业。","t":[103,2829]},{"ar":"في الأيام القديمة كان ذلك معقولاً.","zh":"往昔的规定尚合情理。","t":[2829,6724]},{"ar":"أطفأت المصباح في الصباح وأضيئته ثانية في المساء.","zh":"晨曦中熄灭灯火，暮色中复燃光亮。","t":[6724,11711]},{"ar":"لديّ باقي اليوم للراحة وباقي الليل للنوم.","zh":"我拥有了整个白天的闲暇与夜晚的安眠。","t":[11711,15276]}]},{"id":"ch14p15","audio":"ch14p15.mp3","sents":[{"ar":"هل تغيرت الأوامر منذ ذلك الوقت؟","zh":"自那以后，规定已经改了？","t":[103,2852]}]},{"id":"ch14p16","audio":"ch14p16.mp3","sents":[{"ar":"لم تتغير الأوامر، وتلك هي المأساة!","zh":"规定并未更改，点灯人说道。","t":[103,4474]},{"ar":"هذه هي المأساة!","zh":"这是悲剧！","t":[4474,6908]},{"ar":"من سنة إلى سنة ازدادت سرعة دوران الكوكب إلى حد بعيد ولم تتغير الأوامر.","zh":"年复一年，星球转得越来越快，而命令却未曾更改。","t":[6908,13474]}]},{"id":"ch14p17","audio":"ch14p17.mp3","sents":[{"ar":"ثم ماذا؟ سأل الأمير الصغير.","zh":"小王子问道：“那么呢？”","t":[103,3631]}]},{"id":"ch14p18","audio":"ch14p18.mp3","sents":[{"ar":"ثم – أصبح الكوكب الآن يدور حول نفسه كل دقيقة، وأنا لم أعد أملك ثانية واحدة للراحة.","zh":"这颗星球现在每分钟转一圈，我连一秒钟的休息时间都没有。","t":[103,9066]},{"ar":"كل دقيقة يجب أن أضيء مصباحي وأطفئه!","zh":"每分钟我都要点亮又熄灭我的灯。","t":[9066,12448]}]},{"id":"ch14p19","audio":"ch14p19.mp3","sents":[{"ar":"هذا مضحك جدًا!","zh":"这真有趣！","t":[103,2671]},{"ar":"هناك يُصبح اليوم دقيقة واحدة فقط حيث تعيش!","zh":"在这里，一天仅有一分钟。","t":[2671,6842]}]},{"id":"ch14p20","audio":"ch14p20.mp3","sents":[{"ar":"ليس مضحكًا على الإطلاق، قال عامل الإنارة.","zh":"这根本不有趣！点灯人说道。","t":[103,4750]},{"ar":"بينما كنا نتحدث، مر شهر بالكامل.","zh":"我们交谈之际，一个月已悄然流逝。","t":[4750,8356]}]},{"id":"ch14p21","audio":"ch14p21.mp3","sents":[{"ar":"شهر؟!","zh":"一个月？","t":[103,787]}]},{"id":"ch14p22","audio":"ch14p22.mp3","sents":[{"ar":"نعم، شهر.","zh":"是的，一个月。","t":[103,2434]},{"ar":"ثلاثون دقيقة","zh":"三十分钟。","t":[2434,3789]},{"ar":"ثلاثون يومًا","zh":"三十天。","t":[3789,4855]},{"ar":"مساء الخير.","zh":"晚安。","t":[4855,5895]}]},{"id":"ch14p23","audio":"ch14p23.mp3","sents":[{"ar":"وأشعل مصباحه ثانية.","zh":"他又点亮了灯火。","t":[103,2222]}]},{"id":"ch14p24","audio":"ch14p24.mp3","sents":[{"ar":"الأمير الصغير شاهد عامل الإنارة، شعر بأنه أحب هذا العامل الذي كان مخلصًا لأوامره.","zh":"他看着点灯人，心中涌起对这位忠于职责的灯夫的喜爱。","t":[103,8158]},{"ar":"تذكر غروب الشمس الذي اعتاد هو نفسه البحث عنه بمجرد تحريك كرسيه، فأراد أن يساعد صديقه.","zh":"他记得，往昔自己只是搬动椅子，就能观赏到日落；他想要帮助他的朋友。","t":[8158,16158]}]},{"id":"ch14p25","audio":"ch14p25.mp3","sents":[{"ar":"تعلم... أعتقد أن هنالك طريقة تسمح لك بالراحة حينما تشاء","zh":"“你知道，”他道，“我可以告诉你一个方法，你想要休息的时候就能休息……”","t":[103,6487]}]},{"id":"ch14p26","audio":"ch14p26.mp3","sents":[{"ar":"أريد دوماً أن أستريح، قال عامل الإنارة.","zh":"“我总是想休息，”点灯人说道。","t":[103,3563]}]},{"id":"ch14p27","audio":"ch14p27.mp3","sents":[{"ar":"يمكن للرجل أن يكون مخلصًا وأبله في نفس الوقت.","zh":"人可以同时忠诚又懒惰。","t":[103,5039]},{"ar":"الأمير الصغير استمر في شرحه:","zh":"小王子继续解释道：","t":[5039,7368]}]},{"id":"ch14p28","audio":"ch14p28.mp3","sents":[{"ar":"الكوكب الذي تعيش عليه صغير جدًا، بحيث يمكنك أن تدور حوله بثلاث خطوات فقط، ولكن يجب عليك المشي ببطء لتبقى دائمًا في ضوء الشمس.","zh":"你的星球如此之小，只需迈三步就能绕它一周。","t":[103,13158]},{"ar":"فقط إذا سارتم ببطء، ستكونون دائمًا في ضوء الشمس.","zh":"只需缓缓前行，便能始终沐浴在阳光下。","t":[13158,18618]},{"ar":"عندما تريد الراحة، تتجول... ويبقى اليوم طويلاً كما تريد.","zh":"当你想休息时，就前行——日子便会如你所愿地延长。","t":[18618,24723]}]},{"id":"ch14p29","audio":"ch14p29.mp3","sents":[{"ar":"ليس ذلك يخدمني كثيرًا، قال عامل الإنارة.","zh":"这对我帮助不大，点灯人说道。","t":[103,4829]},{"ar":"ما أحبه في الحياة هو النوم.","zh":"生命中所爱唯有沉睡。","t":[4829,7132]}]},{"id":"ch14p30","audio":"ch14p30.mp3","sents":[{"ar":"بالتأكيد، إليك الرد باللغة العربية:\n\"ثم أنت محظوظ، قال الأمير الصغير.","zh":"那你真是不幸啊。","t":[103,7250]}]},{"id":"ch14p31","audio":"ch14p31.mp3","sents":[{"ar":"أنا محظوظ، قال عامل الإنارة.","zh":"我真是倒霉。","t":[103,3645]},{"ar":"صباح الخير. أطفأ مصباحه.","zh":"早上好。他熄灭了灯火。","t":[3645,7092]}]},{"id":"ch14p32","audio":"ch14p32.mp3","sents":[{"ar":"هذا الرجل سيستخف به الآخرون: الملك والرجل المغرور والسكير ورجل الأعمال.","zh":"那个人，”小王子在继续前行时自言自语，“那个人会被所有人嘲笑：国王、自负的人、酒鬼、商人。","t":[103,7895]},{"ar":"مع ذلك، هو الوحيد منهم جميعًا الذي لا يبدو لي سخيفًا.","zh":"然而，他是他们所有人中唯一一个在我看来并不荒谬的人。","t":[7895,13645]},{"ar":"ربما لأنه يفكر في شيء آخر غير نفسه.","zh":"或许是因为他在想别的事情，而非只顾自己。","t":[13645,17197]}]},{"id":"ch14p33","audio":"ch14p33.mp3","sents":[{"ar":"أنفث نفسًا حزينًا، وقال لنفسه، مرة أخرى:","zh":"他叹了口气，又自言自语道：","t":[103,4458]}]},{"id":"ch14p34","audio":"ch14p34.mp3","sents":[{"ar":"هذا الرجل هو الوحيد الذي كان بوسعي اتخاذه صديقًا لي، لكن كوكبه صغير جدًا حقًا، فما من مكان كاف لشخصين.","zh":"那他是他们所有人中唯一一个我可以成为朋友的人。","t":[103,10961]},{"ar":"لكوكبُهُ صغير جدًا.","zh":"然而，他的星球实在太小了。","t":[10961,13947]},{"ar":"لا يوجد مكان فيه لشخصين...","zh":"这颗星球容不下两个人...","t":[13947,16408]}]},{"id":"ch14p35","audio":"ch14p35.mp3","sents":[{"ar":"ما لم يجرؤ الأمير الصغير على الإقرار بأنه يأسف أكثر لرحيله عن هذا الكوكب، لأنه يتمتع بآلاف وأربعمئة وأربعين غروباً كل يوم!","zh":"他不敢承认的是，他最遗憾的是即将离开这个星球，因为它每天都能目睹1440次日落。","t":[103,11379]}]}]},{"id":"ch15","title_ar":"الفصل الخامس عشر","title_en":"Chapter XV","title_zh":"第 15 章","paras":[{"id":"ch15p00","audio":"ch15p00.mp3","sents":[{"ar":"الكوكب السادس كان أكبر حجمًا بعشرة أضعاف من الذي قبله.","zh":"第六颗行星比上一颗大十倍。","t":[103,5855]},{"ar":"كان يسكنه سيد عجوز يكتب كتبًا ضخمة.","zh":"这位老先生撰写着厚重的书籍。","t":[5855,9697]}]},{"id":"ch15p01","audio":"ch15p01.mp3","sents":[{"ar":"أوه، انظر!","zh":"哦，看哪！","t":[103,2395]},{"ar":"ها هو مستكشف!","zh":"哦，看哪！来了一位探险家！","t":[2395,3618]}]},{"id":"ch15p02","audio":"ch15p02.mp3","sents":[{"ar":"الأمير الصغير جلس على الطاولة ولهب أنفاسه قليلاً.","zh":"小王子坐在桌子上，喘着气。","t":[103,5408]},{"ar":"لقد سافر كثيرًا وأمكنته واسعة جدًا!","zh":"他已跋涉千里，路途遥远！","t":[5408,9013]}]},{"id":"ch15p03","audio":"ch15p03.mp3","sents":[{"ar":"من أين تأتي؟ قال الرجل العجوز له.","zh":"您从何方来？","t":[103,3948]}]},{"id":"ch15p04","audio":"ch15p04.mp3","sents":[{"ar":"ما هذا الكتاب الكبير؟ قال الأمير الصغير.","zh":"那本厚重的书是何物？小王子问道。","t":[103,5184]},{"ar":"ماذا تفعل هنا؟","zh":"您在做什么？","t":[5184,6658]}]},{"id":"ch15p05","audio":"ch15p05.mp3","sents":[{"ar":"أنا جغرافي، قال الرجل العجوز له.","zh":"“我是地理学家，”老先生对他说。","t":[103,3090]}]},{"id":"ch15p06","audio":"ch15p06.mp3","sents":[{"ar":"ما هو الجغرافي؟ سأل الأمير الصغير.","zh":"小王子问：“地理学家是做什么的？”","t":[103,4052]}]},{"id":"ch15p07","audio":"ch15p07.mp3","sents":[{"ar":"المجريف هو عالم يعرف مواقع البحار والأنهار والمدن والجبال والصحارى.","zh":"地理学家是知晓大海、江河、城镇、山脉和沙漠位置的学者。","t":[103,6235]}]},{"id":"ch15p08","audio":"ch15p08.mp3","sents":[{"ar":"هذا مثير جدًا، قال الأمير الصغير.","zh":"这倒很有趣，小王子说。","t":[103,4250]},{"ar":"هنا في النهاية رجل لديه مهنة حقيقية! ثم نظر حوله إلى كوكب الجغرافي.","zh":"终于，他遇见了一位真正有职业的人！他环顾四周，打量着地理学家的星球。","t":[4250,12421]},{"ar":"كان هذا الكوكب الأكثر روعة ورومانسية الذي رآه من قبل.","zh":"这颗星球是他所见过的最为雄伟庄严的星球。","t":[12421,17408]}]},{"id":"ch15p09","audio":"ch15p09.mp3","sents":[{"ar":"إن كوكبك جميل جدًا.","zh":"您的星球真美。","t":[103,3105]},{"ar":"هل يوجد فيه محيطات؟","zh":"这颗星球有海洋吗？","t":[3105,4987]}]},{"id":"ch15p10","audio":"ch15p10.mp3","sents":[{"ar":"لا أستطيع إخبارك بذلك، قال العالم الجغرافي.","zh":"“这我无法告知，”地理学家说。","t":[103,4129]}]},{"id":"ch15p11","audio":"ch15p11.mp3","sents":[{"ar":"أوه! كان الأمير الصغير محبطًا.","zh":"啊！小王子有些失望。","t":[103,4526]},{"ar":"هل يوجد جبال على هذا الكوكب؟","zh":"这颗星球有山脉吗？","t":[4526,6948]}]},{"id":"ch15p12","audio":"ch15p12.mp3","sents":[{"ar":"لا أستطيع إخبارك بذلك، قال العالم الجغرافي.","zh":"“这我无法告知，”地理学家说。","t":[103,4129]}]},{"id":"ch15p13","audio":"ch15p13.mp3","sents":[{"ar":"ومدنًا وأنهارًا وصحاري؟","zh":"城镇、河流、沙漠？","t":[103,2379]}]},{"id":"ch15p14","audio":"ch15p14.mp3","sents":[{"ar":"لا أستطيع إخبارك بذلك أيضًا.","zh":"这我也无法回答。","t":[103,2669]}]},{"id":"ch15p15","audio":"ch15p15.mp3","sents":[{"ar":"لكن أنت جغرافي!","zh":"但您是地理学家！","t":[103,1707]}]},{"id":"ch15p16","audio":"ch15p16.mp3","sents":[{"ar":"بالضبط، قال العالم الجغرافيا.","zh":"“正是如此，”地理学家答道。","t":[103,3618]},{"ar":"ليس أنا مستكشف.","zh":"但我不是探险家。","t":[3618,6053]},{"ar":"ليس لدي مستكشفون على كوكبي.","zh":"我的星球上没有一位探险家。","t":[6053,9671]},{"ar":"ليس الجغرافي من يخرج ليحصي المدن والأنهار والجبال والبحار والoceans والصحارى.","zh":"地理学家并非外出计数城镇、河流、山脉、海洋、大洋和沙漠。","t":[9671,16724]},{"ar":"المجريف لا يمكنه أن يهدر وقته بالتسول، فهو أكثر أهمية بكثير.","zh":"地理学家太过重要，不容闲逛。","t":[16724,23974]},{"ar":"لم يغادر مكتبه.","zh":"他从未离开过他的办公桌。","t":[23974,26303]},{"ar":"لكن يلتقي بالمستكشفين في مكتبه.","zh":"他在书房接待探险家。","t":[26303,30092]},{"ar":"يطرح الأسئلة عليهم ويسجل ما يتذكرونه عن أسفارهم","zh":"他询问他们，记录下他们旅途中的回忆。","t":[30092,34803]},{"ar":"إذا كانت ذكريات أحد منهم قد أسرته، يأمر الجغرافي بتحري شخصية المستكشف الأخلاقية.","zh":"若其中某位探险家的回忆引起了他的兴趣，地理学家便会下令调查那位探险者的道德品质。","t":[34803,42381]}]},{"id":"ch15p17","audio":"ch15p17.mp3","sents":[{"ar":"لماذا ذلك؟","zh":"那是什么原因呢？","t":[103,1300]}]},{"id":"ch15p18","audio":"ch15p18.mp3","sents":[{"ar":"لأن المستكشف الذي ينطق بالكذب يلحق بكتب الجغرافي ضررًا كبيرًا.","zh":"因为一个说谎的探险家会给地理学家的书籍带来灾难。","t":[103,6553]},{"ar":"المستكشف الذي شرب كثيرًا لا ينفع.","zh":"一个酗酒的探险家也不行。","t":[6553,9487]}]},{"id":"ch15p19","audio":"ch15p19.mp3","sents":[{"ar":"لماذا هذا؟ سأل الأمير الصغير.","zh":"“这又是为什么？”小王子问道。","t":[103,3842]}]},{"id":"ch15p20","audio":"ch15p20.mp3","sents":[{"ar":"لأن السكارى يرون الأشياء مضاعفة، وبالنتيجة يسجل الجغرافي وجود جبلين، بينما في الواقع يوجد جبل واحد.","zh":"酗酒者所见皆为双重。","t":[103,10421]},{"ar":"ثم سيتعرف الجغرافي على وجود جبلين في مكان يحتوي على جبل واحد فقط.","zh":"于是地理学家会在只有一座山的地方记下两座山。","t":[10421,16671]}]},{"id":"ch15p21","audio":"ch15p21.mp3","sents":[{"ar":"أنا أعرف شخصًا، سيكون سيئًا كمستكشف، قال الأمير الصغير.","zh":"我认识一个人，他会成为糟糕的探险家。","t":[103,5708]}]},{"id":"ch15p22","audio":"ch15p22.mp3","sents":[{"ar":"هذا ممكن.","zh":"这是可能的。","t":[103,2224]},{"ar":"ثم، عندما يُظهر أن شخصية المستكشف صالحة، يُطلب إجراء تحقيق في اكتشافه.","zh":"于是，当探险者的道德品质得到证实，便下令调查他的发现。","t":[2224,9210]}]},{"id":"ch15p23","audio":"ch15p23.mp3","sents":[{"ar":"هل ذهب أحد ليراه؟","zh":"您去看过它吗？","t":[103,1748]}]},{"id":"ch15p24","audio":"ch15p24.mp3","sents":[{"ar":"لا.","zh":"不。","t":[103,1421]},{"ar":"سيكون هذا معقدًا جدًا.","zh":"这太过复杂了。","t":[1421,4632]},{"ar":"لكن يتطلب من المكتشف تقديم أدلة.","zh":"但需探险家提供证据。","t":[4632,8842]},{"ar":"مثلاً، إذا كان الاكتشاف المطلوب هو جبل كبير، يجب أن يتم إحضار أحجار كبيرة منه.","zh":"例如，如果探险的成果是发现了一座大山，便需从那里带回大石头。","t":[8842,16461]}]},{"id":"ch15p25","audio":"ch15p25.mp3","sents":[{"ar":"العالم الجغرافيا فجأة تحركت له عاطفته.","zh":"地理学家突然激动起来。","t":[103,3774]}]},{"id":"ch15p26","audio":"ch15p26.mp3","sents":[{"ar":"لكنكـ - أنتـ تأتـي من بعيد!","zh":"但你——你从远方来！","t":[103,3697]},{"ar":"أنت مستكشف!","zh":"你是一位探险家！","t":[3697,5803]},{"ar":"ينبغي أن تصف كوكبك لي!","zh":"请向我描述你的星球。","t":[5803,8052]}]},{"id":"ch15p27","audio":"ch15p27.mp3","sents":[{"ar":"فتح الجغرافي كتابه الكبير ورفع قلمه.","zh":"地理学家翻开他那厚重的登记册，削尖了他的铅笔。","t":[103,4408]},{"ar":"يُسجل أولاً كتب روايات المستكشفين بالقلم الرصاص.","zh":"探险家的口述先以铅笔记录。","t":[4408,9671]},{"ar":"ينتظر الإنسان حتى يقدم المستكشف الدليل، قبل أن يكتبه بالحبر.","zh":"待探险家提供证据后，方以墨水记录之。","t":[9671,15092]}]},{"id":"ch15p28","audio":"ch15p28.mp3","sents":[{"ar":"- حسنًا؟ قال الأمير الصغير: - أوه، إن موطني ليس مثيرًا لأنه صغير جدًا. لدي ثلاثة براكين، اثنان ناشطان والثالث خامد. لكن ما من أحد يعلم. قال الجغرافي: - ما من أحد يعلم. - لدي زهرة أيضًا. قال الجغرافي: - لا نسجل الأزهار. - ولم لا؟! إنها أجمل شيء على كوكبي! - لأن الأزهار سريعة الزوال. - وماذا تعني كلمة سريعة الزوال؟ قال الجغرافي: - إن الأبحاث الجغرافية هي أثمن الكتب على الإطلاق، فهي لا تصبح قديمة الطراز. من النادر أن يغيِّر جبل مكانه، ومن النادر جدًا أن يفرغ المحيط نفسه من المياه. إننا نكتب أشياء أبدية. قاطع الأمير الصغير قائلًا: - لكن البراكين الخامدة يمكن أن تثور، فما الذي تعنيه كلمة سريعة الزوال؟ قال الجغرافي: - إذا كانت البراكين خامدة أو نشطة، فالأمر سيان بالنسبة لنا. إن ما يهمنا هو الجبل؛ إنه لا يتغير. قال الأمير الصغير مرة أخرى: - لكن ماذا تعني كلمة سريع الزوال؟ (فهو لم يتخل في حياته عن سؤال طرحه ذات مرة). - إنها تعني عرضة لخطر الزوال المبكر. - هل زهرتي عرضة لخطر الزوال المبكر؟ - إنها كذلك، طبعًا. قال الأمير الصغير في نفسه: - إن زهرتي هي سريعة الزوال، ولديها أربع أشواك فقط لتحمي نفسها من العالم! وقد تركتها وحيدة على كوكبي! كانت تلك اللحظة الأولى التي شعر فيها بالندم، لكنه تشجع ثانية. سأل: - أي مكان تنصحني بزيارته الآن؟ أجاب الجغرافي: - كوكب الأرض، إنه ذو سمعة حسنة. ورحل الأمير الصغير وهو يفكر في زهرته.","zh":"“嗯？”地理学家期待地问道。","t":[103,136526]}]},{"id":"ch15p29","audio":"ch15p29.mp3","sents":[{"ar":"أوه، حيث أعيش، ليس مثيرًا جدًا، قال الأمير الصغير.","zh":"哦，我那地方可没意思了，小王子说。","t":[103,6276]},{"ar":"كل شيء صغير جدًا.","zh":"这一切都如此渺小。","t":[6276,9079]},{"ar":"لدي ثلاثة براكين","zh":"我有三座火山。","t":[9079,10737]},{"ar":"ثلاثة براكين، اثنان نشطان والثالث خامد.","zh":"两座火山活跃，另一座已熄灭。","t":[10737,15724]},{"ar":"لكن لا أحد يعرف.","zh":"然而，无人能预知。","t":[15724,17290]}]},{"id":"ch15p30","audio":"ch15p30.mp3","sents":[{"ar":"لا يمكن معرفة ذلك، قال العالم الجغرافي.","zh":"无人能预知，地理学家说。","t":[103,3971]}]},{"id":"ch15p31","audio":"ch15p31.mp3","sents":[{"ar":"لدي زهرة أيضًا","zh":"我还有一朵花。","t":[103,1786]}]},{"id":"ch15p32","audio":"ch15p32.mp3","sents":[{"ar":"لا نسجل الأزهار.","zh":"我们不记录花朵，地理学家说。","t":[103,1694]}]},{"id":"ch15p33","audio":"ch15p33.mp3","sents":[{"ar":"لماذا ذلك؟","zh":"那又是为何呢？","t":[103,2211]},{"ar":"الوردة هي الأجمل شيء على كوكبي!","zh":"这朵花是我星球上最美的东西。","t":[2211,5118]}]},{"id":"ch15p34","audio":"ch15p34.mp3","sents":[{"ar":"نحن لا نكتبها، قال عالم الجغرافيا، لأنها زائلة.","zh":"“我们不记录它们，”地理学家说，“因为它们是转瞬即逝的。”","t":[103,4971]}]},{"id":"ch15p35","audio":"ch15p35.mp3","sents":[{"ar":"ماذا تعني كلمة سريعة الزوال؟","zh":"那“转瞬即逝”又是什么意思？","t":[103,2840]}]},{"id":"ch15p36","audio":"ch15p36.mp3","sents":[{"ar":"الجغرافيا، قال العالم الجغرافي، \"هي الكتب التي، من بين جميع الكتب، تهتم بأمور هامة.","zh":"地理学，地理学家说，“是所有书籍中最关注重大事务的书籍。","t":[103,9382]},{"ar":"لا يصبحون قديمي الطراز.","zh":"它们永远不会过时。","t":[9382,12368]},{"ar":"من النادر أن يتغير موقف الجبل.","zh":"山移位，极为罕见。","t":[12368,16039]},{"ar":"من النادر جدًا أن يفرغ المحيط نفسه من المياه.","zh":"海洋干涸之事，极为罕见。","t":[16039,20671]},{"ar":"نكتب عن أشياء أبدية.","zh":"我们记载永恒之物。","t":[20671,22631]}]},{"id":"ch15p37","audio":"ch15p37.mp3","sents":[{"ar":"لكن البراكين المنطفئة قد تعود للحياة، قال الأمير الصغير، يقطع كلامه.","zh":"但死火山也可能复苏，小王子打断了他的话。","t":[103,7461]},{"ar":"ماذا يعني ذلك– 'مؤقت'؟","zh":"那“转瞬即逝”又是什么意思？","t":[7461,9474]}]},{"id":"ch15p38","audio":"ch15p38.mp3","sents":[{"ar":"إذا كانت البراكين خامدة أو نشطة، الأمر سيان بالنسبة لنا.","zh":"火山是否熄灭或活跃，对我们来说并无区别。","t":[103,6355]},{"ar":"ما يهمنا هو الجبل.","zh":"山，对我们来说，才是重要的。","t":[6355,9013]},{"ar":"لم يتغير.","zh":"它不会改变。","t":[9013,10118]}]},{"id":"ch15p39","audio":"ch15p39.mp3","sents":[{"ar":"لكن ماذا يعني ذلك - 'مؤقت'؟ تكرر الأمير الصغير، الذي لم يترك قط سؤالاً بعد أن طرحه، وهو لم يكن يسمح لنفسه بالتخلي عنه.","zh":"“‘转瞬即逝’是什么意思？”小王子继续追问，他一生中一旦提问，就绝不会轻易放手。","t":[103,12408]}]},{"id":"ch15p40","audio":"ch15p40.mp3","sents":[{"ar":"يعني ذلك، 'يهدد به الفناء السريع.'","zh":"意味着“面临迅速消失的危险”。","t":[103,3366]}]},{"id":"ch15p41","audio":"ch15p41.mp3","sents":[{"ar":"هل زهرة بلدي مهددة بالانقراض السريع؟","zh":"我的花儿面临迅速消失的危险吗？","t":[103,3590]}]},{"id":"ch15p42","audio":"ch15p42.mp3","sents":[{"ar":"بالطبع، هو كذلك.","zh":"当然如此。","t":[103,2089]}]},{"id":"ch15p43","audio":"ch15p43.mp3","sents":[{"ar":"زهرتي هي سريعة الزوال ولديها أربع أشواك فقط لحماية نفسها من العالم!","zh":"我的花儿是转瞬即逝的，小王子自言自语道，而她只有四根刺来保护自己抵御这个世界。","t":[103,7211]},{"ar":"لقد تركتها وحيدة على كوكبي!","zh":"我让她孤零零地留在了我的星球上。","t":[7211,9790]}]},{"id":"ch15p44","audio":"ch15p44.mp3","sents":[{"ar":"كان تلك اللحظة الأولى التي شعر فيها بالندم.","zh":"那是他第一次感到悔恨。","t":[103,4368]},{"ar":"لكن هو أظهر الشجاعة مرة أخرى.","zh":"他再次鼓起勇气。","t":[4368,7250]}]},{"id":"ch15p45","audio":"ch15p45.mp3","sents":[{"ar":"ما هو المكان الذي تنصحني بزيارتة الآن؟","zh":"您现在建议我去哪个地方呢？","t":[103,3484]}]},{"id":"ch15p46","audio":"ch15p46.mp3","sents":[{"ar":"الكوكب الأرض، قال عالم الجغرافيا.","zh":"地球，地理学家答道。","t":[103,4118]},{"ar":"يُحظى بهذا السمعة الطيبة.","zh":"它享有盛名。","t":[4118,6263]}]},{"id":"ch15p47","audio":"ch15p47.mp3","sents":[{"ar":"الأمير الصغير غادر، يفكر في وردته.","zh":"小王子离去，心中想着他的花儿。","t":[103,3392]}]}]},{"id":"ch16","title_ar":"الفصل السادس عشر","title_en":"Chapter XVI","title_zh":"第 16 章","paras":[{"id":"ch16p00","audio":"ch16p00.mp3","sents":[{"ar":"وهكذا كان الكوكب السابع هو الأرض.","zh":"于是，第七颗行星便是地球。","t":[103,2800]}]},{"id":"ch16p01","audio":"ch16p01.mp3","sents":[{"ar":"الأرض ليست كوكبًا عاديًا فقط!","zh":"地球非同小可！","t":[103,3750]},{"ar":"يمكن العد؛ هناك 111 ملكًا (لا ننسى، بالتأكيد، ملوك السود بينهم)، 7000 عالم جغرافيا، 9 ملايين رجل أعمال، 75 مليون سكير، و311 مليون مرائي—that is to say، حوالي 200 مليون راشد تقريبًا.","zh":"可数的是，这里有111位国王（当然，别忘了，其中也有黑人国王），7000位地理学家，900万商人，7500万酒鬼，3.11亿自命不凡的人——也就是说，大约有2亿个大人。","t":[3750,26540]}]},{"id":"ch16p02","audio":"ch16p02.mp3","sents":[{"ar":"لإعطاء فكرة عن حجم الأرض، سأخبركم بأن قبل اختراع الكهرباء كان لزاماً على كل القارات الستة أن تحتفظ بحشد حقيقي من 462,511 من عمال الإنارة لحفظ مصابيح الشوارع.","zh":"为了让你对地球的大小有个具体概念，我得告诉你，在电发明之前，整个六大洲需要维持一支由四十六万二千五百一十一个点灯人组成的真正大军。","t":[103,17631]}]},{"id":"ch16p03","audio":"ch16p03.mp3","sents":[{"ar":"من بعد مسافة قليلة، سيكون ذلك مشهداً رائعاً.","zh":"从远处望去，那将是一场壮观的景象。","t":[103,5579]},{"ar":"حركات هذا الجيش ستُنظم مثل حركات الباليه في الأوبرا.","zh":"这支部队的动作将如同歌剧芭蕾舞般井然有序。","t":[5579,10842]},{"ar":"أولاً جاء دور مشعلي مصابيح نيوزيلندا وأستراليا.","zh":"新西兰和澳大利亚的提灯人将率先登场。","t":[10842,15855]},{"ar":"بعد إشعال مصابيحهم، ذهبوا إلى النوم.","zh":"点亮了灯，他们便去安睡了。","t":[15855,20158]},{"ar":"ثم، سيطعن في الرقصة محفظو الأنوار من الصين وسيبيريا، وسيعودون بعد ذلك إلى الخلفية.","zh":"接着，中国和西伯利亚的提灯人加入舞步，随后他们也渐渐退入幕后。","t":[20158,28908]},{"ar":"ثم يأتي دور عاملين الإنارة في روسيا والهند وإفريقيا وأوروبا وأمريكا الجنوبية وأمريكا الشمالية، لم يخطئوا قط في ترتيب دخولهم إلى المسرح.","zh":"接着，轮到俄罗斯和印度群岛的提灯人，然后是非洲和欧洲的，接着是南美洲的，最后是北美洲的。","t":[28908,41250]},{"ar":"لم يخطئوا قط في ترتيب دخولهم إلى المسرح.","zh":"他们的进场顺序从未出错。","t":[41250,45684]},{"ar":"مذهل للغاية.","zh":"壮观至极。","t":[45684,47052]}]},{"id":"ch16p04","audio":"ch16p04.mp3","sents":[{"ar":"فقط الرجل الذي كان في رئاسة المصباح الوحيد في القطب الشمالي وزميله المسؤول عن المصباح الوحيد في القطب الجنوبي كانا هما فقط من يعيشان بعيدا عن العناء والقلق: كانا مشغولين مرتين في السنة.","zh":"北极那盏灯的守护者，以及南极那盏灯的同事——唯有他们二人得以远离劳碌与烦恼：他们只需每年忙碌两次。","t":[103,15184]}]}]},{"id":"ch17","title_ar":"الفصل السابع عشر","title_en":"Chapter XVII","title_zh":"第 17 章","paras":[{"id":"ch17p00","audio":"ch17p00.mp3","sents":[{"ar":"عندما يريد المرء أن يكون مضحكًا، يمكنه الكذب قليلًا من وقت إلى آخر.","zh":"当人想卖弄聪明时，有时会稍稍偏离真相。","t":[103,7026]},{"ar":"لم أكن صادقًا تمامًا عندما تحدثت إليكم عن مشعلي المصابيح","zh":"我讲述点灯人的事时，并未全然坦诚。","t":[7026,11895]},{"ar":"وأدرك أنني أرتكب خطأً في تقديم فكرة خاطئة عن كوكبنا لمن لا يعرفه.","zh":"我意识到，我可能给那些不了解我们星球的人留下了错误的印象。","t":[11895,19092]},{"ar":"البشر يشغلون مكانًا صغيرًا جدًا على الأرض.","zh":"人在地球上占据的只是极小的一隅。","t":[19092,23553]},{"ar":"إذا وقف البليونا ساكن في هذا الكوكب واحتشدوا، كما في اجتماع، فباستطاعتهم بسهولة العيش في ساحة عامة طولها عشرون ميلًا وعرضها عشرون ميلًا.","zh":"若这二十亿居民都站立起来，且稍微挤一挤，就像他们参加大型集会那样，便能轻松地安置在二十英里长、二十英里宽的广场上。","t":[23553,36368]},{"ar":"إن الإنسانية كلها يمكن أن تتراكم على جزيرة صغيرة في المحيط الهادئ.","zh":"人类可以堆在太平洋上的一座小岛上。","t":[36368,42039]}]},{"id":"ch17p01","audio":"ch17p01.mp3","sents":[{"ar":"بالطبع، الكبار لن يؤمنوا بك عندما تخبرهم بهذا.","zh":"大人们，当然，当你告诉他们这些时，他们不会相信的。","t":[103,5461]},{"ar":"هم يعتقدون بأنهم يحتلون فراغًا كبيرًا","zh":"他们自以为占据了极大的空间。","t":[5461,8803]},{"ar":"يرون أنفسهم مهمين كالشجيرات الكبيرة.","zh":"他们自以为与猴面包树一样重要。","t":[8803,13132]},{"ar":"أنصحهم، ثم، بأن يقوموا بحساباتهم الخاصة.","zh":"你们不妨建议他们自己算一算。","t":[13132,18487]},{"ar":"يحبون الأرقام، وسيكون هذا ممتعًا لهم.","zh":"他们偏爱数字，这会让他们高兴的。","t":[18487,23250]},{"ar":"لا تضيع وقتك في هذه المهمة الإضافية.","zh":"但别在这额外任务上浪费时间。","t":[23250,27421]},{"ar":"ليس هذا ضروري.","zh":"这并无必要。","t":[27421,29868]},{"ar":"أنت تثق بي، أعلم ذلك.","zh":"你对我，我深知，满怀信心。","t":[29868,32474]}]},{"id":"ch17p02","audio":"ch17p02.mp3","sents":[{"ar":"عندما وصل الأمير الصغير إلى الأرض، تفاجأ برؤية أحد الناس.","zh":"小王子抵达地球时，惊讶地发现不见一人。","t":[103,6053]},{"ar":"بدأ يخشى الأمير الصغير أن يكون قد أخطأ الطريق إلى الكوكب، عندما تحركت لفة ذهبية شاحبة كالقمر في الرمل.","zh":"他开始害怕自己来到了错误的星球，就在这时，一道金色螺旋，月光般的光辉，在沙地上闪现。","t":[6053,15131]}]},{"id":"ch17p03","audio":"ch17p03.mp3","sents":[{"ar":"مساء الخير، قال الأمير الصغير بتهذيب.","zh":"“晚上好，”小王子有礼地说。","t":[103,3497]}]},{"id":"ch17p04","audio":"ch17p04.mp3","sents":[{"ar":"مساء الخير، قال الثعبان.","zh":"“晚上好，”蛇说。","t":[103,2615]}]},{"id":"ch17p05","audio":"ch17p05.mp3","sents":[{"ar":"على أي كوكب هبطت؟ سأل الأمير الصغير.","zh":"这颗星球，我降落在了哪里？小王子问道。","t":[103,4447]}]},{"id":"ch17p06","audio":"ch17p06.mp3","sents":[{"ar":"هذه الأرض، هذه أفريقيا، قال الثعبان.","zh":"这是地球；这是非洲，蛇回答说。","t":[103,3918]}]},{"id":"ch17p07","audio":"ch17p07.mp3","sents":[{"ar":"أوه!","zh":"啊！","t":[103,1526]},{"ar":"وهل هناك أناس على الأرض؟","zh":"地球上无人吗？","t":[1526,3579]}]},{"id":"ch17p08","audio":"ch17p08.mp3","sents":[{"ar":"هذه الصحراء.","zh":"这是沙漠。","t":[103,2158]},{"ar":"ليس هناك أي إنسان في الصحراء.","zh":"沙漠中无人迹。","t":[2158,5566]},{"ar":"الأرض كبيرة، قال الثعبان.","zh":"地球辽阔，蛇说。","t":[5566,8132]}]},{"id":"ch17p09","audio":"ch17p09.mp3","sents":[{"ar":"الأمير الصغير جلس على صخرة وأرفع عينيه نحو السماء.","zh":"小王子坐在一块石头上，仰望天空。","t":[103,4668]}]},{"id":"ch17p10","audio":"ch17p10.mp3","sents":[{"ar":"أتساءل عما إذا كانت النجوم مضاءة كي يعثر كل منا على نجمته ثانية...","zh":"他自言自语道：“我想知道，是不是星星在天空中被点亮，以便有一天我们都能找到属于自己的那颗。”","t":[103,6987]},{"ar":"انظروا إلى كوكبي","zh":"看我的星球。","t":[6987,8461]},{"ar":"هناك فوقنا مباشرة","zh":"它就在我们头顶上方。","t":[8461,10329]},{"ar":"كم هو بعيد!","zh":"它多么遥远啊！","t":[10329,11513]}]},{"id":"ch17p11","audio":"ch17p11.mp3","sents":[{"ar":"إنه جميل.","zh":"它真美。","t":[103,2171]},{"ar":"ما الذي جعلك هنا؟","zh":"你为何至此？","t":[2171,3790]}]},{"id":"ch17p12","audio":"ch17p12.mp3","sents":[{"ar":"لدي بعض المصاعب مع الزهرة، قال الأمير الصغير.","zh":"“我那朵花让我挺烦恼的。”小王子说。","t":[103,4195]}]},{"id":"ch17p13","audio":"ch17p13.mp3","sents":[{"ar":"- أوه! قال الثعبان.","zh":"啊！蛇说。","t":[103,2631]}]},{"id":"ch17p14","audio":"ch17p14.mp3","sents":[{"ar":"كانا صامتان.","zh":"他们俩都沉默了。","t":[103,1484]}]},{"id":"ch17p15","audio":"ch17p15.mp3","sents":[{"ar":"أين الرجال؟ أخذ الأمير الصغير في النهاية في الحديث مجدداً.","zh":"小王子终于又开口说话：“人们在哪里？”","t":[103,5763]}]},{"id":"ch17p16","audio":"ch17p16.mp3","sents":[{"ar":"في الصحراء، يشعر الإنسان بالوحدة...","zh":"沙漠中，有点孤单。","t":[103,2985]}]},{"id":"ch17p17","audio":"ch17p17.mp3","sents":[{"ar":"في البشر، الشعور بالوحدة كذلك.","zh":"人在人间，亦感孤寂。","t":[103,3300]}]},{"id":"ch17p18","audio":"ch17p18.mp3","sents":[{"ar":"الأمير الصغير نظر إليه لفترة طويلة.","zh":"小王子凝视着他许久。","t":[103,3510]}]},{"id":"ch17p19","audio":"ch17p19.mp3","sents":[{"ar":"هذا الحيوان مضحك، قال أخيرًا.","zh":"他终于说道：“你真是个有趣的动物。”","t":[103,4013]},{"ar":"أنت أنحف من الإصبع...","zh":"你细得就像一根手指。","t":[4013,5802]}]},{"id":"ch17p20","audio":"ch17p20.mp3","sents":[{"ar":"لكن أنا أقوى من إصبع الملك، قال الثعبان.","zh":"但我的力量胜过国王的手指。","t":[103,3787]}]},{"id":"ch17p21","audio":"ch17p21.mp3","sents":[{"ar":"الأمير الصغير ابتسم.","zh":"小王子微笑了。","t":[103,1958]}]},{"id":"ch17p22","audio":"ch17p22.mp3","sents":[{"ar":"أنت لست قوياً جدًا","zh":"你并不怎么强大。","t":[103,1708]},{"ar":"ليس لديك حتى قدم.","zh":"你连脚都没有。","t":[1708,4447]},{"ar":"لا يمكنك حتى السفر...","zh":"你甚至无法远行...","t":[4447,6303]}]},{"id":"ch17p23","audio":"ch17p23.mp3","sents":[{"ar":"يمكنني أن أحملك إلى أبعد ما يمكن لسفينة، قال الثعبان.","zh":"我能带你走得更远，蛇说。","t":[103,5182]}]},{"id":"ch17p24","audio":"ch17p24.mp3","sents":[{"ar":"لقد انسج حول ساق الأمير الصغير كحلقة ذهبية.","zh":"他如金镯般缠绕在小王子的脚踝上。","t":[103,4168]}]},{"id":"ch17p25","audio":"ch17p25.mp3","sents":[{"ar":"كل من ألمسه، أرسله إلى الأرض التي أتيا منها، قال الثعبان مجدداً.","zh":"无论我触及谁，都能将他送回他来的地方。","t":[103,6908]},{"ar":"لكن أنت برئ ونقي، وتأتي من نجم...","zh":"但你纯洁无瑕，来自星辰之巅。","t":[6908,10356]}]},{"id":"ch17p26","audio":"ch17p26.mp3","sents":[{"ar":"لم يرد الأمير الصغير.","zh":"小王子默然不语。","t":[103,1958]}]},{"id":"ch17p27","audio":"ch17p27.mp3","sents":[{"ar":"أنت ضعيف جدًا على هذه الأرض المكونة من الجرانيت، لربما استطعت مساعدتك في يوم من الأيام، إذا ما شعرت بحنين شديد إلى كوكبك، وأستطيع...","zh":"在这花岗岩构成的地球上，你如此羸弱，令我心生怜悯。","t":[103,13526]},{"ar":"إذا شعرت بالحنين إلى كوكبك، سأساعدك يوماً ما.","zh":"若你日思夜想，渴望回到自己的星球，我终将助你一臂之力。","t":[13526,18776]},{"ar":"أستطيعـ\"","zh":"我能——","t":[18776,19671]}]},{"id":"ch17p28","audio":"ch17p28.mp3","sents":[{"ar":"أوه...","zh":"哦！","t":[103,1487]},{"ar":"أفهمك تمامًا، الأمير الصغير.","zh":"我深知你的心意，小王子说。","t":[1487,5250]},{"ar":"لماذا دائمًا ما تتحدث بالألغاز؟","zh":"但你为何总是说谜语？","t":[5250,8158]}]},{"id":"ch17p29","audio":"ch17p29.mp3","sents":[{"ar":"أحلها جميعًا، قال الثعبان.","zh":"我解开所有的谜。","t":[103,2721]}]},{"id":"ch17p30","audio":"ch17p30.mp3","sents":[{"ar":"كانا صامتان.","zh":"他们俩都沉默了。","t":[103,1484]}]}]},{"id":"ch18","title_ar":"الفصل الثامن عشر","title_en":"Chapter XVIII","title_zh":"第 18 章","paras":[{"id":"ch18p00","audio":"ch18p00.mp3","sents":[{"ar":"الأمير الصغير عبر الصحراء والتقى بوردة واحدة فقط.","zh":"小王子穿越沙漠，邂逅了那朵花。","t":[103,5513]},{"ar":"زهرة ذات أوراق ثلاثة، زهرة لا قيمة لها على الإطلاق.","zh":"一朵三瓣的花，平凡无奇。","t":[5513,10369]}]},{"id":"ch18p01","audio":"ch18p01.mp3","sents":[{"ar":"صباح الخير، قال الأمير الصغير.","zh":"早上好，小王子说。","t":[103,2997]}]},{"id":"ch18p02","audio":"ch18p02.mp3","sents":[{"ar":"صباح الخير، قالت الزهرة.","zh":"早上好，花儿说。","t":[103,2615]}]},{"id":"ch18p03","audio":"ch18p03.mp3","sents":[{"ar":"أين الرجال؟ سأل الأمير الصغير بتهذيب.","zh":"小王子彬彬有礼地问道：“人在哪里？”","t":[103,4263]}]},{"id":"ch18p04","audio":"ch18p04.mp3","sents":[{"ar":"الوردة رأت ذات مرة قافلة تمر.","zh":"那朵花儿曾见过一队商队经过。","t":[103,3142]}]},{"id":"ch18p05","audio":"ch18p05.mp3","sents":[{"ar":"ألم يكن هناك رجال؟ سألت هي.","zh":"人吗？她应声而问。","t":[103,4697]},{"ar":"أعتقد أن هنالك ستة أو سبعة منهم تقريبًا.","zh":"世间大概有六七个这样的人。","t":[4697,9421]},{"ar":"رأيتُهم، قبل سنوات عديدة.","zh":"几年前我曾见过他们。","t":[9421,13263]},{"ar":"لا يمكن معرفة أين يجدونهم.","zh":"但无人能知晓他们在何方。","t":[13263,16921]},{"ar":"الريح تُطيحُ بها.","zh":"风将他们吹散了。","t":[16921,19316]},{"ar":"ليس لديهم جذور، وهذا يجعل حياتهم صعبة جدًا.","zh":"他们无根无基，生活因而颇为艰难。","t":[19316,23987]}]},{"id":"ch18p06","audio":"ch18p06.mp3","sents":[{"ar":"وداعاً، قال الأمير الصغير.","zh":"再见，小王子说。","t":[103,2550]}]},{"id":"ch18p07","audio":"ch18p07.mp3","sents":[{"ar":"وداعًا، قالت الزهرة.","zh":"再见，花儿说。","t":[103,2168]}]}]},{"id":"ch19","title_ar":"الفصل التاسع عشر","title_en":"Chapter XIX","title_zh":"第 19 章","paras":[{"id":"ch19p00","audio":"ch19p00.mp3","sents":[{"ar":"بعد ذلك، تسلق الأمير الصغير جبلًا عاليًا.","zh":"此后，小王子攀登上一座高山。","t":[103,4868]},{"ar":"الجبال التي عرفها هي البراكين الثلاث، التي تصل إلى ركبتيه فقط.","zh":"他仅知的山只有那三座火山，它们的高度仅至他的膝盖。","t":[4868,11658]},{"ar":"استخدم الأمير الصغير البركان الخامد كرائوسة للقدمين.","zh":"他用那座死火山当脚凳。","t":[11658,17079]},{"ar":"من قمة جبل عالٍ مثله، قال لنفسه: \"سأكون قادرًا على رؤية كل الكوكب في نظرة واحدة، والناس جميعًا...\"","zh":"从这座高山之巅，他自语道：“我一眼便能将整个星球尽收眼底，以及所有人……”","t":[17079,26382]}]},{"id":"ch19p01","audio":"ch19p01.mp3","sents":[{"ar":"لم ير شيئًا إلا قمم الصخور الحادة كالإبر.","zh":"只见岩石尖峰，如针般锋利。","t":[103,3523]}]},{"id":"ch19p02","audio":"ch19p02.mp3","sents":[{"ar":"صباح الخير، قال بتهذيب.","zh":"早上好，他礼貌地说。","t":[103,2668]}]},{"id":"ch19p03","audio":"ch19p03.mp3","sents":[{"ar":"صباح الخير—صباح الخير—صباح الخير، أجاب الصدى.","zh":"早上好——早上好——早上好，回声答道。","t":[103,5050]}]},{"id":"ch19p04","audio":"ch19p04.mp3","sents":[{"ar":"من أنت؟ قال الأمير الصغير.","zh":"你是谁？小王子问道。","t":[103,3197]}]},{"id":"ch19p05","audio":"ch19p05.mp3","sents":[{"ar":"من أنت – من أنت – من أنت؟ أجاب الصدى","zh":"你是谁——你是谁——你是谁？回声应道。","t":[103,4447]}]},{"id":"ch19p06","audio":"ch19p06.mp3","sents":[{"ar":"كن صديقي، فأنا وحيد تمامًا","zh":"做我的朋友吧。","t":[103,2774]},{"ar":"أنا وحيد تمامًا، قال.","zh":"我孤零零一人，他说。","t":[2774,5024]}]},{"id":"ch19p07","audio":"ch19p07.mp3","sents":[{"ar":"أنا وحيد تمامًا... وحيد تمامًا... وحيد تمامًا، أجاب الصدى.","zh":"我孤零零一人——孤零零一人——孤零零一人，回声应道。","t":[103,7329]}]},{"id":"ch19p08","audio":"ch19p08.mp3","sents":[{"ar":"كم كوكب غريب! فكر في نفسه.","zh":"多么奇特的星球啊，他想。","t":[103,4724]},{"ar":"جاف تمامًا، وقطيع تمامًا، وشرس تمامًا، ومرعب تمامًا.","zh":"干涸而尖锐，严酷而拒人于千里之外。","t":[4724,7671]},{"ar":"الناس يفتقرون إلى الخيال.","zh":"人们缺乏想象力。","t":[7671,14803]},{"ar":"يكررون ما يقولون لهم...","zh":"他们重复着别人对他们的每一句话。","t":[14803,17776]},{"ar":"على كوكبي كان لدي زهرة، كانت دائمًا من يبدأ الحديث...","zh":"在我的星球上，我有一朵花，她总是抢先开口……","t":[17776,22356]}]}]},{"id":"ch20","title_ar":"الفصل العشرون","title_en":"Chapter XX","title_zh":"第 20 章","paras":[{"id":"ch20p00","audio":"ch20p00.mp3","sents":[{"ar":"لكن حدث أن بعد مشي الأمير الصغير لفترة طويلة عبر الرمال والصخور والثلج، وصل أخيرًا إلى طريق.","zh":"走过漫漫长路，穿过沙丘、岩石和雪地，小王子终于找到了一条道路。","t":[103,8511]}]},{"id":"ch20p01","audio":"ch20p01.mp3","sents":[{"ar":"وكل الطرق تؤدي إلى بيت الإنسان.","zh":"所有道路都通向人类的居所。","t":[103,2918]}]},{"id":"ch20p02","audio":"ch20p02.mp3","sents":[{"ar":"صباح الخير، قال.","zh":"早上好，他道。","t":[103,2090]}]},{"id":"ch20p03","audio":"ch20p03.mp3","sents":[{"ar":"كان يقف أمام حديقة مزدهرة بالورود.","zh":"他站在一片盛开的玫瑰花丛前。","t":[103,3524]}]},{"id":"ch20p04","audio":"ch20p04.mp3","sents":[{"ar":"صباح الخير، قالت الوردة.","zh":"玫瑰们道：“早上好。”","t":[103,2695]}]},{"id":"ch20p05","audio":"ch20p05.mp3","sents":[{"ar":"الأمير الصغير نظر إليهن.","zh":"小王子凝望着她们。","t":[103,3342]},{"ar":"كلها تبدو كزهرته.","zh":"她们都像他的那朵花。","t":[3342,5052]}]},{"id":"ch20p06","audio":"ch20p06.mp3","sents":[{"ar":"من أنتم؟ قال، مذهولاً.","zh":"他惊愕地问道：“你们是谁？”","t":[103,3645]}]},{"id":"ch20p07","audio":"ch20p07.mp3","sents":[{"ar":"نحن زهور، قالت الزهور.","zh":"“我们是玫瑰，”玫瑰们说。","t":[103,2603]}]},{"id":"ch20p08","audio":"ch20p08.mp3","sents":[{"ar":"وفجأة غمره الحزن","zh":"他不禁悲伤不已。","t":[103,1918]},{"ar":"لقد أخبرته زهرته بأنها الوحيدة من نوعها في كل الكون.","zh":"他的玫瑰曾告诉他，她是宇宙间独一无二的存在。","t":[1918,7632]},{"ar":"وهنا خمسة آلاف منها، وكلها متشابهة، في حديقة واحدة!","zh":"在这片花园里，五千朵玫瑰，无一例外。","t":[7632,13500]}]},{"id":"ch20p09","audio":"ch20p09.mp3","sents":[{"ar":"سيكون غاضباً جدًا، قال لنفسه، إذا رأت ذلك...","zh":"她若看到这些，一定会非常生气。","t":[103,5526]},{"ar":"ستقوم بالسعال بشدة، وتزيف أنك على وشك الموت لتجنب أن تُضحك عليك.","zh":"她将痛苦地咳嗽，装作自己快要死去，以免被人嘲笑。","t":[5526,12934]},{"ar":"وأنا سأكون مُلزماً بالتظاهر بأنني أعتني بها لاستعادة حياتها – لأنني إذا لم أفعل ذلك، لأهون نفسي أيضًا، ستسمح لنفسها بالموته حقًا...","zh":"我只好装作在悉心照料她，让她恢复生机——否则，为了自谦，她真的会让自己死去……","t":[12934,25316]}]},{"id":"ch20p10","audio":"ch20p10.mp3","sents":[{"ar":"عتقدت بأنني غني، ومعي وردة فريدة في العالم، بينما أنا في الواقع أملك وردة عادية، تلك الوردة، وبعثورتي الثلاثة التي تصل إلى ركبتي، ومنها بركان خامد ربما للأبد لا يجعلني أميرًا عظيمًا جدًا.","zh":"我以为自己富足，却原来只拥有了一朵普普通通的玫瑰。","t":[103,19079]},{"ar":"وردة عادية، وثلاث براكين تصل إلى ركبتي، وربما واحد منها قد انطفأ للأبد...","zh":"一朵平凡的玫瑰，三座仅及膝高的火山——其中一座或许永远熄灭。","t":[19079,27421]},{"ar":"هذا لا يجعلني أميرًا عظيمًا جدًا...","zh":"这并不能使我成为一位伟大的王子……","t":[27421,30342]}]},{"id":"ch20p11","audio":"ch20p11.mp3","sents":[{"ar":"وعندما استلقى في العشب بكى.","zh":"他躺在草地上，失声痛哭。","t":[103,2247]}]}]},{"id":"ch21","title_ar":"الفصل الحادي والعشرون","title_en":"Chapter XXI","title_zh":"第 21 章","paras":[{"id":"ch21p00","audio":"ch21p00.mp3","sents":[{"ar":"ثم ظهر الثعلب.","zh":"那时，狐狸出现了。","t":[103,1563]}]},{"id":"ch21p01","audio":"ch21p01.mp3","sents":[{"ar":"صباح الخير، قال الثعلب.","zh":"早上好，狐狸说。","t":[103,2524]}]},{"id":"ch21p02","audio":"ch21p02.mp3","sents":[{"ar":"صباح الخير، الأمل الصغير أجاب بتهذيب، ومع ذلك عندما التفت لم ير شيئًا.","zh":"早上好，小王子有礼地回应，尽管他转身四顾，却什么也没看见。","t":[103,6906]}]},{"id":"ch21p03","audio":"ch21p03.mp3","sents":[{"ar":"أنا هنا، تحت شجرة التفاح.","zh":"“我就在苹果树下。”","t":[103,2695]}]},{"id":"ch21p04","audio":"ch21p04.mp3","sents":[{"ar":"من أنت؟ أنت ظريف جدًا.","zh":"小王子问：“你是谁？你看起来真美。”","t":[103,3184]}]},{"id":"ch21p05","audio":"ch21p05.mp3","sents":[{"ar":"أنا ثعلب، قال الثعلب.","zh":"“我是狐狸，”狐狸说。","t":[103,2221]}]},{"id":"ch21p06","audio":"ch21p06.mp3","sents":[{"ar":"تعال واللعب معي، اقترح الأمير الصغير.","zh":"来和我一起玩吧，小王子提议。","t":[103,4645]},{"ar":"أنا حزين جدًا","zh":"我如此不快乐。","t":[4645,6144]}]},{"id":"ch21p07","audio":"ch21p07.mp3","sents":[{"ar":"لا أستطيع أن ألعب معك، قال الثعلب.","zh":"我不能与你玩耍，狐狸说。","t":[103,4263]},{"ar":"لم أُطعم، لم أُشرب، لم أُمسح، لم أُحب.","zh":"我尚未被驯服。","t":[4263,8421]}]},{"id":"ch21p08","audio":"ch21p08.mp3","sents":[{"ar":"أوه!","zh":"啊！","t":[103,1526]},{"ar":"يرجى العفو، قال الأمير الصغير.","zh":"请见谅，小王子说。","t":[1526,4250]}]},{"id":"ch21p09","audio":"ch21p09.mp3","sents":[{"ar":"لكن، بعد بعض التفكير، أضاف: \"ماذا يعني ذلك– 'التربية'؟\"","zh":"但经过一番思考，他又问：“那‘驯服’究竟是什么意思？”","t":[103,5747]}]},{"id":"ch21p10","audio":"ch21p10.mp3","sents":[{"ar":"أنت لا تعيش هنا، قال الثعلب.","zh":"你并不住在这里。","t":[103,3737]},{"ar":"ماذا تبحث عنه؟","zh":"你在寻找什么？","t":[3737,5198]}]},{"id":"ch21p11","audio":"ch21p11.mp3","sents":[{"ar":"أبحث عن البشر، قال الأمير الصغير.","zh":"我寻找人类，小王子说。","t":[103,4184]},{"ar":"ماذا تعني كلمة أليف؟","zh":"那“驯服”究竟是什么意思？","t":[4184,6198]}]},{"id":"ch21p12","audio":"ch21p12.mp3","sents":[{"ar":"الناس، قال الثعلب.","zh":"人们，狐狸说。","t":[103,2908]},{"ar":"البشر يمتلكون البنادق ويصطادون.","zh":"他们有枪，他们打猎。","t":[2908,6829]},{"ar":"يُزعجني ذلك للغاية.","zh":"令人心绪不宁。","t":[6829,9671]},{"ar":"يتربون على الدجاج أيضًا.","zh":"人们也养鸡。","t":[9671,12789]},{"ar":"هذه هي اهتماماتهم الوحيدة.","zh":"这些便是他们的唯一兴趣。","t":[12789,16132]},{"ar":"هل تبحث عن الدجاج؟","zh":"你在找鸡吗？","t":[16132,17815]}]},{"id":"ch21p13","audio":"ch21p13.mp3","sents":[{"ar":"لا، قال الأمير الصغير.","zh":"“不，”小王子说。","t":[103,3237]},{"ar":"أبحث عن أصدقاء","zh":"我在寻找朋友。","t":[3237,4513]},{"ar":"ماذا يعني ذلك– 'التربية'؟","zh":"那“驯服”究竟是什么意思？","t":[4513,6592]}]},{"id":"ch21p14","audio":"ch21p14.mp3","sents":[{"ar":"هذا العمل يُنسيه الناس كثيرًا، قال الثعلب.","zh":"这是件常被忽视的行为，狐狸说。","t":[103,4816]},{"ar":"إقامة روابط الصداقة","zh":"建立联系。","t":[4816,6881]}]},{"id":"ch21p15","audio":"ch21p15.mp3","sents":[{"ar":"ماذا تعني كلمة أليف؟","zh":"建立联系？","t":[103,2116]}]},{"id":"ch21p16","audio":"ch21p16.mp3","sents":[{"ar":"هكذا، قال الثعلب.","zh":"“就如此，”狐狸说。","t":[103,2947]},{"ar":"أنت لست لي سوى صبي صغير كأي مئة ألف صبي صغير آخر.","zh":"对你而言，我不过是一个和无数小男孩无异的男孩。","t":[2947,8724]},{"ar":"ليس لي حاجة لك.","zh":"我并不需要你。","t":[8724,11184]},{"ar":"ولكنك، من جانبك، لا تحتاجين إليّ.","zh":"你对我，也无需任何依赖。","t":[11184,16000]},{"ar":"أنا لست شيئًا أكثر من ثعلب مثلي مثل مئة ألف ثعلب آخر.","zh":"对你而言，我不过是一只和其他成千上万的狐狸一样的狐狸。","t":[16000,22000]},{"ar":"لكن إذا تربيتني، فإننا سنحتاج بعضنا البعض.","zh":"但若你驯服了我，我们便彼此需要。","t":[22000,27092]},{"ar":"في عينيك، سأكون فريدًا في كل العالم","zh":"在你眼中，我是这世上独一无二的。","t":[27092,30395]},{"ar":"في عالمك، سأكون فريدًا في كل شيء...","zh":"在你们的世界里，我将独一无二。","t":[30395,33790]}]},{"id":"ch21p17","audio":"ch21p17.mp3","sents":[{"ar":"بدأت أفهم، قال الأمير الصغير.","zh":"我开始明白了，小王子说。","t":[103,3908]},{"ar":"هناك زهرة...","zh":"那朵花儿……","t":[3908,5947]},{"ar":"أعتقد أنّها قد تربيتني...","zh":"我想她已经驯服了我……","t":[5947,8263]}]},{"id":"ch21p18","audio":"ch21p18.mp3","sents":[{"ar":"من الممكن، قال الثعلب.","zh":"“这可能，”狐狸说。","t":[103,3276]},{"ar":"إن المرء يرى أشياء شتى على الأرض","zh":"地球上可见万物。","t":[3276,5776]}]},{"id":"ch21p19","audio":"ch21p19.mp3","sents":[{"ar":"أوه، لكن هذا ليس على الأرض! قال الأمير الصغير.","zh":"哦，但这里可不是在地球上！小王子说。","t":[103,5197]}]},{"id":"ch21p20","audio":"ch21p20.mp3","sents":[{"ar":"كان الثعلب يبدو محيرًا، وملئ الفضول.","zh":"狐狸显得困惑，十分好奇。","t":[103,3800]}]},{"id":"ch21p21","audio":"ch21p21.mp3","sents":[{"ar":"على كوكب آخر؟","zh":"在另一个星球上？","t":[103,1603]}]},{"id":"ch21p22","audio":"ch21p22.mp3","sents":[{"ar":"نعم.","zh":"是的。","t":[103,774]}]},{"id":"ch21p23","audio":"ch21p23.mp3","sents":[{"ar":"هل هناك صيادون على هذا الكوكب؟","zh":"这颗星球上有猎人吗？","t":[103,2642]}]},{"id":"ch21p24","audio":"ch21p24.mp3","sents":[{"ar":"لا أستطيع أن ألعب معك، فأنا لست أليفًا.","zh":"没有。","t":[103,3905]}]},{"id":"ch21p25","audio":"ch21p25.mp3","sents":[{"ar":"أوه، هذا مثير للاهتمام!","zh":"哦，这很有意思！","t":[103,3658]},{"ar":"هناك دجاج؟","zh":"这里有鸡吗？","t":[3658,4882]}]},{"id":"ch21p26","audio":"ch21p26.mp3","sents":[{"ar":"لا أستطيع أن ألعب معك، فأنا لست أليفًا.","zh":"不。","t":[103,3905]}]},{"id":"ch21p27","audio":"ch21p27.mp3","sents":[{"ar":"لا شيء مثالي، نادى الثعلب.","zh":"世间无完美，狐狸叹了口气。","t":[103,2747]}]},{"id":"ch21p28","audio":"ch21p28.mp3","sents":[{"ar":"لكن عاد إلى فكرته.","zh":"但他又回到了自己的想法。","t":[103,1905]}]},{"id":"ch21p29","audio":"ch21p29.mp3","sents":[{"ar":"حياتي متعبة جدًا، قال الثعلب.","zh":"我的生活极为单调，狐狸说。","t":[103,4000]},{"ar":"أنا أطارد الدجاج، والأشخاص يطاردونني.","zh":"我捕猎鸡，人捕猎我。","t":[4000,4842]},{"ar":"كل الدجاج متشابه، وكل الرجال متشابهون.","zh":"所有的鸡都长得一样，所有的人也都一样。","t":[4842,13329]},{"ar":"ولكن، كنتُ مملًا قليلاً.","zh":"因此，我有些无聊。","t":[13329,17000]},{"ar":"لكن إذا خضتني، سيكون كأن الشمس بدأت تضيء حياتي.","zh":"但若你驯服了我，就如同阳光照耀我的生命。","t":[17000,22645]},{"ar":"سأعرف صوت خطوة مختلف عن جميع الخطوات الأخرى.","zh":"我将能辨识出与众不同的脚步声。","t":[22645,27711]},{"ar":"أقفال أخرى تدفعني إلى الاندفاع إلى أسفل الأرض.","zh":"其他脚步声让我匆忙钻回地下。","t":[27711,32368]},{"ar":"سيطلق عليك، كالموسيقى، من قبوّي.","zh":"你的脚步声，如同音乐，将把我从洞穴中唤醒。","t":[32368,36855]},{"ar":"ثم انظروا: هل ترون الحقول الزراعية هناك؟","zh":"然后瞧：你看到那边的麦田了吗？","t":[36855,41526]},{"ar":"لا أتناول الخبز.","zh":"我不吃面包。","t":[41526,43934]},{"ar":"القمح ليس له فائدة لي.","zh":"麦子对我毫无用处。","t":[43934,47145]},{"ar":"حقول القمح لا تقول لي شيئًا.","zh":"麦田对我默默无言。","t":[47145,50500]},{"ar":"وهذا محزن جدًا","zh":"这实在可悲！","t":[50500,52026]},{"ar":"أنت تملك شعرًا بلون الذهب، لذلك سيكون الأمر رائعًا حين تجعلني أليفًا!","zh":"你的头发是金色的。","t":[52026,59461]},{"ar":"هل تتصور جمال ذلك عندما أتقنك!","zh":"想见你驯服我后的美好景象吧！","t":[59461,63263]},{"ar":"الحبوب التي هي أيضًا ذهبية ستجلبني إلى ذكراك.","zh":"麦子的金色会让我想起你。","t":[63263,68447]},{"ar":"أود أن أستمع إلى هبوب الريح في حقل القمح...","zh":"我愿倾听麦田中风的低语……","t":[68447,71895]}]},{"id":"ch21p30","audio":"ch21p30.mp3","sents":[{"ar":"الثعبان نظر إلى الأمير الصغير لفترة طويلة.","zh":"狐狸久久地凝视着小王子。","t":[103,3879]}]},{"id":"ch21p31","audio":"ch21p31.mp3","sents":[{"ar":"يرجى-- أهتم بي! قال","zh":"请——驯服我吧！","t":[103,3947]}]},{"id":"ch21p32","audio":"ch21p32.mp3","sents":[{"ar":"أريدُ ذلك، جدًا.","zh":"我非常愿意。","t":[103,2961]},{"ar":"ليس لدي وقت كثير.","zh":"但我没有太多时间。","t":[2961,5816]},{"ar":"لدي أصدقاء لأكتشفهم، وأشياء كثيرة لأفهمها.","zh":"我有朋友要结识，有许多事要理解。","t":[5816,10461]}]},{"id":"ch21p33","audio":"ch21p33.mp3","sents":[{"ar":"فقط يفهم الإنسان ما يهذبه، قال الثعلب.","zh":"驯服了的东西，人才懂得它的价值。","t":[103,4592]},{"ar":"الناس لم يعد لديهم وقت لفهم أي شيء.","zh":"人们不再有时间去理解任何事物。","t":[4592,8934]},{"ar":"يشترون الأشياء الجاهزة من المتاجر.","zh":"他们在商店里购买现成的东西。","t":[8934,12789]},{"ar":"لا توجد محلات في أي مكان يمكن فيها شراء الصداقة، ولذلك لم يعد الناس يملكون أصدقاء.","zh":"然而，世间并无店铺可售友谊，故人皆无友。","t":[12789,21553]},{"ar":"إذا كنت تريد صديقًا، تربني...","zh":"若你愿与我结伴，驯服我吧……","t":[21553,24381]}]},{"id":"ch21p34","audio":"ch21p34.mp3","sents":[{"ar":"ماذا يجب أن أفعل، لأهذبك؟ سأل الأمير الصغير.","zh":"我该做些什么，才能驯服你？","t":[103,5605]}]},{"id":"ch21p35","audio":"ch21p35.mp3","sents":[{"ar":"عليك أن تكون صبورًا جدًا، قال الثعلب.","zh":"你必须非常耐心，狐狸回答道。","t":[103,4447]},{"ar":"أولاً، ستجلس بعيدًا عني– هكذا– في العشب.","zh":"首先，你将坐在离我一段距离的地方——就像这样——在草地上。","t":[4447,9487]},{"ar":"سأشاهدك من زاوية عيني، وأنت لن تقول شيئًا.","zh":"我斜眼瞥着你，你不必说一句话。","t":[9487,14829]},{"ar":"الكلمات مصدر للإحراج.","zh":"言语是误会的根源。","t":[14829,18000]},{"ar":"لكنك ستقترب مني قليلاً كل يوم...","zh":"但你每天都要离我近一点……","t":[18000,21144]}]},{"id":"ch21p36","audio":"ch21p36.mp3","sents":[{"ar":"اليوم التالي عاد الأمير الصغير.","zh":"次日，小王子又来了。","t":[103,2616]}]},{"id":"ch21p37","audio":"ch21p37.mp3","sents":[{"ar":"سيكون من الأفضل أن تعود في نفس الوقت، قال الثعلب.","zh":"最好是同一时间回来，狐狸说。","t":[103,5408]},{"ar":"إذا، على سبيل المثال، تأتي في الساعة الرابعة بعد الظهر، فإنني سأبدأ في الشعور بالسعادة في الساعة الثالثة.","zh":"若你下午四点钟来，那么从三点钟开始，我便开始感到幸福了。","t":[5408,15158]},{"ar":"كلما مر الوقت، يزداد سعادتي يوماً بعد يوم.","zh":"随着时光流逝，我的快乐将愈发浓烈。","t":[15158,20263]},{"ar":"في الرابعة، سأكون قلقي ومتحرك بحماس.","zh":"四点钟，我已开始焦虑不安，坐立难安。","t":[20263,25211]},{"ar":"سأريك كيف أنني سعيد!","zh":"我将向你展示我是多么快乐！","t":[25211,28368]},{"ar":"لكن إذا جئت في أي وقت، لن أعرف أين سيكون قلبي مستعدًا لمقابلتك...","zh":"但如果你随时来访，我就永远不知道何时我的心该准备好迎接你……","t":[28368,35579]},{"ar":"يجب أن يتم الالتزام بالطقوس المناسبة...","zh":"必须遵守适当的仪式……","t":[35579,38763]}]},{"id":"ch21p38","audio":"ch21p38.mp3","sents":[{"ar":"ما هو الطقوس؟ سأل الأمير الصغير.","zh":"小王子问：“什么是仪式？”","t":[103,3921]}]},{"id":"ch21p39","audio":"ch21p39.mp3","sents":[{"ar":"هذه أيضًا هي الأفعال التي تُنسى غالبًا، قال الثعلب.","zh":"那些也是常被忽视的行为，狐狸说。","t":[103,5434]},{"ar":"ما يجعل يومًا مختلفًا عن الأيام الأخرى، ساعة مختلفة عن الساعات الأخرى.","zh":"它们使一日不同于他日，一小时不同于其他小时。","t":[5434,12513]},{"ar":"هناك طقوس، على سبيل المثال، بين محاربتي.","zh":"例如，我的猎人中有一种仪式。","t":[12513,17868]},{"ar":"كلُّ خميس، يرقصون مع فتيات القرية.","zh":"每周四，他们与村里的姑娘们共舞。","t":[17868,22132]},{"ar":"الجمعة هي يوم رائع بالنسبة لي!","zh":"星期四对我来说是个美好的日子！","t":[22132,26039]},{"ar":"أستطيع السير حتى وصولي إلى الكروم.","zh":"我可以一直走到葡萄园。","t":[26039,29737]},{"ar":"لكن إذا كان الصيادون يرقصون في أي وقت، فسيكون كل يوم مثل أي يوم آخر، ولن أملك أي عطلة على الإطلاق.","zh":"但若猎人随时跳舞，那么每一天都将如同其他日子，我便永远没有假期可言。","t":[29737,39119]}]},{"id":"ch21p40","audio":"ch21p40.mp3","sents":[{"ar":"ثم تربى الأمير الصغير الثعلب.","zh":"小王子驯服了狐狸。","t":[103,3421]},{"ar":"وحين اقترب وقت رحيله...","zh":"当离别的时刻临近——","t":[3421,5460]}]},{"id":"ch21p41","audio":"ch21p41.mp3","sents":[{"ar":"أنا سأبكي...","zh":"啊，狐狸说，我要哭了。","t":[103,1169]}]},{"id":"ch21p42","audio":"ch21p42.mp3","sents":[{"ar":"هذا خطأك، الأمير الصغير قال.","zh":"是你的错，小王子说。","t":[103,4066]},{"ar":"لم أكن أرغب في ضررك بأي شكل من الأشكال، ولكنك كنت تريد مني أن أتأهبك...","zh":"我从未希望给你带来伤害；但你却想让我驯服你……","t":[4066,10908]}]},{"id":"ch21p43","audio":"ch21p43.mp3","sents":[{"ar":"نعم، هذا صحيح، قال الثعلب.","zh":"是的，是这样的，狐狸说。","t":[103,3156]}]},{"id":"ch21p44","audio":"ch21p44.mp3","sents":[{"ar":"لكن الآن ستبكين! قال الأمير الصغير.","zh":"但你现在要哭了！小王子说。","t":[103,4302]}]},{"id":"ch21p45","audio":"ch21p45.mp3","sents":[{"ar":"نعم، هذا صحيح، قال الثعلب.","zh":"是的，是这样的，狐狸说。","t":[103,3156]}]},{"id":"ch21p46","audio":"ch21p46.mp3","sents":[{"ar":"لم يكن لك منها أي فائدة على الإطلاق!","zh":"对你毫无益处。","t":[103,3208]}]},{"id":"ch21p47","audio":"ch21p47.mp3","sents":[{"ar":"\"لقد فعل لي الخير،\" قال الثعلب، \"بسبب لون حقول القمح.\" ثم أضاف:","zh":"“它让我感到愉悦，”狐狸说，“因为麦田的颜色。”然后他又补充道：","t":[103,6366]}]},{"id":"ch21p48","audio":"ch21p48.mp3","sents":[{"ar":"اذهب وابحث عن الورود مرة أخرى.","zh":"再去看看那些玫瑰。","t":[103,3803]},{"ar":"إن وردتك، في هذا العالم، فريدة من نوعها.","zh":"你的玫瑰，在这世上独一无二。","t":[3803,8921]},{"ar":"ثم تعود إليّ لأقول وداعاً، وسأعطيك هدية سر.","zh":"然后回来向我告别，我会送你一个秘密作为礼物。","t":[8921,13592]}]},{"id":"ch21p49","audio":"ch21p49.mp3","sents":[{"ar":"الأمير الصغير غادر ليعود ويشاهد الوردة مرة أخرى.","zh":"小王子离去，再次凝视着玫瑰。","t":[103,4629]}]},{"id":"ch21p50","audio":"ch21p50.mp3","sents":[{"ar":"أنت لست بتلك الطريقة كورودتي، قال.","zh":"你那朵玫瑰与我截然不同。","t":[103,4408]},{"ar":"أنت لا تملك شيئًا حتى الآن.","zh":"你尚无所有。","t":[4408,7605]},{"ar":"لا أحد قد تربى عليك، وأنت لم تربي أحدًا.","zh":"无人驯服于你，你亦未驯服他人。","t":[7605,12408]},{"ar":"أنت تشبه الثعلب الذي التقيت به أول مرة.","zh":"你就像我最初遇见的那只狐狸。","t":[12408,16829]},{"ar":"كان مجرد ثعلب مثل مئة ألف من الثعالب الآخرين.","zh":"他只是一只和其他成千上万的狐狸一样的狐狸。","t":[16829,21921]},{"ar":"لكنني جعلته صديقي، والآن هو فريد من نوعه في العالم.","zh":"但他已成了我的朋友，现在他是这世上独一无二的。","t":[21921,27013]}]},{"id":"ch21p51","audio":"ch21p51.mp3","sents":[{"ar":"ورود كانت محرجة جدًا","zh":"玫瑰们感到非常尴尬。","t":[103,2497]}]},{"id":"ch21p52","audio":"ch21p52.mp3","sents":[{"ar":"أنت جميلة، لكنك فارغة، استمر في الحديث.","zh":"你美丽，却空洞无物。","t":[103,5105]},{"ar":"لا يمكن أن يموت أحد من أجلك.","zh":"人们不会为你而死。","t":[5105,8618]},{"ar":"بالطبع، لقد كان ليعتقد المارة العاديون أن وردتي تبدو تمامًا مثلك - الوردة التي تخصني.","zh":"当然，一个普通的过路人会认为我的玫瑰和你的一样——那朵属于我的玫瑰。","t":[8618,17526]},{"ar":"لأنها هي التي سقيتها، لأنها هي التي غطيتها بغلاية زجاجية، لأنها هي التي حمايتها وراء ستارة، لأنها هي التي قتلت الذباب منها (معدًا استثناءً لأثنتين أو ثلاثة التي احتفظنا بها لتصبح فراشات)، لأنها هي التي استمعت إليها عندما شكت، أو استبقت، أو حتى عندما لم تقول شيئًا.","zh":"然而，仅凭她自身，她比你们所有数百朵玫瑰都要重要：因为是我为她浇水；是我为她罩上玻璃罩；是我为她挡风遮雨；是我为她杀死了毛毛虫（除了我们留下变成蝴蝶的那两三只）；是我倾听她的抱怨，或她的自夸，有时甚至在她默默无言时。","t":[17526,43697]},{"ar":"لأنها وردتي.","zh":"因为她是我玫瑰。","t":[43697,45197]}]},{"id":"ch21p53","audio":"ch21p53.mp3","sents":[{"ar":"ثم عاد إلى الثعلب.","zh":"他回到狐狸那里。","t":[103,1735]}]},{"id":"ch21p54","audio":"ch21p54.mp3","sents":[{"ar":"وداعاً، قال.","zh":"再见，他说。","t":[103,1681]}]},{"id":"ch21p55","audio":"ch21p55.mp3","sents":[{"ar":"وداعًا، قال الثعلب.","zh":"再见，狐狸说。","t":[103,2974]},{"ar":"ما هو سرى، سر بسيط جدًا: يمكن للقلب فقط أن يرى بشكل صحيح؛ ما هو أساسي لا يمكن رؤيته بالعين.","zh":"用心去看，才能看得真切；本质的东西，肉眼是看不见的。","t":[2974,12382]}]},{"id":"ch21p56","audio":"ch21p56.mp3","sents":[{"ar":"ما هو جوهري لا يمكن رؤيته بالعين، قال الأمير الصغير مرارًا ليتأكد من تذكره.","zh":"本质的东西，肉眼难辨，小王子反复念诵，以便牢记于心。","t":[103,7208]}]},{"id":"ch21p57","audio":"ch21p57.mp3","sents":[{"ar":"الزمن الذي ضيعته على وردتك هو الذي يجعل وردتك مهمة جدًا.","zh":"你为你的玫瑰浪费的时间，使你的玫瑰变得如此重要。","t":[103,5774]}]},{"id":"ch21p58","audio":"ch21p58.mp3","sents":[{"ar":"هذا الوقت الذي ضيعته على وردتي... قال الأمير الصغير، ليتأكد من أن يذكر.","zh":"“我为我的玫瑰浪费的时间——”小王子说，以便确保自己能记住。","t":[103,7250]}]},{"id":"ch21p59","audio":"ch21p59.mp3","sents":[{"ar":"الناس قد نسوا هذه الحقيقة، قال الثعلب.","zh":"人们已遗忘这一真理，狐狸说。","t":[103,4487]},{"ar":"لا تنسى ذلك.","zh":"但你切莫忘记。","t":[4487,6645]},{"ar":"أصبحت مسؤولًا إلى الأبد عما تربته.","zh":"你一旦驯服了什么，便永远对其负责。","t":[6645,10526]},{"ar":"أنت مسؤول عن وردتك...","zh":"你须对你的玫瑰负责……","t":[10526,12434]}]},{"id":"ch21p60","audio":"ch21p60.mp3","sents":[{"ar":"أنا مسؤول عن وردتي...","zh":"我为我的玫瑰负责，小王子反复说道，以便牢记于心。","t":[103,1932]}]}]},{"id":"ch22","title_ar":"الفصل الثاني والعشرون","title_en":"Chapter XXII","title_zh":"第 22 章","paras":[{"id":"ch22p00","audio":"ch22p00.mp3","sents":[{"ar":"صباح الخير، قال الأمير الصغير.","zh":"早上好，小王子说。","t":[103,2997]}]},{"id":"ch22p01","audio":"ch22p01.mp3","sents":[{"ar":"صباح الخير، قال عامل التحويل في السكة الحديدية.","zh":"早上好，扳道工说。","t":[103,4235]}]},{"id":"ch22p02","audio":"ch22p02.mp3","sents":[{"ar":"ماذا تفعل هنا يا أمير الصغير؟","zh":"小王子问道：“你在此做什么？”","t":[103,2629]}]},{"id":"ch22p03","audio":"ch22p03.mp3","sents":[{"ar":"أنا أقسم المسافرين في مجموعات من ألف، قال القائم على التحكم في الطريق.","zh":"“我负责把旅客分成一千人一组的批次，”扳道工说。","t":[103,7000]},{"ar":"أنا أرسل القطارات التي تحملهم؛ الآن إلى اليمين، الآن إلى اليسار.","zh":"我调度着载着他们的火车，时而向右，时而向左。","t":[7000,13118]}]},{"id":"ch22p04","audio":"ch22p04.mp3","sents":[{"ar":"قطار سريع مضيء كالنور يهتز قلبًا قلبًا، يمر بصوت هدير كالرعد، يزعزع مكتب القائم بالتحويل.","zh":"一列灯火通明的快车如雷霆般轰鸣而过，震得扳道工的小屋摇摇欲坠。","t":[103,8985]}]},{"id":"ch22p05","audio":"ch22p05.mp3","sents":[{"ar":"هم في عجلة كبيرة، قال الأمير الصغير.","zh":"他们匆匆忙忙，小王子说。","t":[103,4513]},{"ar":"ماذا يبحثون عنه؟","zh":"他们在寻找什么？","t":[4513,6092]}]},{"id":"ch22p06","audio":"ch22p06.mp3","sents":[{"ar":"ليس حتى قائد المحرك يعرف ذلك، قال مدير القضبان.","zh":"连火车头上的司机也弄不清楚，”扳道工说。","t":[103,4695]}]},{"id":"ch22p07","audio":"ch22p07.mp3","sents":[{"ar":"ثم مرت قطارتان مضيئة بسرعة هائلة في الاتجاه المعاكس.","zh":"第二列灯火通明的快车在相反方向呼啸而过。","t":[103,5142]}]},{"id":"ch22p08","audio":"ch22p08.mp3","sents":[{"ar":"هل عادوا بالفعل؟ سأل الأمير الصغير.","zh":"他们已经回来了吗？小王子问道。","t":[103,3934]}]},{"id":"ch22p09","audio":"ch22p09.mp3","sents":[{"ar":"هؤلاء ليسوا أولئك، قال القائم على التحويل.","zh":"这不是同一批人，扳道工说。","t":[103,4829]},{"ar":"هذه عملية تبادل.","zh":"这是对开的火车。","t":[4829,6724]}]},{"id":"ch22p10","audio":"ch22p10.mp3","sents":[{"ar":"لم يكنوا راضين عن ما كانوا فيه؟ سأل الأمير الصغير.","zh":"他们对自己的居住地不满意吗？小王子问道。","t":[103,4921]}]},{"id":"ch22p11","audio":"ch22p11.mp3","sents":[{"ar":"لا أحد راضٍ بما هو عليه، قال رجل القاطرة.","zh":"他总觉得自己所在的地方不尽人意，扳道工说。","t":[103,3958]}]},{"id":"ch22p12","audio":"ch22p12.mp3","sents":[{"ar":"سمعوا هدير قطار سريع ثالث مضيء بشدة.","zh":"又有一列灯火通明的快车如雷鸣般轰鸣而过。","t":[103,3813]}]},{"id":"ch22p13","audio":"ch22p13.mp3","sents":[{"ar":"هل هم يتعقبون المسافرين الأوائل؟ قال الأمير الصغير: - بل هم لا يتعقبون شيئًا على الإطلاق. إنهم ينامون هناك، أو يتثاءبون.","zh":"他们是在追赶第一批旅客吗？小王子质问道。","t":[103,12447]}]},{"id":"ch22p14","audio":"ch22p14.mp3","sents":[{"ar":"هم لا يبحثون عن شيء على الإطلاق، قال رجل القاطرة.","zh":"他们根本无所追寻，扳道工说。","t":[103,5289]},{"ar":"إنهم نائمون هناك، أو إذا لم يكونوا نائمين، فإنهم يهمسون.","zh":"他们在车厢里昏昏欲睡，或者若非沉睡，便在打哈欠。","t":[5289,11737]},{"ar":"الأطفال فقط يضغطون بأنوفهم على زجاج النوافذ.","zh":"只有孩子们才把鼻子贴在窗玻璃上。","t":[11737,15764]}]},{"id":"ch22p15","audio":"ch22p15.mp3","sents":[{"ar":"فقط الأطفال يعرفون ما يبحثون عنه، قال الأمير الصغير.","zh":"只有孩子知道他们在寻找什么，小王子说。","t":[103,5618]},{"ar":"هم يهدرون وقتهم على دمية قماش، وتصبح مهمة جدًا بالنسبة لهم، ويبكون إذا ما أُخذت منهم...","zh":"他们把时间浪费在布娃娃身上，那对它们来说变得极其重要；要是有人把它夺走，他们就会哭鼻子……","t":[5618,14316]}]},{"id":"ch22p16","audio":"ch22p16.mp3","sents":[{"ar":"هم محظوظون، قال القائم على التحويل.","zh":"他们是幸运的，扳道工说。","t":[103,3300]}]}]},{"id":"ch23","title_ar":"الفصل الثالث والعشرون","title_en":"Chapter XXIII","title_zh":"第 23 章","paras":[{"id":"ch23p00","audio":"ch23p00.mp3","sents":[{"ar":"صباح الخير، قال الأمير الصغير.","zh":"早上好，小王子说。","t":[103,2997]}]},{"id":"ch23p01","audio":"ch23p01.mp3","sents":[{"ar":"صباح الخير، قال رجل الأعمال.","zh":"早上好，商人说。","t":[103,3934]},{"ar":"هذا كان تاجرًا يبيع حبوبًا مصممة للقضاء على العطش.","zh":"这是一位售卖解渴药丸的商人。","t":[3934,9513]},{"ar":"يجب أن تأخذ قرصًا واحدًا في الأسبوع فقط، وستشعر بعدم الحاجة إلى شرب أي شيء.","zh":"只需每周吞下一颗药丸，便无需再饮任何东西。","t":[9513,16763]}]},{"id":"ch23p02","audio":"ch23p02.mp3","sents":[{"ar":"لماذا تبيع هذه الأقراص يا تاجر؟ سأل الأمير الصغير.","zh":"“你为何卖这种药？”小王子问道。","t":[103,5513]}]},{"id":"ch23p03","audio":"ch23p03.mp3","sents":[{"ar":"لأنها توفر الكثير من الوقت، قال رجل الأعمال.","zh":"“因为这样可以节省大量时间，”商人说。","t":[103,5184]},{"ar":"تم القيام بحسابات من قبل الخبراء.","zh":"专家们已做过计算。","t":[5184,9184]},{"ar":"هذه الحبوب، توفّر لك خمسين ثلاثة دقائق في كل أسبوع.","zh":"每周，这些药丸能为你节省五十三分钟。","t":[9184,14302]}]},{"id":"ch23p04","audio":"ch23p04.mp3","sents":[{"ar":"ماذا أفعل بأول خمسين دقيقة؟","zh":"我该如何利用这五十三分钟？","t":[103,2892]}]},{"id":"ch23p05","audio":"ch23p05.mp3","sents":[{"ar":"ماذا تحب أن تفعل...","zh":"你喜欢做什么……","t":[103,1866]}]},{"id":"ch23p06","audio":"ch23p06.mp3","sents":[{"ar":"حولت، قال للأمير الصغير لنفسه، إن كان لي خمس وثلاثون دقيقة لأقضيها كيفما أريد، سأسرح ببطء نحو عين من الماء العذب...","zh":"“至于我，”小王子自言自语道，“若我有五十三分钟可以随心所欲地度过，我便悠然地向一泓清泉走去。”","t":[103,11313]}]}]},{"id":"ch24","title_ar":"الفصل الرابع والعشرون","title_en":"Chapter XXIV","title_zh":"第 24 章","paras":[{"id":"ch24p00","audio":"ch24p00.mp3","sents":[{"ar":"الأمير الصغير-24 الفصل الرابع والعشرون مضت ثمانية أيام منذ أن تعطلت طائرتي في الصحراء واستمعت إلى قصة التاجر بينما كنت أشرب آخر نقطة من مخزون الماء.","zh":"沙漠中我的飞机失事已第八天，我边听商人的故事边饮尽了我最后一滴水。","t":[103,14642]}]},{"id":"ch24p01","audio":"ch24p01.mp3","sents":[{"ar":"أنا: \"أها، يا الأمير الصغير، ذكرياتك هذه رائعة جدًا، لكن لم أنجح بعد في إصلاح طائري، لم يعد لدي ماء للشرب، وأنا أيضًا سأكون سعيدًا لو استطعت المشي ببطء نحو عين من الماء العذب!\"","zh":"“啊，”我对小王子说，“你的这些回忆真是迷人；不过，我的飞机还没修好，水也喝光了；若能悠闲地走向一汪清泉，我也会很快乐的！”","t":[103,16813]}]},{"id":"ch24p02","audio":"ch24p02.mp3","sents":[{"ar":"صديقي الثعلبـ- قال لي الأمير الصغير...","zh":"我的朋友狐狸——小王子对我说。","t":[103,3577]}]},{"id":"ch24p03","audio":"ch24p03.mp3","sents":[{"ar":"يا صغيري العزيز، هذا لم يعد شأنًا يتعلق بالثعلب!","zh":"亲爱的孩子，这已与狐狸无关了！","t":[103,4550]}]},{"id":"ch24p04","audio":"ch24p04.mp3","sents":[{"ar":"لماذا لا؟","zh":"为何不可？","t":[103,1063]}]},{"id":"ch24p05","audio":"ch24p05.mp3","sents":[{"ar":"لأنني على وشك الموت من العطش...","zh":"因为我即将渴死……","t":[103,2761]}]},{"id":"ch24p06","audio":"ch24p06.mp3","sents":[{"ar":"لم يتبع منطقي، فأجاب: - إنه لمن المفيد أن تكسب صديقًا، حتى لو كان المرء على وشك الموت، فأنا سعيد جدًّا لأنني كسبت الثعلب صديقًا.","zh":"他并未理解我的话，却回答道：","t":[103,12379]}]},{"id":"ch24p07","audio":"ch24p07.mp3","sents":[{"ar":"إنه لمن المفيد أن تكسب صديقًا، حتى لو كان المرء على وشك الموت، فأنا سعيد جدًا لأنني كسبت الثعلب صديقًا.","zh":"有了一位朋友，即便是在命悬一线之际，也是一件好事。","t":[103,10618]},{"ar":"أنا، مثلاً، سعيد جدًا لكوني لدي ثعلب كصديق...","zh":"我很高兴能有一位狐狸作为朋友……","t":[10618,15527]}]},{"id":"ch24p08","audio":"ch24p08.mp3","sents":[{"ar":"لم يجد وسيلة للإحساس بالخطر، قلت لنفسي.","zh":"他无法想象危险的严重。","t":[103,5118]},{"ar":"لم يشعر قط بالجوع أو العطش، كل ما يحتاج إليه هو القليل من نور الشمس...","zh":"他从未尝过饥饿或口渴的滋味。","t":[5118,12211]},{"ar":"يحتاج إلى القليل من ضوء الشمس فقط...","zh":"他只需一点阳光便足矣……","t":[12211,15014]}]},{"id":"ch24p09","audio":"ch24p09.mp3","sents":[{"ar":"لكن نظر إلي ببراءة، وأجاب على فكرتي:","zh":"他凝视着我，对我的想法回应道：","t":[103,3892]}]},{"id":"ch24p10","audio":"ch24p10.mp3","sents":[{"ar":"أنا عطشان جدًا، لنذهب ونبحث عن بئر.","zh":"我也渴了……","t":[103,4671]},{"ar":"دعونا نبحث عن بئر...","zh":"让我们去找一口井……","t":[4671,6461]}]},{"id":"ch24p11","audio":"ch24p11.mp3","sents":[{"ar":"قمت بحركة تنم عن التعب","zh":"我打了个倦怠的手势。","t":[103,2353]},{"ar":"البحث عن بئر في وسط الصحراء العظيمة هو أمر سخيف.","zh":"在沙漠的浩瀚中随意寻找一口井，实在荒谬至极。","t":[2353,7592]},{"ar":"لكن ومع ذلك بدأنا نتحرك.","zh":"然而，我们还是出发了。","t":[7592,10342]}]},{"id":"ch24p12","audio":"ch24p12.mp3","sents":[{"ar":"عندما صبرنا على المشي لعدة ساعات بصمت، غابت الظلام، وبدأت النجوم تظهر.","zh":"我们默默前行数小时，夜幕降临，星辰渐次闪烁。","t":[103,8013]},{"ar":"الشوق جعلني أتألم قليلاً، ونظرت إليهم كأنني في منام.","zh":"干渴让我微微发烧，我望着它们，仿佛置身梦境。","t":[8013,14303]},{"ar":"كلمات الأمير الصغير الأخيرة عادت تتدفق في ذاكرتي كأنها تندفع من البحر:","zh":"小王子的最后几句话如潮水般涌回我的记忆：","t":[14303,20553]}]},{"id":"ch24p13","audio":"ch24p13.mp3","sents":[{"ar":"ثم أنت أيضًا جائع؟ سألتُ.","zh":"你也渴了吗？我追问。","t":[103,3526]}]},{"id":"ch24p14","audio":"ch24p14.mp3","sents":[{"ar":"لكن لم يرد على سؤالي.","zh":"但他并未回答我的问题。","t":[103,3000]},{"ar":"قال لي: - لا شيء.","zh":"他只是对我说：","t":[3000,4671]}]},{"id":"ch24p15","audio":"ch24p15.mp3","sents":[{"ar":"الماء يمكن أن يكون مفيدًا للقلب أيضًا...","zh":"水对心灵亦有益……","t":[103,3313]}]},{"id":"ch24p16","audio":"ch24p16.mp3","sents":[{"ar":"لم أفهم جوابه، لكنني لبثت صامتًا.","zh":"我不解其意，却缄口不言。","t":[103,4355]},{"ar":"أعلم جيدًا أنّه من المستحيل إجراء استجواب له.","zh":"我深知无法对他进行质询。","t":[4355,8132]}]},{"id":"ch24p17","audio":"ch24p17.mp3","sents":[{"ar":"هو متعب جدًا","zh":"他疲惫不堪。","t":[103,1379]},{"ar":"استلقي.","zh":"他坐了下来。","t":[1379,3132]},{"ar":"جلست بجانبه","zh":"我坐在他身边。","t":[3132,4408]},{"ar":"إن النجوم جميلة بسبب زهرة لا يمكن للمرء أن يراها.","zh":"星星之所以美丽，是因为有一朵看不见的花。","t":[4408,9026]}]},{"id":"ch24p18","audio":"ch24p18.mp3","sents":[{"ar":"أجبت: \"نعم، هذا صحيح.\" وبلا قول أي شيء آخر، نظرت عبر جبال الرمال التي تمددت أمامنا في ضوء القمر.","zh":"我答道：“没错，正是如此。”然后默默无言，凝视着月光下绵延的沙丘。","t":[103,9813]}]},{"id":"ch24p19","audio":"ch24p19.mp3","sents":[{"ar":"الصحراء جميلة، قال الأمير الصغير.","zh":"沙漠真美，小王子补充道。","t":[103,3155]}]},{"id":"ch24p20","audio":"ch24p20.mp3","sents":[{"ar":"وكان ذلك صحيحًا","zh":"这倒是真的。","t":[103,1603]},{"ar":"أحببت الصحراء دائمًا.","zh":"沙漠，我始终钟爱。","t":[1603,4355]},{"ar":"يستقر على تل رمال في الصحراء، لا يرى شيئًا ولا يسمع شيئًا.","zh":"坐在沙漠沙丘上，无所见，无所闻。","t":[4355,10579]},{"ar":"في صمت شيء ينبض ويلمع...","zh":"寂静中，有何物跳动，闪烁……","t":[10579,12671]}]},{"id":"ch24p21","audio":"ch24p21.mp3","sents":[{"ar":"ما يجعل الصحراء جميلة هو أنّها تخفي بئرًا، في مكان ما...","zh":"沙漠之所以美丽，是因为它某个角落隐藏着一口井。","t":[103,5023]}]},{"id":"ch24p22","audio":"ch24p22.mp3","sents":[{"ar":"أدهشني فجأة فهمي لتلك الإشعاع الغامض للرمال.","zh":"我猛然领悟到沙漠那神秘闪烁的奥秘。","t":[103,4974]},{"ar":"عندما كنت صبيًا، سكنت في بيت قديم جدًا وقد علمنا من أسطورة أنه يوجد كنز مدفون هناك، وبالتأكيد لم يكتشفه أحد، ربما لن يبحث عنه أحد، ولكنه يضفي سحرًا على المنزل.","zh":"我年幼时曾住在一座古老的大屋中，传说那里埋藏着一笔宝藏。","t":[4974,21592]},{"ar":"بالطبع، لم يعرف أحد كيف يجدها؛ ربما لم يبحث أحد عنها حتى.","zh":"确实，无人知晓如何找到它；或许无人曾试图寻找过。","t":[21592,28434]},{"ar":"لكن ألهمت المنزل سحرًا.","zh":"但那座房子被施了魔法。","t":[28434,31526]},{"ar":"منزلي يخفي سرًا في أعماقه...","zh":"我的家在心底深处藏着一个秘密……","t":[31526,34000]}]},{"id":"ch24p23","audio":"ch24p23.mp3","sents":[{"ar":"نعم، قلت للأمير الصغير.","zh":"“是的，”我对小王子说。","t":[103,3500]},{"ar":"البيت والنجوم والصحراء – ما يمنحها جمالها هو شيء غير مرئي!","zh":"房子、星星、沙漠——赋予它们美丽的是肉眼无法看见的东西。","t":[3500,8736]}]},{"id":"ch24p24","audio":"ch24p24.mp3","sents":[{"ar":"أنا سعيد، قال، أنت توافق على ثعلبي.","zh":"他笑着说：“很高兴，你赞同我的狐狸。”","t":[103,4024]}]},{"id":"ch24p25","audio":"ch24p25.mp3","sents":[{"ar":"الأمير الصغير انام، أخذه في يدي وبدأت المشي مجدداً.","zh":"小王子入睡，我把他抱在怀里，再次踏上了旅程。","t":[103,6158]},{"ar":"شعرت بحركة في قلبي، واهتزت روحي.","zh":"内心深受触动，波澜起伏。","t":[6158,10526]},{"ar":"يبدو لي أنني أحمل كنزاً هشاً جدًا.","zh":"我仿佛抱着一件极其脆弱的珍宝。","t":[10526,14592]},{"ar":"في هذا الأرض لم يكن هناك شيء أكثر هشاشة من هذا.","zh":"在这片大地上，似乎再无比他更脆弱之物。","t":[14592,19697]},{"ar":"في ضوء القمر نظرت إلى جبينه الفاتح، إلى عينيه المغلقة، إلى شعره الذي يهتز في الريح، وقلت لنفسي: \"ما أراه هنا ليس إلا قشر.\"","zh":"在这月光下，我凝视着他苍白的额头、紧闭的双眼、随风轻颤的鬈发，心中自语道：“我所看到的，不过是一具躯壳。”","t":[19697,31408]},{"ar":"ما هو الأهم هو غير المرئي...","zh":"最重要的，是肉眼看不见的……","t":[31408,33672]}]},{"id":"ch24p26","audio":"ch24p26.mp3","sents":[{"ar":"في شفتيه التي تفتحت قليلاً بابتسامة مشككة، قلت لنفسي مرة أخرى: \"ما يثيرني بشأن هذا الأمير الصغير النائم هنا هو ولاءه للوردة، صورة وردة تلمع في كيانه كشعلة المصباح، حتى أثناء نومه...\" وشعرت بأنه أكثر هشاشة.","zh":"在这半张的嘴唇上，带着一丝怀疑的微笑微微张开，我再次对自己说：“打动我的，正是这位在此沉睡的小王子对一朵花的忠诚——玫瑰的影像在他整个生命中如灯焰般闪耀，即便在他入睡时……”我愈发觉得他显得更加脆弱。","t":[103,21447]},{"ar":"شعرت بحاجة لحمايته، كما لو كان هو نفسه نار قد تُطفأ ببخار قليل من الريح...","zh":"我感到需要保护他，仿佛他自身就是一丝微风就能吹灭的火焰……","t":[21447,28381]}]},{"id":"ch24p27","audio":"ch24p27.mp3","sents":[{"ar":"وعندما اجتزت السير، وجدت الماء، عند الفجر.","zh":"曙光初露，我找到了那口井。","t":[103,4115]}]}]},{"id":"ch25","title_ar":"الفصل الخامس والعشرون","title_en":"Chapter XXV","title_zh":"第 25 章","paras":[{"id":"ch25p00","audio":"ch25p00.mp3","sents":[{"ar":"الناس يبدأون رحلتهم في قطارات سريعة دون أن يعرفوا ما يبحثون عنه.","zh":"人们踏上旅程，乘坐快车，却不知他们在寻找什么。","t":[103,6776]},{"ar":"ثم يسرعون ويشعرون بالحماس ويحلقون حول أنفسهم...","zh":"他们忙乱地四处奔走，激动不已，团团打转……","t":[6776,11394]}]},{"id":"ch25p01","audio":"ch25p01.mp3","sents":[{"ar":"إن هذا العناء لا يستحق العناء...","zh":"他接着说：“这番忙碌实在不值得。”","t":[103,2511]}]},{"id":"ch25p02","audio":"ch25p02.mp3","sents":[{"ar":"البئر التي وصلنا إليها لم تكن مثل آبار الصحراء العادية.","zh":"我们找到的井与撒哈拉沙漠的井大不相同。","t":[103,5539]},{"ar":"حفر الصحراء هي مجرد ثقوب مفتوحة في الرمل.","zh":"撒哈拉之井，不过是沙中浅洞。","t":[5539,10105]},{"ar":"هذا الديك كان كحفرة في قرية","zh":"这口井宛如村中的井。","t":[10105,12671]},{"ar":"لم يكن هناك قرية هنا، وقلت لنفسي إنني أرى الأشياء في الحلم...","zh":"然而此处并无村落，我疑心自己是在梦中。","t":[12671,18040]}]},{"id":"ch25p03","audio":"ch25p03.mp3","sents":[{"ar":"هذا غريب، قلت للأمير الصغير.","zh":"这真奇怪，我对小王子说。","t":[103,3908]},{"ar":"كل شيء جاهز للاستخدام: الحبل، الدلو، الحبل…","zh":"一切用具俱备：辘轳、水桶、绳子……","t":[3908,8776]}]},{"id":"ch25p04","audio":"ch25p04.mp3","sents":[{"ar":"ضحك، لمس الحبل، ووضع البكرة في العمل.","zh":"他笑着，轻触绳索，启动了辘轳。","t":[103,4961]},{"ar":"وعانق البكرة، كما لو كانت صديقة قديمة، وأخذت معي قطعة من السكر، وأكلتها ببطء، وأنا أستعيد ذكرياتي.","zh":"辘轳哀鸣，宛如久被遗忘的老风信鸡。","t":[4961,15184]}]},{"id":"ch25p05","audio":"ch25p05.mp3","sents":[{"ar":"هل تسمع؟ قال الأمير الصغير.","zh":"你听，小王子说。","t":[103,4382]},{"ar":"لقد أيقظنا البئر وهي الآن تغني...","zh":"我们唤醒了这口井，它正在歌唱……","t":[4382,7264]}]},{"id":"ch25p06","audio":"ch25p06.mp3","sents":[{"ar":"لم أرد أن يصبح منهكًا بسبب السلك.","zh":"我不愿他因拉绳而劳累。","t":[103,3090]}]},{"id":"ch25p07","audio":"ch25p07.mp3","sents":[{"ar":"اترك الأمر لي، قال الأب الصغير.","zh":"让我来吧。","t":[103,3868]},{"ar":"هذا الثقيل جدًا عليك.","zh":"这份工作对你来说太沉重了。","t":[3868,5684]}]},{"id":"ch25p08","audio":"ch25p08.mp3","sents":[{"ar":"أرفعت الحوض ببطء إلى حافة البئر ووضعته هناك – سعيدًا، متعبًا كما كنت، من إجازتي.","zh":"我缓缓将水桶提到井边，放置其间——尽管疲惫，但为我的成就而喜悦。","t":[103,8750]},{"ar":"النغمة الصوتية للسحاب كانت لا تزال في أذني، ورأيت ضوء الشمس يتلألأ في الماء الذي يزال يتذبذب.","zh":"辘轳之歌仍在耳畔回响，我看见阳光在静止摇曳的水面闪烁。","t":[8750,17145]}]},{"id":"ch25p09","audio":"ch25p09.mp3","sents":[{"ar":"أنا جائع لهذه الماء، قال الأمير الصغير.","zh":"我渴望的就是这样的水，小王子说。","t":[103,4500]},{"ar":"أعطني شيئًا منها لأشرب...","zh":"让我喝上几口……","t":[4500,6566]}]},{"id":"ch25p10","audio":"ch25p10.mp3","sents":[{"ar":"فهمت ما كان يبحث عنه.","zh":"我明白了他在寻找什么。","t":[103,2155]}]},{"id":"ch25p11","audio":"ch25p11.mp3","sents":[{"ar":"رفعت الدلو إلى شفتيه","zh":"我举桶至他唇边。","t":[103,2050]},{"ar":"شرب، وأغلق عينيه.","zh":"他闭目啜饮。","t":[2050,5066]},{"ar":"كأنها حلوى خاصة بالحفلة.","zh":"宛如节日佳肴般甘甜。","t":[5066,8263]},{"ar":"هذه الماء كانت شيء مختلف تمامًا عن الغذاء العادي، إنها وليدة السير تحت النجوم وغناء البكرة وجهد ذراعي، إنها مفيدة للقلب، مثل هدية.","zh":"这水确是不同于寻常的滋养。","t":[8263,21513]},{"ar":"أن نعمة ماءه ولدت من المشي تحت النجوم، أغنية العجلة، وحراك يدي.","zh":"星光下的漫步、辘轳的歌声与我的臂力，孕育了这水的甘甜。","t":[21513,28882]},{"ar":"كأنه هدية، دفعت القلب إلى الراحة.","zh":"宛如礼物，温暖了心房。","t":[28882,33184]},{"ar":"عندما كنت صبيًا صغيرًا، كانت أضواء شجرة الميلاد، وموسيقى قداس منتصف الليل، وطيبة الوجوه الباسمة، تكون توهج هدية الميلاد التي أتلقاها.","zh":"儿时，圣诞树上的灯光、子夜弥撒的乐音、微笑脸庞的温柔，构成了我所收到的礼物的光辉。","t":[33184,45815]}]},{"id":"ch25p12","audio":"ch25p12.mp3","sents":[{"ar":"الرجال الذين يعيشون حيث أنت، يقومون بزراعة خمسة آلاف وردة في نفس الحديقة ويجدهم لا يجدون ما يبحثون عنه فيها.","zh":"“你们那里的男人，”小王子说，“在同一花园里培育了五千朵玫瑰——却在那里找不到他们所寻找的东西。”","t":[103,10366]}]},{"id":"ch25p13","audio":"ch25p13.mp3","sents":[{"ar":"لا يجدونها، أجبت.","zh":"他们并未找到。","t":[103,2182]}]},{"id":"ch25p14","audio":"ch25p14.mp3","sents":[{"ar":"في وردة واحدة أو في قليل من الماء يمكن أن يجدوا ما يبحثون عنه.","zh":"在一朵玫瑰或一滴水中，他们所寻之物便可觅得。","t":[103,5550]}]},{"id":"ch25p15","audio":"ch25p15.mp3","sents":[{"ar":"نعم، هذا صحيح، قلت.","zh":"是的，这确实如此。","t":[103,2642]}]},{"id":"ch25p16","audio":"ch25p16.mp3","sents":[{"ar":"ثم أضاف الأمير الصغير: - إن الأعين عمياء؛ على المرء أن ينظر من خلال القلب.","zh":"小王子又补充道：","t":[103,6379]}]},{"id":"ch25p17","audio":"ch25p17.mp3","sents":[{"ar":"إن الأعين عمياء؛ على المرء أن ينظر من خلال القلب.","zh":"但眼睛是盲的。","t":[103,5237]},{"ar":"على المرء أن ينظر من خلال القلب...","zh":"必须用心去看……","t":[5237,7763]}]},{"id":"ch25p18","audio":"ch25p18.mp3","sents":[{"ar":"لقد شربت الماء.","zh":"我饮了这水。","t":[103,2461]},{"ar":"تنفست بسهولة.","zh":"呼吸顺畅了。","t":[2461,4868]},{"ar":"في وقت الشروق يكون الرمل لون العسل.","zh":"日出时分，沙地泛着蜜色。","t":[4868,8645]},{"ar":"وذلك لون العسل كان يجعلني سعيدًا أيضًا.","zh":"这蜜色也让我心情愉悦。","t":[8645,13250]},{"ar":"ماذا جعلني أشعر بهذا الحزن؟","zh":"那又是什么，让我心生哀愁？","t":[13250,15829]}]},{"id":"ch25p19","audio":"ch25p19.mp3","sents":[{"ar":"عليك أن تحافظ على وعدك، قال الأمير الصغير، بهدوء، وهو يجلس بجانبي مرة أخرى.","zh":"你务必遵守诺言，小王子轻声说，再次坐到我身边。","t":[103,7840]}]},{"id":"ch25p20","audio":"ch25p20.mp3","sents":[{"ar":"ما الوعده؟","zh":"什么诺言？","t":[103,971]}]},{"id":"ch25p21","audio":"ch25p21.mp3","sents":[{"ar":"تعرفـ- أرسم لخروفى قناعًا...","zh":"你知道——给我的绵羊画一个口罩……","t":[103,4079]},{"ar":"أنا مسؤول عن هذه الزهرة...","zh":"我负责这朵花……","t":[4079,6106]}]},{"id":"ch25p22","audio":"ch25p22.mp3","sents":[{"ar":"أخرجت رسوماتي الأولية من جيبي.","zh":"我从口袋里掏出草图。","t":[103,3934]},{"ar":"الأمير الصغير نظر إليهم، ضحك وهو يقول:","zh":"小王子打量了一番，笑着说：","t":[3934,7908]}]},{"id":"ch25p23","audio":"ch25p23.mp3","sents":[{"ar":"أمير الصغير: ووردتك الباوباب تبدو كأنها مثل الملفوف قليلاً.","zh":"你的猴面包树——它们有点像卷心菜。","t":[103,5537]}]},{"id":"ch25p24","audio":"ch25p24.mp3","sents":[{"ar":"أوه!","zh":"哦！","t":[103,629]}]},{"id":"ch25p25","audio":"ch25p25.mp3","sents":[{"ar":"كنت فخورًا جدًا بأشجاري الباوباب!","zh":"我对自己画的猴面包树颇为自豪！","t":[103,2708]}]},{"id":"ch25p26","audio":"ch25p26.mp3","sents":[{"ar":"هذا الثعلب، أذنيه تشبه القرون قليلاً، وهي طويلة جدًا.","zh":"你的狐狸——它的耳朵有点像角，而且太长了。","t":[103,5681]}]},{"id":"ch25p27","audio":"ch25p27.mp3","sents":[{"ar":"وهذا ما يحدث عندما يصبح المرء أليفًا.","zh":"他又笑了。","t":[103,3405]}]},{"id":"ch25p28","audio":"ch25p28.mp3","sents":[{"ar":"ليس أنت عادل، الأمير الصغير، قلت.","zh":"你这不公平，小王子，我说。","t":[103,4553]},{"ar":"أنا أعرف كيف أرسم الثعابين من الخارج والثعابين من الداخل فقط.","zh":"我只懂得画外部的蟒蛇和内部的蟒蛇。","t":[4553,9697]}]},{"id":"ch25p29","audio":"ch25p29.mp3","sents":[{"ar":"أوه، هذا كاف، فالأطفال يفهمون.","zh":"哦，那没关系，他说，孩子们会理解的。","t":[103,3511]}]},{"id":"ch25p30","audio":"ch25p30.mp3","sents":[{"ar":"ثم رسمت رسوماً بفرشاة الرصاص، وأخذت نفسًا عميقًا عند رؤيتها وهو يضحك وهو يقول: إن أشجار الباباوباب التي رسمتها تشبه الملفوف قليلًا. أوه. (وقد كنت فخورًا جدًا بأشجاري الباباوباب)! الثعلب، أذنانه... تشبهان القرون قليلًا، وهما طويلتان (ثم ضحك ثانية). لست عادلًا أيها الأمير الصغير، تذكر أن بإمكاني فقط رسم الحيات العاصرة من الخارج والحيات العاصرة من الداخل. قال لي: أوه، هذا كاف، فالأطفال يفهمون. وهكذا رسمت كمامة بقلم رصاص، وقد اعتصر قلبي حين أعطيته إياها. لديك خطط أجهلها. لكنه لم يجب، وبدلًا من ذلك، قال لي: هل تعلم... إن هبوطي إلى الأرض ستكون ذكراه السنوية غدًا. (ثم أضاف بعد صمت قصير) لقد هبطت إلى مكان قريب جدًا من هنا. ثم تورد وجهه، ومرة أخرى، ومن دون أن أفهم السبب، ساورني شعور غريب بالأسى، ثم خطر سؤال في بالي: إذًا لم يكن مجرد صدفة أن تتجول بمفردك على بعد ألف ميل من أي سكن بشري عندما التقيتك في ذلك الصباح منذ ثمانية أيام؟ هل كنت عائدًا إلى المكان حيث هبطت؟. تورد وجه الأمير الصغير ثانية، ثم تابعت قائلًا بشيء من التردد: ربما بسبب الذكرى السنوية؟ تورد وجه الأمير الصغير مرة ثالثة. لم يجب عن أسئلتي قط، لكن عندما تتورد وجنتا المرء، فذلك يعني نعم، أليس كذلك؟ قلت له: يا إلهي! أشعر بشيء من الخوف. أجاب مطمئنًا: الآن عليك أن تعمل، عليك أن تعود إلى محركك. سأنتظرك هنا، عد مساء الغد. لكنني لم أشعر بالاطمئنان. تذكرت الثعلب. إن المرء يجازف بالبكاء قليلًا إذا ما سمح لنفسه أن يصبح أليفًا.","zh":"于是，我画了一张绵羊口罩的铅笔草图。","t":[103,146105]},{"ar":"قلبي تفتت عند تسليمه إياه.","zh":"我的心在交付给他时撕裂了。","t":[146105,148606]}]},{"id":"ch25p31","audio":"ch25p31.mp3","sents":[{"ar":"لديك خطط لا أعلمها.","zh":"你有所图，我却不晓。","t":[103,2195]}]},{"id":"ch25p32","audio":"ch25p32.mp3","sents":[{"ar":"لكن لم يرد عليّ.","zh":"但他没有回答我。","t":[103,2605]},{"ar":"قال لي: بدلاً من ذلك:","zh":"他转而对我说：","t":[2605,4829]}]},{"id":"ch25p33","audio":"ch25p33.mp3","sents":[{"ar":"أتعلمـ إنني هبطت إلى الأرض...","zh":"你知道——我降临到地球……","t":[103,3382]},{"ar":"غدًا سيكون عيد ميلاده.","zh":"明天就是它的周年纪念日。","t":[3382,5474]}]},{"id":"ch25p34","audio":"ch25p34.mp3","sents":[{"ar":"ثم، بعد صمت، استأنف:","zh":"然后，沉默片刻，他又继续说道：","t":[103,2971]}]},{"id":"ch25p35","audio":"ch25p35.mp3","sents":[{"ar":"جئت منخفضًا قريبًا جدًا من هنا","zh":"我降落得离这里很近。","t":[103,2800]}]},{"id":"ch25p36","audio":"ch25p36.mp3","sents":[{"ar":"ووجهه قد ألون بالحمرة.","zh":"他的脸泛起了红晕。","t":[103,2366]}]},{"id":"ch25p37","audio":"ch25p37.mp3","sents":[{"ar":"ومرة أخرى، دون فهم السبب، شعرت بغربة من الحزن.","zh":"又不知为何，我心中涌起一股莫名的哀愁。","t":[103,6079]},{"ar":"سؤال واحد، ولكن، جاء لي في ذهني:","zh":"然而，一个问题浮现在我的脑海中：","t":[6079,9869]}]},{"id":"ch25p38","audio":"ch25p38.mp3","sents":[{"ar":"إذًا لم يكن مجرد صدفة أن تتجول بمفردك على بعد ألف ميل من أي سكن بشري عندما التقيتك في ذلك الصباح منذ ثمانية أيام؟ هل كنت عائدًا إلى المكان الذي هبطت فيه؟","zh":"那天早上，我们初次相遇——一周前——你独自一人，在这远离人烟的沙漠中漫步，这并非偶然？","t":[103,15737]},{"ar":"كنت أتجه خلفك إلى مكان هبوطك؟","zh":"你正背对着你的降落点走去？","t":[15737,18763]}]},{"id":"ch25p39","audio":"ch25p39.mp3","sents":[{"ar":"الأمير الصغير ألون في وجهه ثانية.","zh":"小王子再次涨红了脸。","t":[103,3103]}]},{"id":"ch25p40","audio":"ch25p40.mp3","sents":[{"ar":"وأضفت، مع بعض التردد:","zh":"我带着几分犹豫，补充道：","t":[103,2458]}]},{"id":"ch25p41","audio":"ch25p41.mp3","sents":[{"ar":"ربما لأنه عيد ميلاد؟","zh":"或许是因为周年纪念吧？","t":[103,2208]}]},{"id":"ch25p42","audio":"ch25p42.mp3","sents":[{"ar":"الأمير الصغير ألون وجهه ثانية.","zh":"小王子脸颊再次泛红。","t":[103,3868]},{"ar":"لم يكن يجيب على الأسئلة... لكن عندما يتحمر الوجه، أليس ذلك يعني \"نعم\"؟","zh":"他从不回答问题——但一个人脸红，难道不是就意味着“是”吗？","t":[3868,11500]}]},{"id":"ch25p43","audio":"ch25p43.mp3","sents":[{"ar":"أه، قلت له، أنا قليل الخوف--","zh":"“啊，”我对他说，“我有点害怕——”","t":[103,3997]}]},{"id":"ch25p44","audio":"ch25p44.mp3","sents":[{"ar":"لكنّه أوقفتني.","zh":"他打断了我。","t":[103,1800]}]},{"id":"ch25p45","audio":"ch25p45.mp3","sents":[{"ar":"الآن يجب عليك العمل.","zh":"现在你必须工作了。","t":[103,3039]},{"ar":"يجب أن تعود إلى محركك.","zh":"你必须回到你的引擎旁。","t":[3039,6224]},{"ar":"سأنتظرك هنا، عد مساء الغد.","zh":"我在这儿等你。","t":[6224,9974]},{"ar":"تعود غدًا مساءً...","zh":"明天晚上再来……","t":[9974,11552]}]},{"id":"ch25p46","audio":"ch25p46.mp3","sents":[{"ar":"لم أكن راضياً عن ذلك.","zh":"但我并未感到安心。","t":[103,2974]},{"ar":"تذكرت الثعلب.","zh":"我记起了那只狐狸。","t":[2974,5237]},{"ar":"إن المرء يجازف بالبكاء قليلًا إذا ما سمح لنفسه أن يصبح أليفًا...","zh":"若有人让自己被驯服，难免会流下几滴泪……","t":[5237,10763]}]}]},{"id":"ch26","title_ar":"الفصل السادس والعشرون","title_en":"Chapter XXVI","title_zh":"第 26 章","paras":[{"id":"ch26p00","audio":"ch26p00.mp3","sents":[{"ar":"بجانب البئر، كانت هنالك بقايا جدار حجري قديم.","zh":"井边，一堵古老的石墙残垣断壁。","t":[103,5539]},{"ar":"عندما عدت من عملي في المساء التالي، رأيت من بعض المسافة الأمير الصغير جالسًا على قمة الجدار، وقدميه تتدلى.","zh":"当晚我下班归来，远远望见小王子坐在断壁之上，双脚悬空。","t":[5539,15579]},{"ar":"سمعتُ يقول:","zh":"我听见他这么说：","t":[15579,16921]}]},{"id":"ch26p01","audio":"ch26p01.mp3","sents":[{"ar":"ثم لا تتذكر.","zh":"那么，你不记得了。","t":[103,2474]},{"ar":"هذا ليس المكان الصحيح...","zh":"这不是确切的地方。","t":[2474,4474]}]},{"id":"ch26p02","audio":"ch26p02.mp3","sents":[{"ar":"صوت آخر لابد أن يكون قد أجاب، لأنه رد عليه:","zh":"另一个声音定然回应了他，因为他对此反驳道：","t":[103,4747]}]},{"id":"ch26p03","audio":"ch26p03.mp3","sents":[{"ar":"نعم، نعم!","zh":"没错！没错！","t":[103,932]},{"ar":"هذا اليوم هو، لكن هذا المكان ليس المناسب.","zh":"正是这一天，但不是这个地方。","t":[932,6514]}]},{"id":"ch26p04","audio":"ch26p04.mp3","sents":[{"ar":"تابعت مشياً باتجاه الجدار","zh":"我继续朝墙走去。","t":[103,2103]},{"ar":"لم أر أي أحد ولا سمعت أحدًا.","zh":"我从未见过或听到过任何人。","t":[2103,5737]},{"ar":"الأمير الصغير رد مرة أخرى:","zh":"小王子却再次反驳道：","t":[5737,8250]}]},{"id":"ch26p05","audio":"ch26p05.mp3","sents":[{"ar":"صحيح.","zh":"没错。","t":[103,1763]},{"ar":"ستشاهدين أين تبدأ آثار قدمي في الرمال","zh":"你将看到我的足迹在沙地上起始之处。","t":[1763,5039]},{"ar":"ليس لديك شيء تفعله سوى أن تنتظرني هناك.","zh":"你只需在那里等我。","t":[5039,9737]},{"ar":"سأكون هناك الليلة.","zh":"今夜我会在那儿等你。","t":[9737,11447]}]},{"id":"ch26p06","audio":"ch26p06.mp3","sents":[{"ar":"كنت على بعد مئة متر فقط من الجدار ومع ذلك لم أر شيئًا.","zh":"我离墙仅有二十米，却仍一无所见。","t":[103,5103]}]},{"id":"ch26p07","audio":"ch26p07.mp3","sents":[{"ar":"بعد صمت قليل، قال الأمير الصغير: - هل السم لديك جيد؟ هل أنت متأكدة من أنه لن يجعلني أعاني وقتًا طويلًا جدًّا؟","zh":"沉默片刻后，小王子又开口了。","t":[103,10987]}]},{"id":"ch26p08","audio":"ch26p08.mp3","sents":[{"ar":"هل لديك سُم جيد؟ هل أنت متأكدة من أنه لن يجعلني أعاني وقتًا طويلاً جدًا؟","zh":"你有毒药吗？","t":[103,8579]},{"ar":"هل أنت متأكدة من أنه لن يجعلني أعاني وقتًا طويلاً جدًا؟","zh":"你能否肯定不会让我遭受太久痛苦？","t":[8579,13527]}]},{"id":"ch26p09","audio":"ch26p09.mp3","sents":[{"ar":"توقفت في مكاني، قلبي قد تمزق؛ ومع ذلك لم أستطع أن أفهم.","zh":"我止步不前，心碎如裂；然而我依旧不解。","t":[103,5721]}]},{"id":"ch26p10","audio":"ch26p10.mp3","sents":[{"ar":"الآن اذهب بعيدًا، قال الأمير الصغير.","zh":"现在你走吧，小王子说。","t":[103,4289]},{"ar":"أريد أن أنزل من الجدار","zh":"我想要从墙上下来。","t":[4289,6368]}]},{"id":"ch26p11","audio":"ch26p11.mp3","sents":[{"ar":"أنخفضت النظر إلى قدم الجدار، ثم قفزت إلى الهواء!","zh":"我低头看向墙脚——然后纵身跃起。","t":[103,5539]},{"ar":"ثعبان صفراء يرفع رأسه نحو الأمير الصغير، هذا الثعبان يمكن أن ينقضي على حياتك في ثوانٍ ثلاثين فقط.","zh":"黄蛇昂首面对小王子，这种蛇只需三十秒就能夺走人的生命。","t":[5539,15289]},{"ar":"كنت أستخرج المسدس من جيبي وأتراجع خطوة سريعة.","zh":"我掏枪入袋，同时快步后退。","t":[15289,20763]},{"ar":"لكن، عند الضجيج الذي أنا أحدثه، استلقي الثعبان بسهولة عبر الرمال كأنه رذاذ من نافورة تُسقط، وابتعد بلا عجلة بين الأحجار، وأصدر صوتاً معدنياً خفيفاً.","zh":"但在我制造的噪音中，那条蛇像喷泉般垂死的喷泉一样，在沙地上轻松地流淌，不慌不忙地消失在石头之间，发出轻微的金属声响。","t":[20763,35224]}]},{"id":"ch26p12","audio":"ch26p12.mp3","sents":[{"ar":"لقد وصلت إلى الجدار في الوقت المناسب لألتقط أميري الصغير بذراعي، وقد استحال وجهه أبيض كالثلج.","zh":"我及时赶到，将他小小的身躯紧紧抱在怀中，他的脸庞白得如雪。","t":[103,8037]}]},{"id":"ch26p13","audio":"ch26p13.mp3","sents":[{"ar":"ماذا يعني ذلك؟ أتمنى أن تعرف.","zh":"我追问：“这是什么意思？”","t":[103,4816]},{"ar":"لماذا تتحدث إلى الثعابين؟","zh":"你为何与蛇交谈？","t":[4816,7131]}]},{"id":"ch26p14","audio":"ch26p14.mp3","sents":[{"ar":"لقد أزلت عنقه الوشاح الذهبي الذي كان يرتديه دائمًا.","zh":"我解开了他始终佩戴的金色围巾。","t":[103,5855]},{"ar":"أزفرت على جبينه، وأعطيته بعض الماء للشرب.","zh":"我湿润了他的太阳穴，并给他喝了一些水。","t":[5855,10711]},{"ar":"لم أعد أجرؤ على سؤاله أي أسئلة أخرى.","zh":"我再也不敢问他更多问题了。","t":[10711,15197]},{"ar":"نظر بجدية إلي ووضع ذراعيه حول عنقي.","zh":"他严肃地望着我，将双臂环抱住我的脖子。","t":[15197,19974]},{"ar":"قلبي ينبض كقلب طائر يُطلق عليه الرصاص...","zh":"他的心跳如中枪濒死的小鸟般急促。","t":[19974,23552]}]},{"id":"ch26p15","audio":"ch26p15.mp3","sents":[{"ar":"أنا سعيد بأنك عثرت على مشكلة محركك، قال.","zh":"他高兴地说：“你找到了飞机的问题，我很欣慰。”","t":[103,5487]},{"ar":"الآن يمكنك العودة إلى بيتكـ","zh":"现在你可以回家了——","t":[5487,8105]}]},{"id":"ch26p16","audio":"ch26p16.mp3","sents":[{"ar":"كيف تعرف عن هذا؟","zh":"你怎会知道那事？","t":[103,1682]}]},{"id":"ch26p17","audio":"ch26p17.mp3","sents":[{"ar":"كنت أحتاج إلى إخباره بأن عملي قد نجح، فوق كل ما طلبته من نفسي.","zh":"我正要告诉他，我的工作已经成功，超出了我敢想象的任何程度。","t":[103,6050]}]},{"id":"ch26p18","audio":"ch26p18.mp3","sents":[{"ar":"لم يجيب عن سؤالي، ولكن أضاف: \"أنا أيضًا سأعود إلى وطني اليوم...\"","zh":"他未对我的问题作答，却补充道：“我也要回家去了……”","t":[103,6169]}]},{"id":"ch26p19","audio":"ch26p19.mp3","sents":[{"ar":"ثم، بأسى-- \"إنه أبعد بكثير...","zh":"那时，他黯然神伤地说：“那还要远得多……”","t":[103,5342]},{"ar":"هذا أكثر صعوبة...","zh":"这还更加艰难……","t":[5342,6961]}]},{"id":"ch26p20","audio":"ch26p20.mp3","sents":[{"ar":"أدركت بوضوح أن شيءً استثنائياً يحدث.","zh":"我明白，这绝非寻常之事。","t":[103,4447]},{"ar":"كنت أحمله بقبضتي كأنه طفل صغير؛ ومع ذلك، يبدو لي أنه كان يسير باتجاه الهاوية لا أستطيع أن أوقفه...","zh":"我紧紧地抱住他，如同抱住一个小孩；然而，我感觉他正一头冲向深渊，而我却无法阻止他……","t":[4447,13869]}]},{"id":"ch26p21","audio":"ch26p21.mp3","sents":[{"ar":"نظرته جدية كأنه فقد نفسه في مكان بعيد.","zh":"他的目光非常严肃，仿佛迷失在遥远之地。","t":[103,4524]}]},{"id":"ch26p22","audio":"ch26p22.mp3","sents":[{"ar":"لدي خروفك، ولدي الصندوق من أجل الخروف، كما لدي الكمامة أيضًا.","zh":"我有你的绵羊。","t":[103,7263]},{"ar":"لدي صندوق الغنم.","zh":"我有羊的箱子。","t":[7263,9842]},{"ar":"لدي القناع...","zh":"我还有它的口罩……","t":[9842,11066]}]},{"id":"ch26p23","audio":"ch26p23.mp3","sents":[{"ar":"وهذا ابتسامة حزينة غمرت وجهه.","zh":"他凄然一笑。","t":[103,3103]}]},{"id":"ch26p24","audio":"ch26p24.mp3","sents":[{"ar":"انتظرت وقتًا طويلاً.","zh":"我等待了许久。","t":[103,2908]},{"ar":"كان يتعافى تدريجيًا.","zh":"他渐渐恢复了生机。","t":[2908,4789]}]},{"id":"ch26p25","audio":"ch26p25.mp3","sents":[{"ar":"يا صغيري العزيز، قلت له، أنت خائف...","zh":"亲爱的孩子，我说道，“你害怕了……”","t":[103,3800]}]},{"id":"ch26p26","audio":"ch26p26.mp3","sents":[{"ar":"لم يكن هناك شك في أن الأمير الصغير كان خائفًا.","zh":"他害怕，这毫无疑问。","t":[103,4974]},{"ar":"لكن ابتسم بابتسامة خفيفة.","zh":"他轻轻地笑了。","t":[4974,7645]}]},{"id":"ch26p27","audio":"ch26p27.mp3","sents":[{"ar":"سأكون خائفاً جدًا الليلة...","zh":"今夜我会更加害怕……","t":[103,2392]}]},{"id":"ch26p28","audio":"ch26p28.mp3","sents":[{"ar":"أعادتني شعور لا يمكن إصلاحه إلى تجمد.","zh":"我又一次被那无法挽回的感觉冻结了。","t":[103,4842]},{"ar":"لا أستطيع تحمل فكرة عدم سماع ضحكك مرة أخرى يا أميري الصغير.","zh":"我无法忍受再想永远听不到那笑声。","t":[4842,11355]},{"ar":"مثل نبع ماء عذب في الصحراء.","zh":"沙漠中的一股清泉。","t":[11355,13737]}]},{"id":"ch26p29","audio":"ch26p29.mp3","sents":[{"ar":"صغيري، قلت، أريد أن أسمع ضحكتك مجددًا.","zh":"小家伙，我想再听到你的笑声。","t":[103,4616]}]},{"id":"ch26p30","audio":"ch26p30.mp3","sents":[{"ar":"لكن قال لي: - ألا تتذكر؟ لم يكن موجودًا هنا! ومن دون شك رد عليه صوت آخر لأنه أجاب: - أجل! أجل! إنه اليوم المناسب لكنها ليست البقعة المناسبة... تابعت السير باتجاه الحائط، لكنني لم أستطع أن أرى أو أن أسمع أحدًا، مع ذلك أجاب الأمير الصغير مرة أخرى: - ... نعم، طبعًا، ستشاهدين أين تبدأ آثار قدمي في الرمال انتظريني هناك. سأكون هناك الليلة. كنت على بعد مئتي متر فقط من الحائط ومع ذلك لم أستطع أن أرى شيئًا، وبعد صمت قليل تحدث الأمير الصغير ثانية: - هل السم لديك جيد؟ هل أنت متأكدة من أنه لن يجعلني أعاني وقتًا طويلًا جدًّا؟ وقفت على دربي وقلبي يعتصر، لكنني لم أكن لأفهم. قال: - الآن اذهبي... أريد أن أنزل! عندئذ خفضت نظري إلى أدنى الجدار، وما رأيت جعلني أقفز في الهواء! كانت هناك إحدى تلك الحيات الصفراوات، التي تستطيع أن تفتك بك في غضون ثوانٍ، رافعة رأسها باتجاه الأمير الصغير. « والآن انصرف، أريد أن أنزل عن هنا » بدأت بالركض وأنا أبحث في جيبي عن مسدسي، لكن بسبب الجلبة التي أحدثتها، انزلقت الحية بسهولة عائدة إلى الرمل مثل نافورة مياه متلاشية، ومن دون أي عجلة ظاهرة، اختفت وسط الحجارة بصوت رنان. وصلت إلى الجدار في الوقت المناسب لألتقط أميري الصغير بذراعي، وقد استحال وجهه أبيض كالثلج. سألته: - ماذا يعني ذلك؟ لماذا تتحدث إلى الحية؟ فككت اللفاع الذهبي الذي لا يفارق عنقه أبدًا، ثم رطبت جبينه وقدمته بعض الماء للشرب، ثم لم أجرؤ على طرح المزيد من الأسئلة. نظر بجدية إلي ووضع ذراعيه حول عنقي. استطعت أن أشعر بقلبه يخفق مثل قلب عصفور يحتضر بعد إصابته بطلقة نارية من بندقية شخص ما. قال لي: - إنني سعيد جدًّا لأنك اكتشفت العطل في محركك، الآن تستطيع أن تذهب إلى وطنك. - كيف عرفت؟ في الواقع، كنت على وشك أن أخبره أن مهمتي نجحت، على العكس من كل التوقعات. لم يجب عن سؤالي، لكنه همس قائلًا: - أنا أيضًا سأعود اليوم إلى وطني. ثم أضاف بشيء من الحزن: - إنه أبعد بكثير... من الصعب أكثر... استطعت أن أشعر بأن شيئًا غير عادي يوشك أن يحدث. كنت أضمه بقوة بذراعي كطفل، ومع ذلك بدا لي أنه ينزلق إلى هاوية، لكنني لم أستطع فعل أي شيء للحؤول دون ذلك. كانت نظرته جدية وتائهة. - لدي خروفك، ولدي الصندوق من أجل الخروف، كما لدي الكمامة أيضًا. ثم ابتسم بحزن. انتظرت وقتًا طويلًا، استطعت أن أشعر بأنه بدأ يدفأ شيئًا فشيئًا. - لقد كنت خائفًا يا رجلي الصغير العزيز. أصيب بالرعب، طبعًا! لكنه ضحك بلطف. - سأشعر بخوف أكبر هذا المساء. مرة ثانية أصابني بالجمود، شعور بأن هناك أمرًا لا يمكن إصلاحه. أدركت أنني لن أتحمل فكرة عدم سماع تلك الضحكة ثانية، كانت أشبه بينبوع ماء عذب في صحراء نفسي. - أريد أن أسمعك تضحك ثانية يا أميري الصغير. لكنه قال لي: - الليلة، تنقضي سنة... وستكون نجمتي تمامًا فوق البقعة حيث هبطت منذ... قلت له: - أيها الأمير الصغير، قل لي إن قصة الحية واللقاء والنجمة ليست إلا حلمًا مزعجًا. لكنه لم يجب عن سؤالي، وبدلًا من ذلك قال لي: - لا يمكن رؤية ما هو مهم. - أجل، أعرف. - تمامًا كما هي الحال مع الزهرة، إذا أحببت زهرة حدث أنها على نجمة، فسيكون من الممتع أن تحدق ليلًا إلى السماء. إن النجوم هي أزهار غزيرة. - أجل، أعرف. - إن الأمر مماثل بالنسبة إلى الماء، فالجرعة التي أعطيتني كانت كالموسيقى تمامًا، بسبب البكرة والحبل... أنت تتذكر، أليس كذلك؟ لقد كانت عذبة. - أجل، أعرف. ستحدق إلى النجوم ليلًا. إن كل شيء صغير جدًّا حيث أعيش لدرجة أنني لا أستطيع أن أريك أين تقع نجمتي. إن الأمر هو أفضل على هذا النحو. ستكون نجمتي إحدى النجمات بالنسبة إليك، وهكذا ستتوق إلى النظر إليها كلها. ستكون كلها صديقات لك. لدي هدية لك... ضحك ثانية. - آه! أيها الأمير الصغير، يا أميري الصغير العزيز، أحب أن أسمع هذه الضحكة! - تمامًا، تلك ستكون هديتي، كما كان الأمر مع الماء... - ماذا تقول؟ - إن النجوم تعني أمورًا مختلفة لمختلف الناس، فبالنسبة إلى البعض هي ليست أكثر من أنوار متلألئة في السماء. وبالنسبة إلى المسافرين هي دليل. وبالنسبة إلى العلماء هي غذاء للفكر. وبالنسبة إلى رجال أعمالنا هي ثروة. لكن النجوم بالنسبة إلى الجميع هي صامتة، وهذا الأمر لا ينطبق عليك من الآن فصاعدًا. - ماذا تعني؟ - عندما تنظر إلى السماء في الليل، ونظرًا لأنني سأعيش على إحداها وأضحك، سيبدو لك أن النجوم كافة تضحك. أنت، وأنت فقط، ستكون لديك نجوم ضاحكة! (قال ذلك وضحك). وعندما ترتاح -لأن الوقت يلطف الأحزان كلها- ستشعر بالفرح لأنك عرفتني، ستكون دائمًا صديقي، سترغب في الضحك معي، ومن حين إلى آخر ستفتح نافذتك لمجرد الاستمتاع بذلك. وأصدقاؤك سيُدهشون عندما يشاهدونك تضحك بينما تحدق إلى السماء. ولسوف تقول لهم: أجل، إن النجوم تدفعني إلى الضحك باستمرار. وسيظنون أنك مجنون، وسأكون قد قمت بحيلة بارعة... (ضحك ثانية) سيبدو الأمر وكأنني قدمت لك عوضًا عن النجوم، الكثير من الأجراس الصغيرة التي تستطيع أن تضحك... (وضحك مرة أخرى، ثم أصبح جديًّا ثانية) الليلة... أنت تعرف... لا تأت. - لن أتركك. - سأبدو أنني أتألم. سأبدو وكأنني أحتضر. إن الأمر هكذا. لا تأت لترى ذلك؛ لا جدوى. - لن أتركك. كان قلقًا. - أقول لك... جزئيًّا بسبب الحية، لا ينبغي أن تعضك، فالحيات مخلوقات شريرة. يمكنها أن تعض لمجرد اللهو. - لن أتركك. طمأنته فكرة. - هل من الصحيح أنها لا تمتلك المزيد من السم من أجل عضة ثانية؟ في تلك الليلة لم أشاهده يبدأ رحلة. غادر من دون أي صوت، وعندما تمكنت من اللحاق به، كان يسير بخطى سريعة ثابتة. قال لي فقط: - أوه! أنت هنا! وأمسك بيدي، وكان ما زال يشعر بالقلق. - لم يكن ينبغي لك المجيء، لن تكون سعيدًا، سأبدو وكأنني أحتضر ولن يكون ذلك صحيحًا. لم أقل شيئًا. - عليك أن تفهم، إنه بعيد جدًّا. لا أستطيع أن أحمل هذا الجسد معي؛ إنه ثقيل جدًّا. لم أقل شيئًا. - سيبدو مثل صدفة قديمة مهجورة، وليس شيئًا تحزن من أجله. لم أقل شيئًا. كان مثبَط الهمة، لكنه بذل جهدًا أخيرًا. - أتعرف... سيكون كل شيء لطيفًا. أنا أيضًا سأنظر إلى النجوم، وستكون كل النجوم آبارًا ذات بكرات صدئة، ستسكب كل النجوم لي شيئًا من الماء لأشرب. لم أقل شيئًا. - سيكون ذلك ممتعًا جدًّا! سيكون لدي خمسمئة مليون جرس صغير، سيكون لدي خمسمئة مليون نبع من المياه العذبة... وهو أيضًا لم يقل المزيد لأنه كان يبكي... - ها هي. دعني أذهب بمفردي. ثم جلس لأنه أحس بالخوف. بعد ذلك قال: - هل تعلم... زهرتي... أنا مسؤول عنها، وهي ضعيفة جدًّا وتثق بالآخرين كثيرًا. لديها أربع أشواك صغيرة لتحمي نفسها من العالم. جلست لأنني لم أستطع أن أبقى واقفًا أكثر من ذلك. قال: - الآن... هذا كل شيء. تردد قليلًا، ثم وقف، تقدم خطوة إلى الأمام. لم أستطع أن أتحرك. لم يبق شيء أكثر من وميض أصفر قريب من كاحله. وقف بلا حراك لحظة، لم يصرخ، هوى بلطف مثلما تهوي شجرة، لم يكن هنالك حتى أخف صوت بسبب الرمل.","zh":"他对我说：","t":[103,659096]}]},{"id":"ch26p31","audio":"ch26p31.mp3","sents":[{"ar":"الليلة، تنقضي سنة... وستكون نجمتي تمامًا فوق البقعة حيث هبطت منذ...","zh":"今夜，它将是一周年……","t":[103,8487]},{"ar":"نجمتي، إذن، يمكن العثور عليها فوق المكان الذي هبطت فيه إلى الأرض، قبل عامٍ...","zh":"我的星星，现在就在我一年前降落到地球的那个地方上方……","t":[8487,15921]}]},{"id":"ch26p32","audio":"ch26p32.mp3","sents":[{"ar":"يا صغير الرجل، قل لي إن هذه القصة عن الثعبان، والمكان اللقاء، والنجمة ليست إلا حلمًا مزعجًا...","zh":"小家伙，告诉我，这关于蛇、约会和星星的事，只是一场噩梦……","t":[103,8879]}]},{"id":"ch26p33","audio":"ch26p33.mp3","sents":[{"ar":"لكن لم يرد على دعائي.","zh":"但他并未回应我的哀求。","t":[103,2987]},{"ar":"قال لي: بدلاً من ذلك:","zh":"他转而对我说：","t":[2987,5211]}]},{"id":"ch26p34","audio":"ch26p34.mp3","sents":[{"ar":"ما هو مهم هو ما لا يُرى...","zh":"那重要的东西，是肉眼无法看见的……","t":[103,2248]}]},{"id":"ch26p35","audio":"ch26p35.mp3","sents":[{"ar":"نعم، أعلم…","zh":"是的，我知道……","t":[103,1589]}]},{"id":"ch26p36","audio":"ch26p36.mp3","sents":[{"ar":"إنه كذلك بالنسبة للوردة.","zh":"它对花儿来说也是如此。","t":[103,3513]},{"ar":"إذا أحببت وردة تعيش على نجم، سيكون من السعادة النظر إلى السماء في الليل.","zh":"若你爱上了一朵生长在星星上的花，那么在夜晚仰望星空便显得格外甜蜜。","t":[3513,10776]},{"ar":"كل النجوم تزهر بالزهور...","zh":"繁星似锦，花开满空","t":[10776,12948]}]},{"id":"ch26p37","audio":"ch26p37.mp3","sents":[{"ar":"نعم، أعلم...","zh":"是的，我知道……","t":[103,1550]}]},{"id":"ch26p38","audio":"ch26p38.mp3","sents":[{"ar":"الماء كذلك.","zh":"水亦如此。","t":[103,2263]},{"ar":"بسبب الحبل والسلك، ما أعطيتني منه للشرب كان كالموسيقى.","zh":"因为那辘轳和绳子，你给我的水，如同音乐。","t":[2263,8013]},{"ar":"أتذكرُـ كيف كان ذلك رائعًا.","zh":"你记得——那时多么美好。","t":[8013,10631]}]},{"id":"ch26p39","audio":"ch26p39.mp3","sents":[{"ar":"نعم، أعلم...","zh":"是的，我知道……","t":[103,1550]}]},{"id":"ch26p40","audio":"ch26p40.mp3","sents":[{"ar":"وفي الليل، ستشاهد النجوم.","zh":"在夜晚，你会仰望星空。","t":[103,3684]},{"ar":"حيث أعيش فيه كل شيء صغير جدًا لا أستطيع أن أريك أين تقع نجمتي.","zh":"我住的地方一切都很小，无法向你指出我的星星所在之处。","t":[3684,10487]},{"ar":"كما هو أفضل هكذا.","zh":"如此更佳。","t":[10487,13158]},{"ar":"نجمتي سيكون مجرد نجم بين النجوم، لكِ.","zh":"我的星星只是万千星辰之一，对你而言。","t":[13158,18382]},{"ar":"ولذا ستحب مشاهدة كل النجوم في السماء...","zh":"因此，你将喜欢观看天空中所有的星星……","t":[18382,22763]},{"ar":"ستكون كلها صديقات لك.","zh":"它们都将成为你的朋友。","t":[22763,26066]},{"ar":"بالإضافة إلى ذلك، سأقدم لك هدية...","zh":"此外，我还要送你一份礼物……","t":[26066,29632]}]},{"id":"ch26p41","audio":"ch26p41.mp3","sents":[{"ar":"ضحك مرة أخرى.","zh":"他又笑了。","t":[103,1668]}]},{"id":"ch26p42","audio":"ch26p42.mp3","sents":[{"ar":"أوه، الأمير الصغير، الأمير الصغير العزيز!","zh":"啊，小王子，我亲爱的王子！","t":[103,5237]},{"ar":"أحب أن أسمع ضحكتك!","zh":"我喜欢听你的笑声！","t":[5237,7197]}]},{"id":"ch26p43","audio":"ch26p43.mp3","sents":[{"ar":"هذا هدية لي.","zh":"这是我的礼物。","t":[103,2447]},{"ar":"هذا فقط.","zh":"仅此而已。","t":[2447,4408]},{"ar":"سيكون كما كنا عندما شربنا الماء...","zh":"它将如同我们共饮那水时一般。","t":[4408,7356]}]},{"id":"ch26p44","audio":"ch26p44.mp3","sents":[{"ar":"ماذا تحاول أن تقول؟","zh":"你究竟想表达什么？","t":[103,1984]}]},{"id":"ch26p45","audio":"ch26p45.mp3","sents":[{"ar":"كل رجل يمتلك النجوم، ولكنها ليست نفس الأشياء بالنسبة للناس المختلفين.","zh":"每个人心中都有星星，但对不同的人来说，它们的意义各不相同。","t":[103,7632]},{"ar":"بالنسبة لبعض منهم، منهم الموالون، تكون النجوم مرشدين.","zh":"对某些旅人来说，星星是向导。","t":[7632,14092]},{"ar":"بالنسبة لبعض الناس، ليست أكثر من ضوء صغير في السماء.","zh":"对其他人而言，它们不过是天空中微小的灯火。","t":[14092,19895]},{"ar":"بالنسبة للعلماء، هي مشاكل.","zh":"对学者来说，它们是问题。","t":[19895,23566]},{"ar":"بالنسبة لرجل الأعمال، كانت هي الثروة.","zh":"对那位商人来说，它们是财富。","t":[23566,27934]},{"ar":"لكل هذه النجوم صمت.","zh":"但这些星星都沉默着。","t":[27934,30855]},{"ar":"أنت-أنت فقط-ستمتلك النجوم كأحد لا يمتلكها أحد آخر-","zh":"你——只有你——将拥有别人无法拥有的星星——","t":[30855,36039]}]},{"id":"ch26p46","audio":"ch26p46.mp3","sents":[{"ar":"ماذا تحاول أن تقول؟","zh":"你究竟想表达什么？","t":[103,1984]}]},{"id":"ch26p47","audio":"ch26p47.mp3","sents":[{"ar":"في نجمة سأعيش.","zh":"在某一颗星星上，我将居住。","t":[103,2737]},{"ar":"على كوكبك، سأضحك.","zh":"在那颗星星上，我会笑着。","t":[2737,5776]},{"ar":"وعندما تنظر إلى السماء في الليل، فإن النجوم كافة تبدو كأنها تضحك!","zh":"当你在夜晚仰望星空时，仿佛所有的星星都在欢笑。","t":[5776,12487]},{"ar":"أنت - فقط أنت - ستملك نجومًا تضحك!\" وضحك مرة أخرى.","zh":"你——只有你——将拥有会笑的星星！他再次笑了。","t":[12487,18158]}]},{"id":"ch26p48","audio":"ch26p48.mp3","sents":[{"ar":"وعندما يهدأ حزنك (الزمن يهدئ كل الحزن) ستكون سعيدًا بأنك تعرفت علي.","zh":"当你的悲伤得到慰藉（时间抚平所有悲伤）时，你将满足于曾认识我。","t":[103,8329]},{"ar":"ستكون دائمًا صديقي","zh":"你永远是我的朋友。","t":[8329,10053]},{"ar":"ستعجبك الضحك معي.","zh":"你愿与我同笑。","t":[10053,12803]},{"ar":"أحياناً ستفتح نافذتك، لهذا السعادة...","zh":"有时，你也会打开窗子，为了那份快乐……","t":[12803,17197]},{"ar":"وأنتم يا أصدقاؤي ستفاجأون بحسن خلقكم عندما ترونني مندمجًا في الضحك بينما أنظر إلى السماء!","zh":"你的朋友们会惊讶地看到你仰望星空时竟在欢笑！","t":[17197,26066]},{"ar":"نعم، النجوم تجعلني أضحك دائمًا! سيظنون أنك مجنون.","zh":"是的，星星总是让我笑！他们会以为你疯了。","t":[26066,33250]},{"ar":"سيكون هذا حيلة سيئة جدًا التي سألعبها عليك...","zh":"这将是我在你身上玩的一个非常拙劣的把戏……","t":[33250,37658]}]},{"id":"ch26p49","audio":"ch26p49.mp3","sents":[{"ar":"وهذا ما يحدث عندما تضحك مرة أخرى.","zh":"他又笑了。","t":[103,3326]}]},{"id":"ch26p50","audio":"ch26p50.mp3","sents":[{"ar":"كأنني أعطيتك العديد من الجرسات الصغيرة التي تعرف كيف تضحك...","zh":"仿佛我给了你无数会笑的小铃铛……","t":[103,5379]}]},{"id":"ch26p51","audio":"ch26p51.mp3","sents":[{"ar":"وهذا هو. دعني أذهب بمفردي. ثم جلس لأنه أحس بالخوف. بعد ذلك قال: - هل تعلم... زهرتي... أنا مسؤول عنها، وهي ضعيفة جدًّا وتثق بالآخرين كثيرًا. لديها أربع أشواك صغيرة لتحمي نفسها من العالم. جلست لأنني لم أستطع أن أبقى واقفًا أكثر من ذلك. قال: - الآن... هذا كل شيء. تردد قليلًا، ثم وقف، تقدم خطوة إلى الأمام. لم أستطع أن أتحرك. لم يبق شيء أكثر من وميض أصفر قريب من كاحله. وقف بلا حراك لحظة، لم يصرخ، هوى بلطف مثلما تهوي شجرة، لم يكن هنالك حتى أخف صوت بسبب الرمل.","zh":"他又笑了。","t":[103,58605]},{"ar":"ثم أصبح جادًا بسرعة:","zh":"他很快变得严肃起来：","t":[58605,60566]}]},{"id":"ch26p52","audio":"ch26p52.mp3","sents":[{"ar":"الليلة... تعرف... لا تأت.","zh":"今夜——你知道……","t":[103,5013]},{"ar":"لا تأتي، قال الأمير الصغير.","zh":"“别来了，”小王子说。","t":[5013,7566]}]},{"id":"ch26p53","audio":"ch26p53.mp3","sents":[{"ar":"لن أتركك، قلت.","zh":"我不会离开你。","t":[103,1852]}]},{"id":"ch26p54","audio":"ch26p54.mp3","sents":[{"ar":"سأبدو وكأنني أعاني.","zh":"我将显得像是在受苦。","t":[103,3053]},{"ar":"سأبدو وكأنني أحتضر.","zh":"我将显得像是即将离世。","t":[3053,5974]},{"ar":"إنه كذلك.","zh":"它就是这样。","t":[5974,8118]},{"ar":"لا تأت لرؤية ذلك.","zh":"别来看那场戏。","t":[8118,10921]},{"ar":"ليس الأمر يستحق العناء...","zh":"不值得费这个劲……","t":[10921,12960]}]},{"id":"ch26p55","audio":"ch26p55.mp3","sents":[{"ar":"لن أتركك.","zh":"我不会离开你。","t":[103,1168]}]},{"id":"ch26p56","audio":"ch26p56.mp3","sents":[{"ar":"لكن كان قلقه.","zh":"但他忧心忡忡。","t":[103,1590]}]},{"id":"ch26p57","audio":"ch26p57.mp3","sents":[{"ar":"هذا لأن الثعبان.","zh":"这同样是因为那条蛇。","t":[103,2684]},{"ar":"لا يجب أن يلدغك.","zh":"它不能咬你。","t":[2684,5197]},{"ar":"الثعبانـ هم مخلوقات شريرة.","zh":"蛇——它们是恶毒的生物。","t":[5197,8461]},{"ar":"هذا الثعبان قد يضربك فقط للمرح...","zh":"这蛇说不定会故意咬你取乐呢……","t":[8461,11316]}]},{"id":"ch26p58","audio":"ch26p58.mp3","sents":[{"ar":"لن أتركك.","zh":"我不会离开你。","t":[103,1168]}]},{"id":"ch26p59","audio":"ch26p59.mp3","sents":[{"ar":"لكن فكرة جاءت لتأكيد نفسه:","zh":"但一个念头让他得到了安慰：","t":[103,2734]}]},{"id":"ch26p60","audio":"ch26p60.mp3","sents":[{"ar":"الثعبان لم يعد لديه سم لعضة ثانية.","zh":"蛇咬的第二口不再有毒液。","t":[103,3498]}]},{"id":"ch26p61","audio":"ch26p61.mp3","sents":[{"ar":"لم أرأنه يغادر في تلك الليلة.","zh":"那晚，我没有看到他踏上归途。","t":[103,3605]},{"ar":"لم يفارقني دون أن يصدر صوتًا.","zh":"他悄无声息地从我身边溜走。","t":[3605,7171]},{"ar":"عندما استطعت اللحاق به كان يسير بخطوات سريعة وقوية.","zh":"他追上他时，他正迈着迅速而坚定的步伐前行。","t":[7171,12855]},{"ar":"قال لي: لا شيء أكثر من هذا.","zh":"他只对我说了这么一句：","t":[12855,15527]}]},{"id":"ch26p62","audio":"ch26p62.mp3","sents":[{"ar":"آه!","zh":"啊！","t":[103,1421]},{"ar":"أنت هناك...","zh":"你就在那里……","t":[1421,2513]}]},{"id":"ch26p63","audio":"ch26p63.mp3","sents":[{"ar":"أمسك بيدي","zh":"他握住了我的手。","t":[103,1103]},{"ar":"لكن كان يشعر بالقلق حتى الآن.","zh":"他依旧忧心忡忡。","t":[1103,3892]}]},{"id":"ch26p64","audio":"ch26p64.mp3","sents":[{"ar":"كان خطأً أن تأتِ.","zh":"你来得不对。","t":[103,2526]},{"ar":"ستعاني.","zh":"你将受苦。","t":[2526,4421]},{"ar":"سأبدو كأنني ميت، ولكن هذا ليس صحيحًا...","zh":"我将看起来像是死了；其实并非如此……","t":[4421,8619]}]},{"id":"ch26p65","audio":"ch26p65.mp3","sents":[{"ar":"لم أقول شيئًا.","zh":"我无言以对。","t":[103,1497]}]},{"id":"ch26p66","audio":"ch26p66.mp3","sents":[{"ar":"أفهم...","zh":"你懂得……","t":[103,1632]},{"ar":"البعد كبير جدًا.","zh":"路途太过遥远。","t":[1632,4303]},{"ar":"لا أستطيع حمل هذا الجسد معي.","zh":"我无法带着这具身体离去。","t":[4303,7724]},{"ar":"هذا ثقيل جدًا.","zh":"这太沉重了。","t":[7724,9276]}]},{"id":"ch26p67","audio":"ch26p67.mp3","sents":[{"ar":"لم أقول شيئًا.","zh":"我无言以对。","t":[103,1497]}]},{"id":"ch26p68","audio":"ch26p68.mp3","sents":[{"ar":"لكن سيكون كالقشرة القديمة المهجورة.","zh":"却如同褪去的旧壳。","t":[103,4289]},{"ar":"ليس هناك شيء حزين في قذائف القديم...","zh":"旧壳并无悲凉之处……","t":[4289,7539]}]},{"id":"ch26p69","audio":"ch26p69.mp3","sents":[{"ar":"لم أقول شيئًا.","zh":"我无言以对。","t":[103,1497]}]},{"id":"ch26p70","audio":"ch26p70.mp3","sents":[{"ar":"كان الأمير الصغير مقلوبًا على نفسه قليلًا.","zh":"他有些气馁。","t":[103,4395]},{"ar":"ولكنه جعل جهدًا آخر:","zh":"但他又试了一次：","t":[4395,6579]}]},{"id":"ch26p71","audio":"ch26p71.mp3","sents":[{"ar":"أتعلم، سيكون ذلك رائعًا جدًا.","zh":"你懂得，这会非常美好。","t":[103,4342]},{"ar":"أنا أيضًا سأنظر إلى النجوم","zh":"我也会仰望星空。","t":[4342,6421]},{"ar":"كل النجوم ستكون آبارًا بآلات تعليق صدئة.","zh":"繁星如井，辘轳生锈。","t":[6421,11132]},{"ar":"النجوم ستسقي لي من ماء جديد لتشرب به...","zh":"繁星将为我涌出清泉解渴。","t":[11132,14460]}]},{"id":"ch26p72","audio":"ch26p72.mp3","sents":[{"ar":"لم أقول شيئًا.","zh":"无言以对。","t":[103,1497]}]},{"id":"ch26p73","audio":"ch26p73.mp3","sents":[{"ar":"سيكون ذلك ممتعًا جدًا! سيكون لدي خمسمئة مليون جرس صغير، سيكون لدي خمسمئة مليون نبع من المياه العذبة... وهو أيضًا لم يقل المزيد لأنه كان يبكي... - ها هي. دعني أذهب بمفردي. ثم جلس لأنه أحس بالخوف. بعد ذلك قال: - هل تعلم... زهرتي... أنا مسؤول عنها، وهي ضعيفة جدًا وتثق بالآخرين كثيرًا. لديها أربع أشواك صغيرة لتحمي نفسها من العالم. جلست لأنني لم أستطع أن أبقى واقفًا أكثر من ذلك. قال: - الآن... هذا كل شيء. تردد قليلًا، ثم وقف، تقدم خطوة إلى الأمام. لم أستطع أن أتحرك. لم يبق شيء أكثر من وميض أصفر قريب من كاحله. وقف بلا حراك لحظة، لم يصرخ، هوى بلطف مثلما تهوي شجرة، لم يكن هنالك حتى أخف صوت بسبب الرمل.","zh":"那将非常有趣！","t":[103,73842]},{"ar":"ستكون لديك خمسمئة مليون جرس صغير، وسأكون لدي خمسمئة مليون نبع من المياه العذبة...","zh":"你将拥有五亿个小铃铛，而我将拥有五亿股清泉……","t":[73842,82000]}]},{"id":"ch26p74","audio":"ch26p74.mp3","sents":[{"ar":"وهذا هو. دعني أذهب بمفردي. ثم جلس لأنه أحس بالخوف. بعد ذلك قال: - هل تعلم... زهرتي... أنا مسؤول عنها، وهي ضعيفة جدًّا وتثق بالآخرين كثيرًا. لديها أربع أشواك صغيرة لتحمي نفسها من العالم. جلست لأنني لم أستطع أن أبقى واقفًا أكثر من ذلك. قال: - الآن... هذا كل شيء. تردد قليلًا، ثم وقف، تقدم خطوة إلى الأمام. لم أستطع أن أتحرك. لم يبق شيء أكثر من وميض أصفر قريب من كاحله. وقف بلا حراك لحظة، لم يصرخ، هوى بلطف مثلما تهوي شجرة، لم يكن هنالك حتى أخف صوت بسبب الرمل.","zh":"他默默无言，只因泪水盈眶。","t":[103,57684]}]},{"id":"ch26p75","audio":"ch26p75.mp3","sents":[{"ar":"هذا هو.","zh":"这里就是了。","t":[103,1842]},{"ar":"دعني أستمر بنفسي.","zh":"让我自己继续吧。","t":[1842,3579]}]},{"id":"ch26p76","audio":"ch26p76.mp3","sents":[{"ar":"وأجلس لأنه خشي من الخوف.","zh":"他坐下来，因为他害怕了。","t":[103,3618]},{"ar":"ثم قال، ثانية:","zh":"他又说道：","t":[3618,5500]}]},{"id":"ch26p77","audio":"ch26p77.mp3","sents":[{"ar":"أتعلم... زهرة...","zh":"你可知——我的花儿……","t":[103,3382]},{"ar":"أنا مسؤول عنها","zh":"我为她负责。","t":[3382,4684]},{"ar":"وهي ضعيفة جدًا!","zh":"她如此脆弱！","t":[4684,7303]},{"ar":"هي بسيطة جدًا!","zh":"她如此天真！","t":[7303,9803]},{"ar":"هي ليست لها إلا أربع شوك صغيرة، لا فائدة منها على الإطلاق، لحمايتها من العالم بأسره...","zh":"她仅有四根刺，毫无用处，却用来抵御整个世界的侵害。","t":[9803,17658]}]},{"id":"ch26p78","audio":"ch26p78.mp3","sents":[{"ar":"أنا أيضًا جلست لأنني لم أستطع أن أستمر في الوقوف.","zh":"我也坐了下来，因为我已无法再站立。","t":[103,4247]}]},{"id":"ch26p79","audio":"ch26p79.mp3","sents":[{"ar":"هذا كافٍ...","zh":"那便足够了……","t":[103,1024]}]},{"id":"ch26p80","audio":"ch26p80.mp3","sents":[{"ar":"كان يتردد قليلاً، ثم وقف.","zh":"他犹疑片刻，然后站起身来。","t":[103,3934]},{"ar":"لقد خطوة واحدة.","zh":"他迈出一步。","t":[3934,6526]},{"ar":"لم أستطع أن أتحرك.","zh":"我动弹不得。","t":[6526,8395]}]},{"id":"ch26p81","audio":"ch26p81.mp3","sents":[{"ar":"بجانب كاحله، كان هناك ومضة صفراء فقط.","zh":"踝边，一抹黄光掠过。","t":[103,5171]},{"ar":"لم يتحرك للحظة واحدة.","zh":"他瞬间僵立不动。","t":[5171,8368]},{"ar":"لم يصرخ.","zh":"他没有呼喊。","t":[8368,10158]},{"ar":"إنه سقط بسهولة كأن شجرة تسقط.","zh":"他如树般轻轻倒下。","t":[10158,14474]},{"ar":"لم يكن هنالك حتى صوت، بسبب الرمل.","zh":"连沙沙声也没有，因为沙子的缘故。","t":[14474,17869]}]}]},{"id":"ch27","title_ar":"الفصل السابع والعشرون","title_en":"Chapter XXVII","title_zh":"第 27 章","paras":[{"id":"ch27p00","audio":"ch27p00.mp3","sents":[{"ar":"وها قد مضت ست سنوات...","zh":"六载光阴，已然逝去……","t":[103,2287]}]},{"id":"ch27p01","audio":"ch27p01.mp3","sents":[{"ar":"لم أروي هذه القصة من قبل.","zh":"这故事，我从未对人提起。","t":[103,3355]},{"ar":"الرفاق الذين لقوني عند عودتي كانوا سعداء برؤيتي على قيد الحياة.","zh":"重逢的伙伴们见到我安然无恙，心中皆感欣慰。","t":[3355,9671]},{"ar":"كنت حزيناً، لكنني أخبرتهم بأنني مرهق.","zh":"我心情沉重，却对他们说：“我累得要命。”","t":[9671,13592]}]},{"id":"ch27p02","audio":"ch27p02.mp3","sents":[{"ar":"والآن، قلبي قد استقر قليلاً.","zh":"我的哀愁得以稍慰。","t":[103,3895]},{"ar":"هذا يعني- لم يكن تمامًا.","zh":"这也就是说——并未完全。","t":[3895,7447]},{"ar":"لكني أعلم أنه عاد إلى كوكبه، لأنني لم أجد جسده عند الفجر.","zh":"但我深知他已返回自己的星球，因为天亮时我没有找到他的遗体。","t":[7447,14066]},{"ar":"لم يكن الجسد ثقيلًا...","zh":"他的遗体并不沉重……","t":[14066,16934]},{"ar":"في الليل أحب الاستماع إلى نجوم السماء تنهمر.","zh":"夜幕降临，我偏爱聆听星辰的低语。","t":[16934,21395]},{"ar":"إنها كخمسمئة مليون جرس صغير...","zh":"它们宛如五亿个小铃铛……","t":[21395,24434]}]},{"id":"ch27p03","audio":"ch27p03.mp3","sents":[{"ar":"لكن هناك شيء استثنائي...","zh":"然而，有一件不同寻常的事……","t":[103,3303]},{"ar":"عندما رسمت الكمامة للأمير الصغير، نسيت أن أضيف الشريط الجلدي إليها.","zh":"为小王子画了口罩，却忘了添上皮带。","t":[3303,10211]},{"ar":"لم يتمكن أبدًا من ربطها حول عنق قوادة.","zh":"他永远无法将它系在绵羊的脖子上。","t":[10211,14803]},{"ar":"أنا أتساءل دائمًا عما يحدث على كوكبه.","zh":"我始终在思索：他的星球上究竟发生了什么？","t":[14803,19000]},{"ar":"ربما أكل الأبقار الزهرة...","zh":"或许绵羊已经吃掉了那朵花……","t":[19000,20921]}]},{"id":"ch27p04","audio":"ch27p04.mp3","sents":[{"ar":"بالطبع لا! فالأمير الصغير يغطي زهرته بقبتها الزجاجية كل ليلة ويراقب خروفه بانتباه...","zh":"当然，不会吧！","t":[103,10211]},{"ar":"الأمير الصغير يغلق زهرته في كرة الزجاج كل ليلة ويشاهد غنمه بحذر شديد... ثم أكون سعيدًا.","zh":"小王子每晚都将他的花儿藏进玻璃球中，他精心照看着他的绵羊……于是，我便安心了。","t":[10211,20579]},{"ar":"في ضحك النجوم، حلوة الروح.","zh":"星光笑意中，自有甜蜜。","t":[20579,23303]}]},{"id":"ch27p05","audio":"ch27p05.mp3","sents":[{"ar":"لكن في وقت آخر أقول لنفسي: \"في لحظة ما أو أخرى، يُصبح الشخص غافلاً، وهذا كافٍ!","zh":"然而，有时我会对自己说：人难免会疏忽大意，这就足够了！","t":[103,8750]},{"ar":"في ليلة ما نسي الأمل الصغير كرة الزجاج، أو انطلق الأغنام دون صوت، في الليل... ثم تحولت البوقات الصغيرة إلى دموع...","zh":"那天晚上，他忘了玻璃球，或者绵羊悄无声息地溜出了，然后那些小铃铛就变成了泪水……","t":[8750,19198]}]},{"id":"ch27p06","audio":"ch27p06.mp3","sents":[{"ar":"هناك لغز عظيم","zh":"这是一桩不解之谜。","t":[103,1563]},{"ar":"لمن يحبون الأمير الصغير مثلي، ولم يكن في الكون شيء نفسه إذا في مكان ما، لا نعرفه، أكلت هناك شاة لم نرها قط وردة... نعم أو لا؟","zh":"对于你们这些也喜爱小王子的人，还有我，若在宇宙的某个角落，有一只我们从未见过的绵羊——真的吗？——吃掉了一朵玫瑰，那么，宇宙间的一切都将不再相同……","t":[1563,14513]}]},{"id":"ch27p07","audio":"ch27p07.mp3","sents":[{"ar":"أنظروا إلى السماء","zh":"仰望星空。","t":[103,1287]},{"ar":"اسألوا أنفسكم: هل أكل الخروف الزهرة؟ نعم أو لا؟","zh":"请自问：是，还是否？","t":[1287,7487]},{"ar":"هل أكلت الأغنام الزهرة؟","zh":"绵羊是否吞食了那朵花？","t":[7487,10342]},{"ar":"وسترى كيف تتغير الأمور...","zh":"你们便会察觉万物如何变幻。","t":[10342,12685]}]},{"id":"ch27p08","audio":"ch27p08.mp3","sents":[{"ar":"ولم يفهم الأكبرون أبدًا لماذا هذا الأمر مهم! هذا بالنسبة لي أجمل وأحزن طبيعة في العالم، إنه الطبيعة نفسها كما في الصورة الأخيرة، لكنني رسمته مرة ثانية كي أطبعه في ذاكرتكم. إنه المكان حيث ظهر الأمير الصغير على الأرض ثم اختفى. انظروا بانتباه إلى الطبيعة لتتأكدوا من أن تتذكروا إذا ما قمتم بالسفر ذات يوم إلى إفريقيا، عبر الصحراء. وإذا صادفتم أن وصلتم إلى هذه النقطة، أرجو ألا تتابعوا السير بسرعة، تريثوا قليلًا تحت النجمة تمامًا، بعد ذلك، إذا جاء طفل باتجاهكم، إذا ضحك، إذا كانت لديه خصل شعر ذهبية، وإذا رفض أن يجيب على الأسئلة، فأنتم بالتأكيد ستعرفون من هو، لذا كونوا طيبين! لا تتركوني أستسلم للحزن، اكتبوا لي بسرعة كي تخبروني أنه عاد.","zh":"大人永远无法明白，这个问题有多么重要！","t":[103,62882]}]},{"id":"ch27p09","audio":"ch27p09.mp3","sents":[{"ar":"هذا هو، بالنسبة لي، أجمل وأحزن مناظر الأرض في العالم","zh":"这，于我而言，是世上最美丽又最悲伤的风光。","t":[103,5116]},{"ar":"المثل الذي في الصفحة السابقة، ولكني رسمته ثانية لتعميق تأثيره في ذاكرتكم.","zh":"与前页相同，但我再次绘制它，是为了加深你们的印象。","t":[5116,13158]},{"ar":"هنا ظهر الأمير الصغير على الأرض ثم اختفى.","zh":"小王子便是在此地降临地球，又在此地消失。","t":[13158,16526]}]},{"id":"ch27p10","audio":"ch27p10.mp3","sents":[{"ar":"أنظروا إليه بعناية حتى تكونوا متأكدين من التعرف عليه في حال سفرتم إلى الصحراء الأفريقية يوماً ما.","zh":"仔细端详，以便有朝一日你在非洲沙漠旅行时能认出它。","t":[103,9316]},{"ar":"إذا مررت بهذا المكان، فلا تسرع في الطريق.","zh":"若你途经此地，请勿匆匆赶路。","t":[9316,14026]},{"ar":"انتظر لحظة، تحت النجم بالضبط.","zh":"在星光下稍作等待。","t":[14026,17855]},{"ar":"إذا ظهر رجل صغير يضحك، بأسنان ذهبية، ويرفض الإجابة على الأسئلة، ستعرف من هو.","zh":"若有个孩童笑逐颜开，金发披肩，对问话不答，你便识得他是谁了。","t":[17855,26987]},{"ar":"إذا حدث هذا، فأراني الراحة.","zh":"若此成真，请安慰我。","t":[26987,30671]},{"ar":"أرسلوا لي إشارة بأنه قد عاد.","zh":"请告知我他已归来。","t":[30671,33316]}]},{"id":"ch27p11","audio":"ch27p11.mp3","sents":[{"ar":"سaint-exupéry: مختصر سيرة حياته","zh":"圣埃克苏佩里：简传","t":[103,2366]}]},{"id":"ch27p12","audio":"ch27p12.mp3","sents":[{"ar":"صديقوه يُدعوه سانت-إكزوبيري","zh":"他的朋友们称他为圣埃克苏佩里。","t":[103,3339]},{"ar":"الحقيقة، كان يُدعى أنطوان دو سانت إكزوبيري.","zh":"实际上，他名叫安东尼·德·圣埃克苏佩里。","t":[3339,6921]},{"ar":"هو من أعظم الكتاب الفرنسيين.","zh":"他是法国最伟大的作家之一。","t":[6921,10289]},{"ar":"هو أيضًا من الرواد الذين أسسوا الطيران.","zh":"他也是航空业的先驱之一。","t":[10289,14329]},{"ar":"هذه قصته.","zh":"这是他的故事。","t":[14329,15579]}]},{"id":"ch27p13","audio":"ch27p13.mp3","sents":[{"ar":"أنطوان دو سانت إكزوبيري ولد في ليون سنة 1900.","zh":"圣埃克苏佩里于1900年出生于里昂。","t":[103,3511]},{"ar":"في سن مبكرة، حلمن ب مغامرة.","zh":"早年，他梦想着冒险。","t":[3511,9737]},{"ar":"كانت أمنيته الأكبر أن يصبح ضابطًا في البحرية.","zh":"他最大的愿望是成为一名海军军官。","t":[9737,14408]},{"ar":"لِيُصبح ضابطًا بحريًا، كان لابد من اجتياز امتحان شديد الصعوبة.","zh":"为了成为一名海军军官，必须通过一场极其艰难的考试。","t":[14408,20763]},{"ar":"استكملت الإمتحان وفشلت...","zh":"圣埃克苏佩里应试未果...","t":[20763,24000]},{"ar":"حسنًا، سأقوم بترجمة الجملة المطلوبة إلى العربية:\n\nحسنًا، هناك حل آخر – الطيران.","zh":"幸而，还有另一种解决办法——航空。","t":[24000,33908]},{"ar":"في هذا الوقت، كانت الطيران خطيرًا للغاية.","zh":"那时，航空极为危险。","t":[33908,38539]},{"ar":"المخاطر، الخطر-- هذا هو بالضبط ما كان يطمح إليه سانت-إكزوبيري.","zh":"危险，风险——这正是圣埃克苏佩里所渴望的。","t":[38539,46158]},{"ar":"خلال خدمته العسكرية، تعلم قيادة الطائرات.","zh":"在服役期间，他学会了驾驶飞机。","t":[46158,51289]},{"ar":"كان لدي سانت-إكزوبيري فكرة واحدة في رأسه: الطيران.","zh":"圣埃克苏佩里心中只有一个念头：飞翔。","t":[51289,56211]}]},{"id":"ch27p14","audio":"ch27p14.mp3","sents":[{"ar":"بعد انتهاء خدمته العسكرية، قدّم نفسه إلى مدير شركة طيران وأعرب له عن رغبته في أن يصبح طيارًا.","zh":"服役结束后，他向一家航空公司经理表达了自己想成为一名飞行员的愿望。","t":[103,10092]},{"ar":"المخرج قال له: \"افعل كما يفعل الجميع.","zh":"导演对他说：“就像别人一样做吧。”","t":[10092,14658]},{"ar":"أولاً، يجب أن تصبح ميكانيكيًا.","zh":"首先，你得学会做一名机械师。","t":[14658,17881]}]},{"id":"ch27p15","audio":"ch27p15.mp3","sents":[{"ar":"أنطوان دو سانت إكزوبيري عمل ليتصرف كميكانيكي.","zh":"圣埃克苏佩里努力成为一名机械师。","t":[103,5329]},{"ar":"، وقد وصل إلى هدفه أخيرًا.","zh":"1927年，他终于实现了目标。","t":[5329,8684]},{"ar":"كان الطيار في تشكيل الطائرات.","zh":"他是编队中的飞行员。","t":[8684,12053]},{"ar":"أكمل مهمات خطيرة فوق البحر الأبيض المتوسط، فوق الصحراء الكبرى.","zh":"他在地中海、撒哈拉上空完成了危险的飞行任务。","t":[12053,18697]},{"ar":"كان لديه العديد من الحوادث في وسط الصحراء.","zh":"他在沙漠中央遭遇了许多事故。","t":[18697,23118]},{"ar":"لاحقاً، عُين مدير شركته الجوية الخاصة في أمريكا الجنوبية.","zh":"后来，他成为南美自己航空公司的总监。","t":[23118,29526]},{"ar":"في هناك، أنهى العديد من المهمات الخطيرة فوق جبال الأنديز.","zh":"在那儿，他也在安第斯山脉上空完成了许多危险的任务。","t":[29526,34631]}]},{"id":"ch27p16","audio":"ch27p16.mp3","sents":[{"ar":"بالنسبة لعلي، الطيران لم يكن مجرد قيادة طائرة.","zh":"对圣埃克苏佩里而言，飞行不仅仅是驾驶飞机。","t":[103,5934]},{"ar":"كان يتأمل، يفكر في أمور.","zh":"也在沉思，在反思。","t":[5934,9697]},{"ar":"في أثناء مهماته، فكر أنطوان دو سانت إكزوبيري بعمق في العزلة، الصداقة، معنى الحياة، حالة الإنسان، والحرية.","zh":"在执行任务期间，圣埃克苏佩里深刻思考着孤独、友谊、生命的意义、人的境遇和自由。","t":[9697,21197]},{"ar":"نشر تفكيراته.","zh":"他发表了反思。","t":[21197,23539]},{"ar":"كتبه فور نجاحه","zh":"他的书籍立刻大获成功。","t":[23539,25237]}]},{"id":"ch27p17","audio":"ch27p17.mp3","sents":[{"ar":"للأسف، كانت الشركة الجوية التي عمل فيها سانت-إكزوبيري تواجه مشاكل مالية خطيرة.","zh":"不幸的是，圣埃克苏佩里供职的航空公司正面临严重的财务困境。","t":[103,8526]},{"ar":"كان لابد من أن يترك الشركة سانت-إكزوبيري.","zh":"圣埃克苏佩里不得不离开公司。","t":[8526,12895]},{"ar":"أصبح صحفيًا","zh":"他成为一名记者。","t":[12895,14105]},{"ar":"ذهب إلى إسبانيا وروسيا وألمانيا.","zh":"他游历过西班牙、俄罗斯和德国。","t":[14105,17803]},{"ar":"عندما كان يستطيع، سافر.","zh":"他一有机会就飞行。","t":[17803,20250]}]},{"id":"ch27p18","audio":"ch27p18.mp3","sents":[{"ar":"، فرنسا ذهبت إلى الحرب مع ألمانيا.","zh":"1939年，法国与德国开战。","t":[103,3697]},{"ar":"أنطوان دو سانت إكزوبيري انضم فورًا إلى الجيش.","zh":"圣埃克苏佩里立刻应征入伍。","t":[3697,8474]},{"ar":"الخسارة جاءت سريعًا.","zh":"败局随之而至。","t":[8474,11382]},{"ar":"فرنسا وقعت تحت سيطرة جيش هتلر.","zh":"法国沦陷于希特勒的军队之手。","t":[11382,14526]}]},{"id":"ch27p19","audio":"ch27p19.mp3","sents":[{"ar":"لم يرضخ الأمير الصغير للهزيمة.","zh":"圣埃克苏佩里不接受失败。","t":[103,3566]},{"ar":"قرر أن يغادر فرنسا.","zh":"他决定离开法国。","t":[3566,6474]},{"ar":"استقر في الولايات المتحدة حيث استمر في الكتابة.","zh":"他在美国定居，继续写作。","t":[6474,11197]},{"ar":"في نيويورك نشر الأُمير الصغير كتابه الشهير الصغير، من أبرز أعماله.","zh":"在纽约，他出版了《小王子》，这是他最著名的作品之一。","t":[11197,16710]}]},{"id":"ch27p20","audio":"ch27p20.mp3","sents":[{"ar":"، قوات الجيش الأمريكي هبطت في شمال أفريقيا.","zh":"1942年，美军在北非登陆。","t":[103,4461]},{"ar":"قرر أنطوان دو سانت إكزوبيري الانضمام إلى الجيش الأمريكي.","zh":"圣埃克苏佩里决定加入美国军队。","t":[4461,9829]},{"ar":"عندما بلغت الأربعين وثمانية عشر عامًا، التطوع ليكون طيارًا.","zh":"四十二岁时，他志愿成为了一名飞行员。","t":[9829,16645]},{"ar":"كان قد أخبروه بأنه كبير في السن.","zh":"他被告知自己年纪太大。","t":[16645,20579]},{"ar":"استمرّ.","zh":"他坚持不懈。","t":[20579,22329]},{"ar":"أخيرًا حصل على الرضا.","zh":"终于，他得到了满足。","t":[22329,25105]},{"ar":"تم منحي طائرة.","zh":"他得到了一架飞机。","t":[25105,27474]},{"ar":"أكمل العديد من المهمات فوق فرنسا المحتلة.","zh":"他在被占领的法国上空完成了许多任务。","t":[27474,31158]}]},{"id":"ch27p21","audio":"ch27p21.mp3","sents":[{"ar":"في 31 يوليو 1944، غادر أنطوان دو سانت إكزوبيري مهمته الأخيرة.","zh":"1944年7月31日，圣埃克苏佩里踏上他最后的使命。","t":[103,10487]},{"ar":"طائرة الأمير الصغير تم تدميرها من قبل الألمان فوق البحر الأبيض المتوسط.","zh":"他的飞机在地中海上空被德国人摧毁。","t":[10487,17434]},{"ar":"في ذلك اليوم، لم يرجع أنطوان دو سانت إكزوبيري...","zh":"那天，圣埃克苏佩里未能归来……","t":[17434,22421]},{"ar":"في السماء العريضة، وجد الخطر والموت والشهرازة.","zh":"在辽阔的天际，他觅得风险、死亡与荣耀。","t":[22421,26737]}]}]}]};